import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation: key=(donor_id, recipient_id), value=list of (action) observed
        self.history = {}  # (donor, recipient) -> list of donor actions (True=C, False=D)
        # Track own interactions per opponent to avoid punishing too harshly
        self.own_interactions = {}  # (self_id, opp_id) -> list of (my_action, opp_action)
        # Track defection counts per agent (as donor) globally
        self.defect_count = {}  # agent_id -> int
        self.coop_count = {}   # agent_id -> int
        # Track personal trust scores for each opponent
        self.trust = {}  # opponent_id -> float (0 to 1)
        # Generation tracking (optional, but useful)
        self.round_num = 0
        self.generation = 0
        # Opponent id set by framework
        self._ctx_opponent_id = None

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False  # defect as safe default
        # If we have no history with this opponent, start with cooperate (optimistic)
        if opp not in self.trust:
            # Check global reputation: if opponent has high defection rate, defect
            total_actions = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total_actions > 0:
                def_rate = self.defect_count.get(opp, 0) / total_actions
                if def_rate > 0.3:
                    self.trust[opp] = 0.2
                else:
                    self.trust[opp] = 0.8
            else:
                self.trust[opp] = 0.7
        # If we have personal history, adjust trust based on reciprocity
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if my_actions and opp_actions:
                # If opponent cooperated more than 50% of time and we cooperated, increase trust
                opp_coop_rate = sum(opp_actions) / len(opp_actions)
                my_coop_rate = sum(my_actions) / len(my_actions)
                # Tit-for-tat style: if opponent cooperated last time, trust them a bit
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.1)
                else:
                    self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
                # Also consider overall reciprocity
                if opp_coop_rate > 0.7 and my_coop_rate > 0.7:
                    self.trust[opp] = min(1.0, self.trust[opp] + 0.05)
        # Decide based on trust threshold
        if self.trust.get(opp, 0.5) >= 0.5:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Convert action strings to booleans
        d_act = (donor_action == 'cooperate')
        r_act = (recipient_action == 'cooperate')
        # Update global counts
        if donor_id not in self.defect_count:
            self.defect_count[donor_id] = 0
            self.coop_count[donor_id] = 0
        if d_act:
            self.coop_count[donor_id] += 1
        else:
            self.defect_count[donor_id] += 1
        # Track per-pair history
        key = (donor_id, recipient_id)
        if key not in self.history:
            self.history[key] = []
        self.history[key].append(d_act)
        # Track own interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            own_key = (self.agent_id, other)
            if own_key not in self.own_interactions:
                self.own_interactions[own_key] = []
            # For self as donor, we know our action; for self as recipient, we infer our action from recipient_action
            if donor_id == self.agent_id:
                my_act = d_act
                opp_act = r_act
            else:
                my_act = r_act
                opp_act = d_act
            self.own_interactions[own_key].append((my_act, opp_act))
            # Update trust based on this interaction if it involves us
            if len(self.own_interactions[own_key]) > 0:
                # Simple: if opponent defected against us, lower trust; if cooperated, raise
                if opp_act:
                    self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.1)
                else:
                    self.trust[other] = max(0.0, self.trust.get(other, 0.5) - 0.2)
        # Occasionally adjust trust based on third-party observations (reputation)
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # If donor defects often, lower trust for them
            total = self.defect_count.get(donor_id, 0) + self.coop_count.get(donor_id, 0)
            if total > 10:
                def_rate = self.defect_count.get(donor_id, 0) / total
                if def_rate > 0.6:
                    self.trust[donor_id] = min(self.trust.get(donor_id, 0.5), 0.2)
                elif def_rate < 0.3:
                    self.trust[donor_id] = max(self.trust.get(donor_id, 0.5), 0.7)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_history = {}  # opponent_id -> list of (my_action, opp_action)
        self.reputation = {}       # agent_id -> reputation score (higher = more cooperative)
        self.round = 0
        self.generation = 0
        self.my_actions = []
        self.opponent_ids_seen = set()
        # Learning parameters
        self.coop_threshold = 0.5  # Reputation threshold for cooperation
        self.trust_factor = 0.5    # How much we trust reputation
        self.defect_prob = 0.05    # Exploration probability

    def decide(self) -> bool:
        opp_id = self._ctx_opponent_id
        self.round += 1

        # If we haven't seen this opponent before, default to defect
        if opp_id not in self.opponent_history:
            self.opponent_ids_seen.add(opp_id)
            self.reputation.setdefault(opp_id, 0.5)
            # First encounter: be slightly cooperative if reputation is high
            if self.reputation.get(opp_id, 0.5) > 0.7:
                return True
            return False

        history = self.opponent_history[opp_id]
        if not history:
            return False

        # Compute opponent's cooperation rate
        coop_rate = sum(1 for a, b in history if b) / len(history)

        # Compute my payoff against this opponent
        my_payoff = 0
        for my_a, opp_a in history:
            if my_a and opp_a:
                my_payoff += 1
            elif my_a and not opp_a:
                my_payoff -= 1
            elif not my_a and opp_a:
                my_payoff += 2
            else:
                my_payoff += 0

        # Adaptive strategy based on opponent's behavior
        if coop_rate >= 0.6:
            # Opponent is cooperative, try cooperation with some probability
            if random.random() < self.trust_factor:
                return True
            else:
                return False
        elif coop_rate <= 0.2:
            # Opponent is defective, mostly defect
            return False
        else:
            # Mixed behavior: defect more often
            return random.random() < 0.3

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation scores
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.5
            # Update reputation with simple moving average
            if action == 'cooperate':
                self.reputation[agent_id] = self.reputation[agent_id] * 0.9 + 0.1
            else:
                self.reputation[agent_id] = self.reputation[agent_id] * 0.9 - 0.1
            # Clamp to [0,1]
            self.reputation[agent_id] = max(0.0, min(1.0, self.reputation[agent_id]))

        # Update opponent history for self-involved actions
        if donor_id == self.agent_id:
            opp_id = recipient_id
            my_action = donor_action == 'cooperate'
            opp_action = recipient_action == 'cooperate'
            self._update_history(opp_id, my_action, opp_action)
        elif recipient_id == self.agent_id:
            opp_id = donor_id
            my_action = recipient_action == 'cooperate'
            opp_action = donor_action == 'cooperate'
            self._update_history(opp_id, my_action, opp_action)

    def _update_history(self, opp_id: int, my_action: bool, opp_action: bool) -> None:
        if opp_id not in self.opponent_history:
            self.opponent_history[opp_id] = []
        self.opponent_history[opp_id].append((my_action, opp_action))
        # Keep history bounded to avoid memory issues
        if len(self.opponent_history[opp_id]) > 100:
            self.opponent_history[opp_id] = self.opponent_history[opp_id][-100:]

