class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track history of opponents' actions against us and others
        self.history = {}  # (opponent_id, round) -> action
        self.round = 0
        self.coop_count = 0
        self.defect_count = 0
        self.my_last_action = None
        self.opponent_last_action = None
        # Simple reputation: how cooperative each agent is overall
        self.reputation = {}  # agent_id -> [coop, total]
        # Track interactions: for each opponent, last few actions
        self.interactions = {}  # opponent_id -> list of (my_action, opp_action)
        # Randomness for occasional exploration
        self.explore_prob = 0.05

    def decide(self) -> bool:
        opp_id = self._ctx_opponent_id
        # If we have no history with this opponent, be cautious: cooperate initially
        if opp_id not in self.interactions or len(self.interactions[opp_id]) == 0:
            # Start with cooperation to test opponent
            return True

        # Analyze opponent's recent behavior (last 5 mutual interactions)
        recent = self.interactions[opp_id][-5:]
        opp_coop_rate = sum(1 for my, opp in recent if opp == 'cooperate') / len(recent)

        # If opponent cooperates a lot, cooperate; else defect
        if opp_coop_rate > 0.5:
            return True
        else:
            # Occasionally explore to avoid being too predictable
            if random.random() < self.explore_prob:
                return True
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round counter when we see our own action
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # If we are donor or recipient, record our action
            if donor_id == self.agent_id:
                self.my_last_action = donor_action
                # Update interaction with opponent
                if recipient_id in self.interactions:
                    self.interactions[recipient_id].append((donor_action, recipient_action))
                else:
                    self.interactions[recipient_id] = [(donor_action, recipient_action)]
                # Update reputation for opponent
                if recipient_id in self.reputation:
                    self.reputation[recipient_id][1] += 1
                    if recipient_action == 'cooperate':
                        self.reputation[recipient_id][0] += 1
                else:
                    self.reputation[recipient_id] = [1 if recipient_action == 'cooperate' else 0, 1]
            elif recipient_id == self.agent_id:
                self.opponent_last_action = recipient_action
                if donor_id in self.interactions:
                    self.interactions[donor_id].append((donor_action, recipient_action))
                else:
                    self.interactions[donor_id] = [(donor_action, recipient_action)]
                if donor_id in self.reputation:
                    self.reputation[donor_id][1] += 1
                    if donor_action == 'cooperate':
                        self.reputation[donor_id][0] += 1
                else:
                    self.reputation[donor_id] = [1 if donor_action == 'cooperate' else 0, 1]
        else:
            # Third-party observation: update reputation for both
            if donor_id in self.reputation:
                self.reputation[donor_id][1] += 1
                if donor_action == 'cooperate':
                    self.reputation[donor_id][0] += 1
            else:
                self.reputation[donor_id] = [1 if donor_action == 'cooperate' else 0, 1]

            if recipient_id in self.reputation:
                self.reputation[recipient_id][1] += 1
                if recipient_action == 'cooperate':
                    self.reputation[recipient_id][0] += 1
            else:
                self.reputation[recipient_id] = [1 if recipient_action == 'cooperate' else 0, 1]

        # Increment round counter when we observe our own actions (each round we see our own action once)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Only increment when we are donor (each round we are donor once)
            if donor_id == self.agent_id:
                self.round += 1

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_history = {}  # opponent_id -> list of actions ('C'/'D')
        self.my_actions = {}        # opponent_id -> list of my actions
        self.coop_counts = [0] * 15  # cooperate count per agent (for reputation)
        self.defect_counts = [0] * 15
        self.gen_round = 0
        self.generation = 0
        self.total_rounds = 0
        self.cooperation_threshold = 0.25  # initial threshold for trusting others
        self.memory_limit = 50  # keep last 50 interactions per opponent
        self.trust_scores = {}   # opponent_id -> trust score (0 to 1)
        self.coop_frequency = 0.5  # overall cooperation rate to adapt
        self.rounds_played = 0
        self.generations_played = 0

    def _record_action(self, opponent_id: int, my_action: bool, opp_action: bool):
        # Update history and counts
        if opponent_id not in self.opponent_history:
            self.opponent_history[opponent_id] = []
            self.my_actions[opponent_id] = []
        self.opponent_history[opponent_id].append('C' if opp_action else 'D')
        self.my_actions[opponent_id].append('C' if my_action else 'D')
        # Keep memory limit
        if len(self.opponent_history[opponent_id]) > self.memory_limit:
            self.opponent_history[opponent_id].pop(0)
            self.my_actions[opponent_id].pop(0)
        # Update counts for reputation
        if opp_action:
            self.coop_counts[opponent_id] += 1
        else:
            self.defect_counts[opponent_id] += 1
        # Update trust score (simple moving average)
        total = self.coop_counts[opponent_id] + self.defect_counts[opponent_id]
        if total > 0:
            self.trust_scores[opponent_id] = self.coop_counts[opponent_id] / total

    def _decide_against(self, opponent_id: int) -> bool:
        # Core strategy logic
        if opponent_id not in self.opponent_history:
            # No history: be cautious but slightly cooperative to probe
            return random.random() < 0.4  # 40% chance to cooperate initially
        opp_hist = self.opponent_history[opponent_id]
        my_actions = self.my_actions.get(opponent_id, [])
        n = len(opp_hist)
        if n == 0:
            return False

        # Compute opponent cooperation rate
        coop_rate = sum(1 for a in opp_hist if a == 'C') / n

        # Trust score from overall counts
        trust = self.trust_scores.get(opponent_id, 0.5)

        # Adaptive threshold: lower if overall cooperation is low (to exploit defectors)
        threshold = self.cooperation_threshold
        if self.rounds_played > 0:
            # Adjust threshold based on my recent success? Use overall coop frequency
            threshold = max(0.1, min(0.9, self.coop_frequency * 0.8 + 0.1))

        # Use a forgiving tit-for-tat with noise tolerance
        if n >= 1 and opp_hist[-1] == 'C':
            # If opponent cooperated last time, cooperate if they are generally cooperative
            if coop_rate > threshold or trust > threshold:
                return True
            else:
                # Even if last was C, if they are overall bad, defect
                return False
        else:
            # Opponent defected last time or unknown: defect unless very high trust
            if trust > 0.8 and coop_rate > 0.7:
                return True
            else:
                return False

    def decide(self) -> bool:
        # Get opponent id from context
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
            return False
        # Occasionally explore with small probability to learn
        if random.random() < 0.02:
            return random.random() < 0.5
        return self._decide_against(opp)

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update counts for all agents (reputation tracking)
        if donor_id < 15:
            if donor_action == 'cooperate':
                self.coop_counts[donor_id] += 1
            else:
                self.defect_counts[donor_id] += 1
        if recipient_id < 15:
            if recipient_action == 'cooperate':
                self.coop_counts[recipient_id] += 1
            else:
                self.defect_counts[recipient_id] += 1

        # Update trust scores for observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id < 15:
                total = self.coop_counts[agent_id] + self.defect_counts[agent_id]
                if total > 0:
                    self.trust_scores[agent_id] = self.coop_counts[agent_id] / total

        # If this is my own action, record it for my history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent and actions
            if donor_id == self.agent_id:
                opp = recipient_id
                my_action = donor_action == 'cooperate'
                opp_action = recipient_action == 'cooperate'
            else:
                opp = donor_id
                my_action = recipient_action == 'cooperate'
                opp_action = donor_action == 'cooperate'
            self._record_action(opp, my_action, opp_action)
            self.rounds_played += 1

        # Update overall cooperation frequency based on observations
        total_obs = self.coop_counts[self.agent_id] + self.defect_counts[self.agent_id]
        if total_obs > 0:
            self.coop_frequency = self.coop_counts[self.agent_id] / total_obs

    # Additional helper to reset per generation if needed (optional)
    def reset_generation(self):
        self.gen_round = 0
        # Keep histories but maybe decay trust? Not needed.

