import math

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.history = {}  # opponent_id -> list of (my_action, opp_action)
        self.reputation = {}  # agent_id -> accumulated score
        self.my_recent_actions = []
        self.generation = 0
        self.round = 0
        self.coop_threshold = 0.3  # initial threshold for trusting others
        self.defect_threshold = -0.5
        self.memory = 10  # keep last N interactions per opponent
        self.trust = {}  # opponent_id -> trust value
        self.observed_actions = {}  # (donor, recipient) -> last action
        self.cooperation_score = {}  # agent_id -> cooperation rate
        self.total_interactions = {}  # agent_id -> count

    def decide(self) -> bool:
        if self.opponent_id is None:
            return False  # default defect if no opponent
        # If we have no history with this opponent, defect (stranger danger)
        if self.opponent_id not in self.history or len(self.history[self.opponent_id]) < 2:
            return False
        # Look at opponent's recent behavior globally (reputation)
        opp_coop_rate = self.get_cooperation_rate(self.opponent_id)
        # If opponent cooperates often, cooperate with some probability based on trust
        if opp_coop_rate > 0.6:
            # Trustworthy - cooperate unless we have reason to defect
            if self.opponent_id in self.history:
                recent = self.history[self.opponent_id][-self.memory:]
                # If opponent defected recently against us, punish
                if any(action == 'defect' for _, action in recent[-3:]):
                    return False
                # Otherwise cooperate
                return True
            else:
                return False
        else:
            # Opponent is not cooperative overall - defect
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global reputation scores
        # Cooperation is good, defection is bad
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 0.5
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 0.5
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + 0.2
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) - 0.2

        # Record observation for cooperation rate
        self.total_interactions[donor_id] = self.total_interactions.get(donor_id, 0) + 1
        if donor_action == 'cooperate':
            self.cooperation_score[donor_id] = self.cooperation_score.get(donor_id, 0) + 1
        # If this is about us, record our own action
        if donor_id == self.agent_id:
            self.my_recent_actions.append(donor_action)
            if len(self.my_recent_actions) > 100:
                self.my_recent_actions.pop(0)
        # If this is about our opponent, update their history if we are involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # This is our own interaction - update opponent history
            if donor_id == self.agent_id:
                opp = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opp = donor_id
                my_action = recipient_action
                opp_action = donor_action
            if opp not in self.history:
                self.history[opp] = []
            self.history[opp].append((my_action, opp_action))
            if len(self.history[opp]) > 200:
                self.history[opp].pop(0)

    def get_cooperation_rate(self, agent_id: int) -> float:
        total = self.total_interactions.get(agent_id, 0)
        if total == 0:
            return 0.0
        coop = self.cooperation_score.get(agent_id, 0)
        return coop / total

