                recent = self.history[self.opponent_id][-self.memory:]
                # If opponent defected recently against us, punish
                if any(action == 'defect' for _, action in recent[-3:]):
                    return False
                # Otherwise cooperate
                return True
            else:
                return False
        else:
            # Opponent is not cooperative overall - defect
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global reputation scores
        # Cooperation is good, defection is bad
        if donor_action == 'cooperate':
