        self.exploit_threshold = 0.3
        self.defect_penalty = 0.2
        self.coop_bonus = 0.1
        self.reputation_weight = 0.3
        self.personal_weight = 0.7
        self.reputation_floor = 0.2
        self.reputation_boost = 0.1
        self.reputation_penalty = 0.1
        self.high_rep_threshold = 0.7
        self.low_rep_threshold = 0.3

