                if my_def < 10:
                    self.my_defections[self.opponent_id] = my_def + 1
                    return False
                else:
                    return True
            else:
                # Need reputation - cooperate to build it
                return True

        # Moderately cooperative - defect selectively based on streak
        if coop_rate >= 0.5:
            if self.consecutive_coop >= 2:
                # They're in a cooperative streak - exploit
                if my_reputation > 0.3:
                    self.my_defections[self.opponent_id] = my_def + 1
                    return False
                else:
                    return True
            else:
                # Mixed - defect if we have reputation buffer
                if my_reputation > 0.4:
                    return random.random() < 0.5  # 50% defect
                else:
                    return True

        # Defecting opponent - use tit-for-tat with occasional cooperation for reputation
        if coop_rate < 0.3:
            if self.opp_defect_streak.get(self.opponent_id, 0) >= 3:
                # They're in a defection streak - defect back
                return False
            else:
                # They might be about to cooperate - cooperate sometimes
                if my_reputation < 0.25:
                    self.build_reputation = True
                    return True
                return random.random() < 0.2  # 20% cooperate

        # Mixed behavior (0.3-0.5)
        if self.consecutive_coop >= 2:
            return False  # exploit their cooperation
        else:
            if my_reputation < 0.3:
                return True  # need reputation
            return random.random() < 0.25  # 25% cooperate

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Reputation updates - asymmetric weight: donors judged more harshly
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + 0.12
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - 0.18

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + 0.08
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - 0.08

        for aid in [donor_id, recipient_id]:
            if aid in self.reputation:
                self.reputation[aid] = max(0.0, min(1.0, self.reputation[aid]))

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            if opp_id not in self.history:
                self.history[opp_id] = []
            self.history[opp_id].append((my_action, opp_action))

            if opp_id not in self.recent_actions:
                self.recent_actions[opp_id] = []
            self.recent_actions[opp_id].append(opp_action)
            if len(self.recent_actions[opp_id]) > 20:
                self.recent_actions[opp_id].pop(0)

            if opp_id not in self.coop_counts:
