                self.defect_counts[opp_id] = 0
            if opp_action == 'cooperate':
                self.coop_counts[opp_id] += 1
            else:
                self.defect_counts[opp_id] += 1

        if donor_id == self.agent_id:
            self.my_actions.append(donor_action)
            if donor_action == 'defect':
