            self.scores[opp] = 0.0
            self.trust[opp] = self.initial_coop_bias
            self.partner_history[opp] = []

        if len(self.opp_actions[opp]) > 0:
            personal_coop_rate = self.coop_counts[opp] / len(self.opp_actions[opp])
        else:
            personal_coop_rate = self.initial_coop_bias

        rep = self.reputation.get(opp, self.neutral_reputation)

        combined_trust = self.personal_weight * personal_coop_rate + self.reputation_weight * rep

        expected_coop = combined_trust
        expected_defect = 1 - expected_coop

        coop_payoff = expected_coop * 1 + expected_defect * (-1)
        defect_payoff = expected_coop * 2 + expected_defect * 0

        if random.random() < self.exploration_rate:
            return random.random() < 0.5

        # Exploit high reputation cooperators aggressively
        if rep >= self.high_rep_threshold and personal_coop_rate >= 0.6:
            # They are very likely to cooperate, defect to get T=2
            return False

        # If opponent has low reputation, defect to avoid being exploited
        if rep <= self.low_rep_threshold:
            return False

        # If we can get away with defecting against medium reputation without hurting own rep too much
        if rep >= 0.5 and rep < self.high_rep_threshold and personal_coop_rate >= 0.7:
            # They cooperate often but not as high rep, exploit them too
            return False

        # Otherwise, base decision on trust threshold
        if combined_trust >= self.coop_threshold:
