            if any(action == 'defect' for _, action in recent):
                return False
        # Check global reputation: if opponent cooperates often, cooperate
        opp_coop_rate = self.get_cooperation_rate(self.opponent_id)
        # If opponent cooperates often AND hasn't defected against us recently, cooperate
        if opp_coop_rate > 0.6:
            return True
        # If opponent has low cooperation rate but hasn't defected against us, sometimes take risk
        if opp_coop_rate > 0.4 and self.opponent_id in self.opponent_defect_streak:
            if self.opponent_defect_streak[self.opponent_id] == 0:
                # Risk tolerance: cooperate with some probability if they seem decent
                if random.random() < 0.5:
                    return True
        return False

