            recent_coop_rate = personal_coop_rate

        # If opponent has been cooperating recently and reputation is decent, exploit them
        if recent_coop_rate > 0.6 and rep > 0.5:
            # But check my own recent defect rate to not over-exploit
            if self.my_defect_rate < 0.7:  # Don't defect too often overall
                # Occasionally exploit, but with increasing probability if it works
                if self.total_exploit_attempts > 0:
                    success_rate = self.exploit_successes / self.total_exploit_attempts
                else:
                    success_rate = 0.5
                if random.random() < (0.5 + 0.5 * success_rate):
                    self.interaction_count += 1
                    self.total_exploit_attempts += 1
                    return False  # Defect to exploit

        # If opponent has low reputation, defect to avoid being exploited
        if rep <= self.low_rep_threshold:
            return False

        # Otherwise, base decision on trust threshold with a slight tilt toward defection
        if combined_trust >= self.coop_threshold:
            # Occasionally defect if payoff advantage is high enough
            if defect_payoff > coop_payoff + 0.2:
                return False
            return True
        else:
            # More likely to defect when trust is low
            if defect_payoff > coop_payoff - 0.1:
                return False
            else:
                return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation with dynamic boosting/penalizing
        if donor_id not in self.reputation:
            self.reputation[donor_id] = self.neutral_reputation
        if recipient_id not in self.reputation:
            self.reputation[recipient_id] = self.neutral_reputation

        if donor_action == 'cooperate':
            # Cooperating boosts reputation, especially against defectors
            if recipient_action == 'defect':
                self.reputation[donor_id] += self.reputation_boost * 1.8
            else:
                self.reputation[donor_id] += self.reputation_boost
        else:
            # Defecting hurts reputation, especially against cooperators
            if recipient_action == 'cooperate':
                self.reputation[donor_id] -= self.reputation_penalty * 1.8
            else:
                self.reputation[donor_id] -= self.reputation_penalty

        # Clamp reputation
        self.reputation[donor_id] = max(0, min(1, self.reputation[donor_id]))

        # Update personal history if it involves us
        if donor_id == self.agent_id:
            self.my_actions.setdefault(recipient_id, []).append(donor_action)
            self.opp_actions.setdefault(recipient_id, []).append(recipient_action)
            if donor_action == 'cooperate':
                self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + 1
            else:
                self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + 1
            self.partner_history.setdefault(recipient_id, []).append((donor_action, recipient_action))
            # Track my own actions for defect rate
            self.recent_actions.setdefault(recipient_id, []).append(donor_action)
            if len(self.recent_actions[recipient_id]) > self.window_size:
                self.recent_actions[recipient_id] = self.recent_actions[recipient_id][-self.window_size:]
            # Update overall defect rate
            all_my_actions = [a for a, b in self.partner_history.get(recipient_id, [])]
            if len(all_my_actions) > 0:
                self.my_defect_rate = all_my_actions.count('defect') / len(all_my_actions)
        elif recipient_id == self.agent_id:
            self.my_actions.setdefault(donor_id, []).append(recipient_action)
            self.opp_actions.setdefault(donor_id, []).append(donor_action)
            if recipient_action == 'cooperate':
                self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + 1
            else:
                self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + 1
            self.partner_history.setdefault(donor_id, []).append((recipient_action, donor_action))
            # Track opponent's recent actions for exploitation
            self.recent_actions.setdefault(donor_id, []).append(recipient_action)
            if len(self.recent_actions[donor_id]) > self.window_size:
                self.recent_actions[donor_id] = self.recent_actions[donor_id][-self.window_size:]

        # Keep only recent memory
        for opp in list(self.partner_history.keys()):
            if len(self.partner_history[opp]) > self.memory:
                self.partner_history[opp] = self.partner_history[opp][-self.memory:]
                coop = sum(1 for a, b in self.partner_history[opp] if a == 'cooperate')
                defect = sum(1 for a, b in self.partner_history[opp] if a == 'defect')
                self.coop_counts[opp] = coop
                self.defect_counts[opp] = defect
                self.opp_actions[opp] = [b for a, b in self.partner_history[opp]]
                self.my_actions[opp] = [a for a, b in self.partner_history[opp]]

        # Update trust and exploit success tracking
        for opp in self.partner_history:
            if len(self.partner_history[opp]) > 0:
                opp_coop = sum(1 for a, b in self.partner_history[opp] if b == 'cooperate') / len(self.partner_history[opp])
                rep = self.reputation.get(opp, self.neutral_reputation)
                self.trust[opp] = self.personal_weight * opp_coop + self.reputation_weight * rep
                # Track exploit success: if we defected and opponent cooperated, it was successful
                my_actions_list = self.my_actions.get(opp, [])
                opp_actions_list = self.opp_actions.get(opp, [])
                for i in range(len(my_actions_list)):
                    if my_actions_list[i] == 'defect' and opp_actions_list[i] == 'cooperate':
                        self.exploit_successes += 1
            else:
                rep = self.reputation.get(opp, self.neutral_reputation)
                self.trust[opp] = self.reputation_weight * rep + (1 - self.reputation_weight) * self.initial_coop_bias

