        self.recent_opponent_actions = {}  # opp_id -> list of their actions in last few rounds
        self.last_opponent = None

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False

        # Get opponent's history from public observations
        as_donor = self.obs_as_donor.get(opp, [])
        as_recipient = self.obs_as_recipient.get(opp, [])
        total_obs = len(as_donor) + len(as_recipient)

        # If very few observations, defect to avoid exploitation
        if total_obs < 3:
            return False

        # Compute cooperation rate in both roles
        coop_count = as_donor.count('cooperate') + as_recipient.count('cooperate')
        coop_rate = coop_count / total_obs

        # Also check recent behavior (last 5 actions) to detect changes
        recent_actions = (as_donor[-5:] + as_recipient[-5:])
        if recent_actions:
            recent_coop_rate = recent_actions.count('cooperate') / len(recent_actions)
        else:
            recent_coop_rate = 0.0

        # Strategy: cooperate only if opponent shows strong and consistent cooperation
        # Use both overall and recent rates, with a bias towards recent
        if total_obs >= 5:
            if coop_rate > 0.8 and recent_coop_rate > 0.6:
                return True
            elif coop_rate > 0.9 and recent_coop_rate > 0.5:
                return True
            elif coop_rate > 0.7 and recent_coop_rate > 0.7:
                return True
        return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Record all public observations
        if donor_id != self.agent_id:
            if donor_id not in self.obs_as_donor:
                self.obs_as_donor[donor_id] = []
            self.obs_as_donor[donor_id].append(donor_action)
        if recipient_id != self.agent_id:
            if recipient_id not in self.obs_as_recipient:
                self.obs_as_recipient[recipient_id] = []
            self.obs_as_recipient[recipient_id].append(recipient_action)

        # Track own actions and payoff
        my_action = None
        if donor_id == self.agent_id:
            my_action = donor_action
            self.my_actions.append(donor_action)
            if donor_action == 'cooperate':
                self.my_total_coop += 1
            else:
                self.my_total_def += 1
        if recipient_id == self.agent_id:
            my_action = recipient_action
            self.my_actions.append(recipient_action)
            if recipient_action == 'cooperate':
                self.my_total_coop += 1
            else:
                self.my_total_def += 1

        # Update payoff based on my action and opponent's action
        if my_action is not None:
            opp_action = None
            if donor_id == self.agent_id:
                opp_action = recipient_action
            elif recipient_id == self.agent_id:
                opp_action = donor_action
            if opp_action is not None:
                if my_action == 'cooperate' and opp_action == 'cooperate':
                    self.payoff_sum += 1
                elif my_action == 'cooperate' and opp_action == 'defect':
                    self.payoff_sum -= 1
                elif my_action == 'defect' and opp_action == 'cooperate':
