        self.generation = 0
        self.rounds_played = 0
        self.total_rounds_per_gen = 143
        self.num_agents = 15
        self.coop_counts = {}
        self.defect_counts = {}
        self.recent_actions = {}
        self.round_index = 0
        self.my_actions = []
        self.coop_threshold = 0.7
        self.memory = 15
        self.defect_rounds = 0
        self.last_opponent = None
        self.consecutive_coop = 0
        self.build_reputation = False
        self.build_rounds = 0
        self.my_defections = {}
        self.opp_defect_streak = {}
        self.first_encounter = True
        self.initial_defect = False
        self.defect_after_coop = 0
        self.reputation_boost_cooldown = 0

    def decide(self) -> bool:
        if self.opponent_id is None:
            return False

        self.round_index += 1
        self.rounds_played += 1

        if self.round_index % self.total_rounds_per_gen == 0:
            self.generation += 1
            self.round_index = 0
            self.rounds_played = 0
            self.build_reputation = False
            self.build_rounds = 0
            self.first_encounter = True
            self.initial_defect = False

        opp_history = self.history.get(self.opponent_id, [])

        if len(opp_history) < 2:
            if self.first_encounter:
                self.first_encounter = False
                # Start with cooperation to build reputation
                return True
            else:
                # If they've defected at first, defect back
                if opp_history and opp_history[-1][1] == 'defect':
                    return False
                return True

        recent = opp_history[-self.memory:]
        if not recent:
            return False
        coop_count = sum(1 for _, opp_act in recent if opp_act == 'cooperate')
        coop_rate = coop_count / len(recent)

        opp_reputation = self.reputation.get(self.opponent_id, 0.5)
        my_reputation = self.reputation.get(self.agent_id, 0.5)

        if self.last_opponent == self.opponent_id:
            if recent and recent[-1][1] == 'cooperate':
                self.consecutive_coop += 1
            else:
                self.consecutive_coop = 0
        else:
            self.consecutive_coop = 0
        self.last_opponent = self.opponent_id

        if recent and recent[-1][1] == 'defect':
            self.opp_defect_streak[self.opponent_id] = self.opp_defect_streak.get(self.opponent_id, 0) + 1
        else:
            self.opp_defect_streak[self.opponent_id] = 0

        if self.build_reputation:
            self.build_rounds += 1
            if self.build_rounds > 3:
                self.build_reputation = False
                self.build_rounds = 0
            return True

        my_def = self.my_defections.get(self.opponent_id, 0)

        # If we have high reputation, we can defect more
        if my_reputation > 0.7:
            # Exploit highly cooperative opponents
            if coop_rate > 0.6:
                if my_def < 12:
                    self.my_defections[self.opponent_id] = my_def + 1
                    return False
                else:
                    return True
            # Against defectors, defect but occasionally cooperate to keep reputation
            if coop_rate < 0.3:
                if self.opp_defect_streak.get(self.opponent_id, 0) >= 2:
                    return False
                else:
                    return random.random() < 0.15
            # Medium cooperators - defect if streak
            if self.consecutive_coop >= 2:
                self.my_defections[self.opponent_id] = my_def + 1
                return False
            return random.random() < 0.5

        # Need to build reputation
        if my_reputation < 0.3:
            # Cooperate to boost reputation
            return True

        # Moderate reputation - balance
        if coop_rate > 0.8:
            # They're very cooperative - exploit but not too much
            if my_def < 6:
                self.my_defections[self.opponent_id] = my_def + 1
                return False
            return True
        elif coop_rate >= 0.5:
            if self.consecutive_coop >= 2:
                self.my_defections[self.opponent_id] = my_def + 1
                return False
            else:
                return random.random() < 0.4
        elif coop_rate < 0.3:
            if self.opp_defect_streak.get(self.opponent_id, 0) >= 3:
                return False
            return random.random() < 0.3
        else:
            if self.consecutive_coop >= 1:
                return False
            return random.random() < 0.35

    def observe(
        self,
