        # Get current trust score
        trust_score = self.trust.get(opp, 0.5)

        # Analyze recent behavior patterns
        recent = self.recent_actions.get(opp, [])
        if len(recent) >= 3:
            # If opponent has been cooperating consistently, keep cooperating to build mutual trust
            # But if they suddenly defect, defect immediately (forgiving tit-for-tat)
            if recent[-1] == False:
                return False
            # If opponent has a long cooperation streak, continue cooperating
            if self.cooperation_streak.get(opp, 0) >= 4:
                return True
            # If opponent has a long defection streak, defect
            if self.defection_streak.get(opp, 0) >= 2:
                return False

        # Use trust threshold with some randomness to avoid being exploited
        if trust_score >= 0.65:
            return True
        elif trust_score <= 0.35:
            return False
        else:
            # In the uncertain zone, use a probabilistic approach
            # Slightly bias towards cooperation if we've been cooperating with them
            key = (self.agent_id, opp)
            if key in self.own_interactions:
                my_actions = [a[0] for a in self.own_interactions[key]]
                if my_actions and my_actions[-1]:
