        # Track my reputation as seen by others (approximate)
        self.my_reputation = 0.5  # initial neutral

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False

        # Get opponent's overall cooperation rate from public observations
        as_donor = self.obs_as_donor.get(opp, [])
        as_recipient = self.obs_as_recipient.get(opp, [])
        total_obs = len(as_donor) + len(as_recipient)
        if total_obs == 0:
            # No info: defect to be safe
            return False

        coop_count = as_donor.count('cooperate') + as_recipient.count('cooperate')
        coop_rate = coop_count / total_obs

        # Also check my own interaction history with this opponent
        my_interactions = self.interactions.get(opp, [])
        my_coop_times = sum(1 for my, opp_action in my_interactions if my == 'cooperate')
        my_def_times = sum(1 for my, opp_action in my_interactions if my == 'defect')

        # Strategy:
        # 1. If opponent has high cooperation rate (>0.6) and enough data, cooperate to gain mutual benefit.
        # 2. If opponent is mostly defecting, defect.
        # 3. To exploit naive cooperators, if they are very cooperative (>0.8) but I haven't defected much against them recently, defect to exploit them.
        # 4. However, to maintain reputation, occasionally cooperate with highly cooperative opponents.

        if total_obs < 3:
            # Not enough data: defect
            return False

