        opp_def_against_me = sum(1 for my, opp_action in my_interactions if opp_action == 'defect')
        opp_coop_against_me = sum(1 for my, opp_action in my_interactions if opp_action == 'cooperate')

        if opp_def_against_me > 0 and opp_def_against_me / max(1, len(my_interactions)) > 0.3:
            # Retaliatory opponent: cooperate if they are cooperative overall, else defect
            if coop_rate > 0.6 and self.reputation > 0.4:
                return True
            return False

        # If opponent is very cooperative and hasn't retaliated much, exploit
        if coop_rate > 0.75 and opp_def_against_me / max(1, len(my_interactions)) < 0.2:
            # But don't over-exploit to maintain reputation
            if self.reputation > 0.7:
                return False  # defect to exploit
            else:
                # Occasionally cooperate to boost reputation
                if random.random() < 0.2:
