        # Strategy: cooperate only if opponent shows strong and consistent cooperation
        # Use both overall and recent rates, with a bias towards recent
        if total_obs >= 5:
            if coop_rate > 0.8 and recent_coop_rate > 0.6:
                return True
            elif coop_rate > 0.9 and recent_coop_rate > 0.5:
                return True
            elif coop_rate > 0.7 and recent_coop_rate > 0.7:
                return True
        return False

