    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.history = {}
        self.own_interactions = {}
        self.defect_count = {}
        self.coop_count = {}
        self.trust = {}
        self.round_num = 0
        self.generation = 0
        self._ctx_opponent_id = None
        # Track recent opponent actions for adaptive strategy
        self.recent_opp_actions = {}  # opp_id -> list of last 3 actions (True=C, False=D)
        # Track how many times we cooperated with each opponent
        self.coops_with = {}
        # Track opponent's recent defection streak
        self.opp_def_streak = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.2
                elif def_rate < 0.2:
                    self.trust[opp] = 0.8
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                # Tit-for-tat with forgiveness: cooperate if opponent cooperated last time
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.15)
                else:
                    # If opponent defected, check streak
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.1)
        # Exploit cooperators: if opponent has high coop rate but low defections against us, cooperate more
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 20:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.1:
                # Generous cooperator - exploit by always cooperating to keep them cooperating
                self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
            elif def_rate > 0.7:
                # Chronic defector - defect always
                self.trust[opp] = 0.0
        # Decision threshold: cooperate if trust >= 0.45 (slightly more aggressive)
        return self.trust.get(opp, 0.5) >= 0.45

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        d_act = (donor_action == 'cooperate')
        r_act = (recipient_action == 'cooperate')
        # Update global counts
        if donor_id not in self.defect_count:
            self.defect_count[donor_id] = 0
            self.coop_count[donor_id] = 0
        if d_act:
            self.coop_count[donor_id] += 1
        else:
            self.defect_count[donor_id] += 1
        # Track per-pair history
        key = (donor_id, recipient_id)
        if key not in self.history:
            self.history[key] = []
        self.history[key].append(d_act)
        # Track own interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            own_key = (self.agent_id, other)
            if own_key not in self.own_interactions:
                self.own_interactions[own_key] = []
            if donor_id == self.agent_id:
                my_act = d_act
                opp_act = r_act
            else:
                my_act = r_act
                opp_act = d_act
            self.own_interactions[own_key].append((my_act, opp_act))
            # Update recent opponent actions
            if other not in self.recent_opp_actions:
                self.recent_opp_actions[other] = []
            self.recent_opp_actions[other].append(opp_act)
            if len(self.recent_opp_actions[other]) > 3:
                self.recent_opp_actions[other] = self.recent_opp_actions[other][-3:]
            # Update defection streak
            if opp_act:
                self.opp_def_streak[other] = 0
            else:
                self.opp_def_streak[other] = self.opp_def_streak.get(other, 0) + 1
            # Update trust based on this interaction
            if opp_act:
                self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.12)
            else:
                # If opponent defected, lower trust more if they have a streak
                streak = self.opp_def_streak.get(other, 0)
                penalty = 0.15 if streak >= 2 else 0.08
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - penalty)
        # Third-party reputation: but be less harsh to avoid over-penalizing
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            total = self.defect_count.get(donor_id, 0) + self.coop_count.get(donor_id, 0)
            if total > 30:
                def_rate = self.defect_count.get(donor_id, 0) / total
                if def_rate > 0.8:
                    self.trust[donor_id] = min(self.trust.get(donor_id, 0.5), 0.1)
                elif def_rate < 0.1:
                    self.trust[donor_id] = max(self.trust.get(donor_id, 0.5), 0.8)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.round_num = 0
        # Track observations for each agent: as donor and as recipient
        self.obs_as_donor = {}
        self.obs_as_recipient = {}
        # Track interactions with each opponent: their action vs mine
        self.interactions = {}  # opp_id -> list of (my_action, opp_action)
        # Track my total cooperation/defection counts
        self.my_total_coop = 0
        self.my_total_def = 0
        # Track my recent actions for reputation building
        self.my_actions = []
        # Track opponent's cooperation rate per opponent
        self.opp_coop_rate = {}
        # Track how many times I've cooperated with each opponent
        self.coop_with_opp = {}
        self.def_with_opp = {}
        # Track recent interactions for adaptive strategy
        self.recent_interactions = {}  # opp_id -> list of (my_action, opp_action) last 10
        # Track my reputation as seen by others (approximate)
        self.my_reputation = 0.5  # initial neutral

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False

        # Get opponent's overall cooperation rate from public observations
        as_donor = self.obs_as_donor.get(opp, [])
        as_recipient = self.obs_as_recipient.get(opp, [])
        total_obs = len(as_donor) + len(as_recipient)
        if total_obs == 0:
            # No info: defect to be safe
            return False

        coop_count = as_donor.count('cooperate') + as_recipient.count('cooperate')
        coop_rate = coop_count / total_obs

        # Also check my own interaction history with this opponent
        my_interactions = self.interactions.get(opp, [])
        my_coop_times = sum(1 for my, opp_action in my_interactions if my == 'cooperate')
        my_def_times = sum(1 for my, opp_action in my_interactions if my == 'defect')

        # Strategy:
        # 1. If opponent has high cooperation rate (>0.6) and enough data, cooperate to gain mutual benefit.
        # 2. If opponent is mostly defecting, defect.
        # 3. To exploit naive cooperators, if they are very cooperative (>0.8) but I haven't defected much against them recently, defect to exploit them.
        # 4. However, to maintain reputation, occasionally cooperate with highly cooperative opponents.

        if total_obs < 3:
            # Not enough data: defect
            return False

        # Determine if opponent is likely to retaliate: look at my interactions with them
        if my_interactions:
            opp_def_against_me = sum(1 for my, opp_action in my_interactions if opp_action == 'defect')
            opp_coop_against_me = sum(1 for my, opp_action in my_interactions if opp_action == 'cooperate')
            # Check recent behavior (last 5 interactions) to adapt faster
            recent = self.recent_interactions.get(opp, [])
            if recent:
                recent_def = sum(1 for my, opp_action in recent if opp_action == 'defect')
                recent_coop = sum(1 for my, opp_action in recent if opp_action == 'cooperate')
                if recent_def > 0:
                    # They have defected recently -> retaliate or avoid
                    if coop_rate > 0.7 and total_obs >= 10:
                        return True  # maybe they are forgiving but conditional
                    else:
                        return False
                else:
                    # They haven't defected recently -> they are cooperative now
                    # Exploit if they are very cooperative and I've been cooperating too much
                    if coop_rate > 0.8 and my_coop_times > 0:
                        # To exploit, defect but not too often to avoid losing reputation
                        # Use a probabilistic approach: defect with probability based on how naive they are
                        # If they have never defected against me, they are likely naive
                        if opp_def_against_me == 0:
                            # They never defected against me -> exploit aggressively
                            # But to maintain reputation, sometimes cooperate
                            if random.random() < 0.7:
                                return False  # defect to exploit
                            else:
                                return True  # occasional cooperation to keep them trusting
                        else:
                            # They have defected before but not recently -> be cautious
                            if coop_rate > 0.7:
                                return True  # cooperate to maintain relationship
                            else:
                                return False
                    else:
                        # Not very cooperative or I haven't cooperated much -> cooperate to build trust
                        if coop_rate > 0.5:
                            return True
                        else:
                            return False
            else:
                # No recent interactions but have history
                if opp_def_against_me > 0:
                    # They have defected against me before -> likely retaliatory
                    if coop_rate > 0.7 and total_obs >= 10:
                        return True
                    else:
                        return False
                else:
                    # They have never defected against me -> naive cooperator
                    # Exploit them
                    if coop_rate > 0.7:
                        return False  # defect to exploit
                    else:
                        if coop_rate > 0.5:
                            return True
                        else:
                            return False
        else:
            # No direct interaction yet: use public info
            if coop_rate > 0.8:
                # Likely naive cooperator: defect to exploit
                return False
            elif coop_rate > 0.5:
                # Moderate cooperator: cooperate to build relationship
                return True
            else:
                return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Record observations for all agents
        if donor_id != self.agent_id:
            if donor_id not in self.obs_as_donor:
                self.obs_as_donor[donor_id] = []
            self.obs_as_donor[donor_id].append(donor_action)
        if recipient_id != self.agent_id:
            if recipient_id not in self.obs_as_recipient:
                self.obs_as_recipient[recipient_id] = []
            self.obs_as_recipient[recipient_id].append(recipient_action)

        # Track my own actions and interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine my action and opponent action
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            # Record my action
            self.my_actions.append(my_action)
            if my_action == 'cooperate':
                self.my_total_coop += 1
            else:
                self.my_total_def += 1

            # Record interaction with opponent
            if opp_id not in self.interactions:
                self.interactions[opp_id] = []
            self.interactions[opp_id].append((my_action, opp_action))

            # Update recent interactions (keep last 10)
            if opp_id not in self.recent_interactions:
                self.recent_interactions[opp_id] = []
            self.recent_interactions[opp_id].append((my_action, opp_action))
            if len(self.recent_interactions[opp_id]) > 10:
                self.recent_interactions[opp_id].pop(0)

            # Update coop/def counts with this opponent
            if opp_id not in self.coop_with_opp:
                self.coop_with_opp[opp_id] = 0
                self.def_with_opp[opp_id] = 0
            if my_action == 'cooperate':
                self.coop_with_opp[opp_id] += 1
            else:
                self.def_with_opp[opp_id] += 1

        # Update round number (approximate - each observe call is one interaction)
        self.round_num += 1

