import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_history = {}  # opponent_id -> list of actions ('C'/'D')
        self.my_actions = {}        # opponent_id -> list of my actions
        self.coop_counts = [0] * 15  # cooperate count per agent (for reputation)
        self.defect_counts = [0] * 15
        self.gen_round = 0
        self.generation = 0
        self.total_rounds = 0
        self.cooperation_threshold = 0.25  # initial threshold for trusting others
        self.memory_limit = 50  # keep last 50 interactions per opponent
        self.trust_scores = {}   # opponent_id -> trust score (0 to 1)
        self.coop_frequency = 0.5  # overall cooperation rate to adapt
        self.rounds_played = 0
        self.generations_played = 0
        # New: track reputation of others as observed globally
        self.global_coop = [0] * 15
        self.global_def = [0] * 15

    def _record_action(self, opponent_id: int, my_action: bool, opp_action: bool):
        # Update history and counts
        if opponent_id not in self.opponent_history:
            self.opponent_history[opponent_id] = []
            self.my_actions[opponent_id] = []
        self.opponent_history[opponent_id].append('C' if opp_action else 'D')
        self.my_actions[opponent_id].append('C' if my_action else 'D')
        # Keep memory limit
        if len(self.opponent_history[opponent_id]) > self.memory_limit:
            self.opponent_history[opponent_id].pop(0)
            self.my_actions[opponent_id].pop(0)
        # Update counts for reputation (but note: these are only my interactions, not global)
        if opp_action:
            self.coop_counts[opponent_id] += 1
        else:
            self.defect_counts[opponent_id] += 1
        # Update trust score (simple moving average)
        total = self.coop_counts[opponent_id] + self.defect_counts[opponent_id]
        if total > 0:
            self.trust_scores[opponent_id] = self.coop_counts[opponent_id] / total

    def _decide_against(self, opponent_id: int) -> bool:
        # Core strategy logic
        if opponent_id not in self.opponent_history:
            # No history: be cautious but slightly cooperative to probe
            # Use global reputation to decide initial action
            glob_total = self.global_coop[opponent_id] + self.global_def[opponent_id]
            if glob_total > 0:
                rep = self.global_coop[opponent_id] / glob_total
                # Cooperate if reputation is high, else defect
                return rep > 0.6
            else:
                return random.random() < 0.4  # initial probe
        opp_hist = self.opponent_history[opponent_id]
        n = len(opp_hist)
        if n == 0:
            return False

        # Compute opponent cooperation rate from my history
        coop_rate = sum(1 for a in opp_hist if a == 'C') / n

        # Trust score from my interactions
        trust = self.trust_scores.get(opponent_id, 0.5)

        # Also incorporate global reputation
        glob_total = self.global_coop[opponent_id] + self.global_def[opponent_id]
        if glob_total > 0:
            glob_rep = self.global_coop[opponent_id] / glob_total
        else:
            glob_rep = 0.5

        # Combine local and global info: if global says defector, be more suspicious
        effective_trust = 0.5 * trust + 0.5 * glob_rep

        # Adaptive threshold: lower if overall cooperation is low (to exploit defectors)
        threshold = self.cooperation_threshold
        if self.rounds_played > 0:
            # Adjust threshold based on overall cooperation rate (global observation)
            threshold = max(0.1, min(0.9, self.coop_frequency * 0.8 + 0.1))

        # Use a forgiving tit-for-tat with noise tolerance
        if n >= 1 and opp_hist[-1] == 'C':
            # If opponent cooperated last time, cooperate if they are generally cooperative
            if coop_rate > threshold or effective_trust > threshold:
                return True
            else:
                # Even if last was C, if they are overall bad, defect
                return False
        else:
            # Opponent defected last time or unknown: defect unless very high trust
            if effective_trust > 0.8 and coop_rate > 0.7:
                return True
            else:
                return False

    def decide(self) -> bool:
        # Get opponent id from context
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
            return False
        # Occasionally explore with small probability to learn
        if random.random() < 0.02:
            return random.random() < 0.5
        return self._decide_against(opp)

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global reputation counts for all agents (public observation)
        if donor_id < 15:
            if donor_action == 'cooperate':
                self.global_coop[donor_id] += 1
            else:
                self.global_def[donor_id] += 1
        if recipient_id < 15:
            if recipient_action == 'cooperate':
                self.global_coop[recipient_id] += 1
            else:
                self.global_def[recipient_id] += 1

        # Update local trust scores for observed agents (using global counts)
