        # Track my cumulative reputation from others' perspective (approx)
        self.my_rep_history = []
        self.cooperate_bias = 0.0  # dynamic bias to exploit or be generous

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False

        # Get opponent's overall cooperation rate from public observations
        as_donor = self.obs_as_donor.get(opp, [])
        as_recipient = self.obs_as_recipient.get(opp, [])
        total_obs = len(as_donor) + len(as_recipient)
        if total_obs == 0:
            # No info: cooperate to build reputation (since being cooperative may get reciprocated)
            return True

        coop_count = as_donor.count('cooperate') + as_recipient.count('cooperate')
        coop_rate = coop_count / total_obs

        # Also check my own interaction history with this opponent
        my_interactions = self.interactions.get(opp, [])
        my_coop_times = sum(1 for my, opp_action in my_interactions if my == 'cooperate')
        my_def_times = sum(1 for my, opp_action in my_interactions if my == 'defect')

        # Determine opponent's recent behavior (last few rounds) from public observations
        recent_donor = as_donor[-5:] if as_donor else []
        recent_recipient = as_recipient[-5:] if as_recipient else []
        recent_actions = recent_donor + recent_recipient
        if recent_actions:
            recent_coop_rate = recent_actions.count('cooperate') / len(recent_actions)
        else:
            recent_coop_rate = coop_rate

        # Strategy: Adaptive exploitative/cooperative based on opponent type and my reputation
        # 1. If opponent is a clear cooperator (coop_rate > 0.7) and doesn't retaliate, exploit to gain.
        #    But to maintain reputation, don't over-exploit; alternate.
        # 2. If opponent is defector (coop_rate < 0.4), defect always.
        # 3. If moderate, cooperate if recent cooperation is high to build trust.
        # 4. Use my reputation: if my reputation is low, cooperate more to rebuild; if high, exploit more.

        # Adjust my cooperate_bias based on my reputation (range -0.2 to 0.2)
        if self.my_reputation > 0.7:
            self.cooperate_bias = -0.15  # more exploitative
        elif self.my_reputation < 0.3:
            self.cooperate_bias = 0.15   # more cooperative
        else:
            self.cooperate_bias = 0.0

        # If I have direct interactions, look at whether they retaliate
        if my_interactions:
            opp_def_against_me = sum(1 for my, opp_action in my_interactions if opp_action == 'defect')
            opp_coop_against_me = sum(1 for my, opp_action in my_interactions if opp_action == 'cooperate')
