                recent_def = sum(1 for my, opp_action in recent if opp_action == 'defect')
                recent_coop = sum(1 for my, opp_action in recent if opp_action == 'cooperate')
                # If they defect recently, defect (no forgiveness unless they have high coop_rate overall)
                if recent_def > 0:
                    if coop_rate > 0.8 and recent_def <= 1:
                        # They might be forgiving, cooperate occasionally
                        return random.random() < 0.3
                    else:
                        return False
                else:
                    # They haven't defected recently -> they are cooperative
                    # Exploit if they are very cooperative and haven't retaliated before
                    if coop_rate > 0.75 and opp_def_against_me == 0:
                        # Exploit with probability, but not too often to keep reputation
                        exploit_prob = 0.6 + self.cooperate_bias
                        return random.random() >= exploit_prob  # True means cooperate, so defect when random < exploit_prob
                    elif coop_rate > 0.6:
                        # Moderately cooperative, cooperate to maintain trust
                        return True
                    else:
                        return False
            else:
                # No recent direct interactions but have history
                if opp_def_against_me > 0:
                    # They have defected before -> retaliatory
                    if coop_rate > 0.7:
                        return random.random() < 0.4  # sometimes cooperate to rebuild
                    else:
                        return False
                else:
                    # Never defected against me -> naive cooperator
                    if coop_rate > 0.75:
                        # Exploit aggressively but with some cooperation to keep them trusting
                        exploit_prob = 0.8 + self.cooperate_bias
                        return random.random() >= exploit_prob
                    else:
                        return coop_rate > 0.5
        else:
            # No direct interaction yet: use public info
            if coop_rate > 0.8:
                # Likely naive cooperator: defect with high probability
                exploit_prob = 0.85 + self.cooperate_bias
                return random.random() >= exploit_prob
            elif coop_rate > 0.5:
                # Moderate: cooperate to build relationship
                return True
            else:
                return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Record observations for all agents
        if donor_id != self.agent_id:
            if donor_id not in self.obs_as_donor:
                self.obs_as_donor[donor_id] = []
            self.obs_as_donor[donor_id].append(donor_action)
