            return False

        as_donor = self.obs_as_donor.get(opp, [])
        as_recipient = self.obs_as_recipient.get(opp, [])
        total_obs = len(as_donor) + len(as_recipient)
        if total_obs == 0:
            if self.reputation > 0.5:
                return True
            return False

        coop_count = as_donor.count('cooperate') + as_recipient.count('cooperate')
        coop_rate = coop_count / total_obs
        self.expected_coop_rate[opp] = coop_rate

        my_interactions = self.interactions.get(opp, [])
        my_coop_times = sum(1 for my, opp_action in my_interactions if my == 'cooperate')
        my_def_times = sum(1 for my, opp_action in my_interactions if my == 'defect')

        # Opponent defection rate against me
        opp_def_against_me = sum(1 for my, opp_action in my_interactions if opp_action == 'defect')
        opp_coop_against_me = sum(1 for my, opp_action in my_interactions if opp_action == 'cooperate')
        total_my_interactions = len(my_interactions)
        if total_my_interactions > 0:
            opp_def_rate = opp_def_against_me / total_my_interactions
        else:
            opp_def_rate = 0.0
        self.opp_def_rate[opp] = opp_def_rate

        # If opponent is a defector (high defection rate), avoid cooperating and defect
        if opp_def_rate > 0.5 and total_my_interactions >= 3:
            return False

        # If opponent is cooperative but I have exploited them a lot, consider cooperating to maintain reputation
        if coop_rate > 0.6 and total_my_interactions >= 2:
            my_exploit_ratio = my_def_times / max(1, total_my_interactions)
            if my_exploit_ratio > 0.7:
                # Occasionally cooperate to rebuild reputation, especially if my rep is low
                if self.reputation < 0.5:
                    return True
                else:
                    # If rep is high, we can continue exploiting with a small chance of cooperation
                    if random.random() < 0.2:
                        return True
                    else:
                        return False
            else:
                # Not over-exploited yet, so exploit
                if self.reputation > 0.5:
                    return False
                else:
                    # Low reputation, need to cooperate more to build it
                    if random.random() < 0.4:
                        return True
                    else:
