                self.def_with_opp[opp_id] += 1

            # Update reputation based on my action
            if my_action == 'cooperate':
                self.reputation = self.reputation * 0.9 + 0.1
            else:
                self.reputation = self.reputation * 0.9
            # Track reputation history for adaptive decisions
            self.rep_history.append(self.reputation)

        self.round_num += 1

