        self.recent_actions = {}  # opp_id -> deque of bool actions (True=C, False=D)
        self.cooperation_streak = {}  # opp_id -> current consecutive cooperation count
        self.defection_streak = {}  # opp_id -> current consecutive defection count
        # New: track opponent's reputation as seen by others, with higher weight
        self.global_defect_rates = {}  # agent_id -> recent defection rate
        self.interaction_count = {}  # agent_id -> number of interactions with this agent
        self.last_action_towards = {}  # opp_id -> my last action (True=C, False=D)

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False

        # Get current trust score
        trust_score = self.trust.get(opp, 0.5)

        # Analyze recent behavior patterns
        recent = self.recent_actions.get(opp, [])
        if len(recent) >= 3:
            # If opponent has been cooperating consistently, keep cooperating to build mutual trust
            # But if they suddenly defect, defect immediately (forgiving tit-for-tat)
            if recent[-1] == False:
                return False
            # If opponent has a long cooperation streak, continue cooperating
            if self.cooperation_streak.get(opp, 0) >= 4:
                return True
            # If opponent has a long defection streak, defect
            if self.defection_streak.get(opp, 0) >= 2:
                return False

        # Use trust threshold with some randomness to avoid being exploited
        if trust_score >= 0.65:
            return True
        elif trust_score <= 0.35:
            return False
        else:
            # In the uncertain zone, use a probabilistic approach
            # Slightly bias towards cooperation if we've been cooperating with them
            key = (self.agent_id, opp)
            if key in self.own_interactions:
                my_actions = [a[0] for a in self.own_interactions[key]]
                if my_actions and my_actions[-1]:
                    return random.random() < 0.6
            return random.random() < 0.4

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        d_act = (donor_action == 'cooperate')
        r_act = (recipient_action == 'cooperate')

        # Update global counts
        if donor_id not in self.defect_count:
            self.defect_count[donor_id] = 0
            self.coop_count[donor_id] = 0
        if d_act:
            self.coop_count[donor_id] += 1
        else:
            self.defect_count[donor_id] += 1

