        key = (donor_id, recipient_id)
        if key not in self.history:
            self.history[key] = []
        self.history[key].append(d_act)

        # Track own interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            own_key = (self.agent_id, other)
            if own_key not in self.own_interactions:
                self.own_interactions[own_key] = []
            if donor_id == self.agent_id:
                my_act = d_act
                opp_act = r_act
            else:
                my_act = r_act
                opp_act = d_act
            self.own_interactions[own_key].append((my_act, opp_act))

            # Update trust based on direct interaction
            if opp_act:
                self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.15)
            else:
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - 0.25)

            # Update recent actions and streaks for this opponent
            if other not in self.recent_actions:
                self.recent_actions[other] = []
                self.cooperation_streak[other] = 0
