                self.defection_streak[other] = 0
            else:
                self.defection_streak[other] += 1
                self.cooperation_streak[other] = 0

            # Track interaction count
            self.interaction_count[other] = self.interaction_count.get(other, 0) + 1

            # Update last action towards this opponent (for potential revenge/forgiveness)
            self.last_action_towards[other] = my_act

        # Update reputation-based trust for third-party observations
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Use global reputation to adjust trust, but with a learning rate
            total = self.defect_count.get(donor_id, 0) + self.coop_count.get(donor_id, 0)
            if total >= 5:
                def_rate = self.defect_count.get(donor_id, 0) / total
                # Update trust based on reputation, but don't let it dominate personal experience
                if def_rate > 0.6:
                    self.trust[donor_id] = min(self.trust.get(donor_id, 0.5), 0.4)
                elif def_rate < 0.3:
