                elif recip_def_rate < 0.3:
                    self.trust[recipient_id] = max(self.trust.get(recipient_id, 0.5), 0.6)

        # NEW: Update global defection rate for all observed agents with higher weight
        # This makes reputation more influential for decision-making
        for agent in [donor_id, recipient_id]:
            if agent != self.agent_id:
                total_agent = self.defect_count.get(agent, 0) + self.coop_count.get(agent, 0)
                if total_agent >= 5:
