    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust with adaptive base
        if opp not in self.trust:
            # Use public reputation heavily for unknown opponents
            if opp in self.public_total and self.public_total[opp] > 30:
                coop_rate = self.public_coop_rate.get(opp, 0) / self.public_total[opp]
                if coop_rate > 0.8:
                    self.trust[opp] = 0.75
                elif coop_rate < 0.2:
                    self.trust[opp] = 0.15
                else:
                    self.trust[opp] = 0.45
            else:
                # Be more optimistic initially to encourage cooperation
                self.trust[opp] = 0.65

        # Personal interaction adjustments
        key = (self.agent_id, opp)
