            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                # Recent opponent behavior (last 5)
                recent = opp_actions[-5:]
                coop_count = sum(recent)
                coop_rate = coop_count / len(recent)
                # If they cooperated recently, increase trust significantly
                if coop_rate > 0.6:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.25)
                elif coop_rate < 0.3:
                    # Check streak for severe punishment
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 3:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.4)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.2)
                else:
                    # Mixed behavior - keep trust moderate
                    self.trust[opp] = self.trust.get(opp, 0.5) * 0.9 + 0.1

        # Exploit forgiving cooperators more aggressively
        my_def = self.my_defects.get(opp, 0)
        opp_coop_me = self.opp_coop_vs_me.get(opp, 0)
        if opp_coop_me > 3 and my_def > 0:
            # They've cooperated with us multiple times despite our defections
