                    return random.random() < 0.8
                else:
                    return False
            else:
                # Opponent has defected against me before
                # Check if they retaliate when I defect
                if retaliated:
                    # They retaliate: be more cooperative to avoid punishment
                    return True
                else:
                    # They don't retaliate: exploit them
                    if coop_rate > 0.6:
                        exploit_prob = 0.85 + self.cooperate_bias
                        return random.random() >= exploit_prob
                    else:
