        self.opp_response_to_my_coop = {}
        self.opp_response_to_my_defect = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False

        # Get opponent's overall cooperation rate from public observations
        as_donor = self.obs_as_donor.get(opp, [])
        as_recipient = self.obs_as_recipient.get(opp, [])
        total_obs = len(as_donor) + len(as_recipient)
        if total_obs == 0:
            # No info: cooperate initially to build reputation
            return True

        coop_count = as_donor.count('cooperate') + as_recipient.count('cooperate')
        coop_rate = coop_count / total_obs

        # Check my own interaction history with this opponent
        my_interactions = self.interactions.get(opp, [])
        my_coop_times = sum(1 for my, opp_action in my_interactions if my == 'cooperate')
        my_def_times = sum(1 for my, opp_action in my_interactions if my == 'defect')

        # Determine opponent's recent behavior (last few rounds) from public observations
        recent_donor = as_donor[-5:] if as_donor else []
        recent_recipient = as_recipient[-5:] if as_recipient else []
        recent_actions = recent_donor + recent_recipient
        if recent_actions:
            recent_coop_rate = recent_actions.count('cooperate') / len(recent_actions)
        else:
            recent_coop_rate = coop_rate

        # Check if opponent has retaliated against me recently (defected after I defected)
        retaliated = False
        if my_interactions:
            recent_my = my_interactions[-5:]
            for i in range(len(recent_my)-1):
                if recent_my[i][0] == 'defect' and recent_my[i+1][1] == 'defect':
                    retaliated = True
                    break

        # Adjust cooperate_bias based on my reputation and also on round number
        if self.round_num < 50:
            # Early game: build reputation to attract cooperators
            if self.my_reputation > 0.8:
                self.cooperate_bias = -0.1  # slightly exploit when reputation high
            elif self.my_reputation < 0.3:
                self.cooperate_bias = 0.3   # boost reputation when low
            else:
                self.cooperate_bias = 0.1
        else:
            # Late game: exploit more aggressively
            if self.my_reputation > 0.7:
                self.cooperate_bias = -0.3
            elif self.my_reputation < 0.3:
                self.cooperate_bias = 0.2
            else:
                self.cooperate_bias = -0.1

        # More sophisticated strategy based on opponent's behavior against me
        opp_def_against_me = self.opp_total_def_against_me.get(opp, 0)
        opp_coop_against_me = self.opp_total_coop_against_me.get(opp, 0)
        opp_interactions_count = self.opp_interaction_count.get(opp, 0)

        # Check if opponent has ever defected against me
        ever_defected = opp_def_against_me > 0

        # Check recent defection pattern
        recent_defections = self.opp_recent_def_against_me.get(opp, 0)
        recent_cooperations = self.opp_recent_cooperations.get(opp, 0) if hasattr(self, 'opp_recent_cooperations') else 0

        # Determine opponent type based on my interactions
        if my_interactions:
            # Direct interaction exists
            if ever_defected:
                # Opponent has defected against me
                # Check if they are retaliatory (defect after I defect)
                retaliation_count = self.opp_retaliations.get(opp, 0)
                my_defects = my_def_times
                if my_defects > 0 and retaliation_count / my_defects > 0.3:
                    # They retaliate strongly: be cooperative to avoid punishment
                    # But if they cooperate a lot overall, maybe they are forgiving
                    if coop_rate > 0.7:
