                    if coop_rate > 0.6:
                        exploit_prob = 0.8 + self.cooperate_bias
                        return random.random() >= exploit_prob
                    else:
                        # Low cooperator: defect
                        return False
            else:
                # Opponent never defected against me: likely naive cooperator
                if coop_rate > 0.85:
                    # Very cooperative: exploit aggressively
                    exploit_prob = 0.9 + self.cooperate_bias
                    return random.random() >= exploit_prob
                elif coop_rate > 0.6:
                    # Moderate: cooperate to maintain relationship but sometimes test
                    return random.random() < 0.85
                else:
                    # Not very cooperative: defect
                    return False
        else:
            # No direct interaction yet: use public info and reputation
            # Consider opponent's overall behavior and my reputation
            if coop_rate > 0.85:
                # Likely naive cooperator: defect aggressively
                exploit_prob = 0.9 + self.cooperate_bias
                return random.random() >= exploit_prob
            elif coop_rate > 0.6:
                # Moderate: cooperate to build relationship, but if my reputation is high, exploit more
                if self.my_reputation > 0.7:
                    exploit_prob = 0.4 + self.cooperate_bias
                    return random.random() >= exploit_prob
                else:
                    return True
            elif coop_rate > 0.4:
                # Somewhat defector: be cautious
                return random.random() < 0.3
            else:
                # Defector: always defect
                return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Record observations for all agents
        if donor_id != self.agent_id:
            if donor_id not in self.obs_as_donor:
                self.obs_as_donor[donor_id] = []
            self.obs_as_donor[donor_id].append(donor_action)
        if recipient_id != self.agent_id:
            if recipient_id not in self.obs_as_recipient:
                self.obs_as_recipient[recipient_id] = []
            self.obs_as_recipient[recipient_id].append(recipient_action)

        # Track my own actions and interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            self.my_actions.append(my_action)
            if my_action == 'cooperate':
                self.my_total_coop += 1
            else:
                self.my_total_def += 1

            if opp_id not in self.interactions:
                self.interactions[opp_id] = []
            self.interactions[opp_id].append((my_action, opp_action))

            if opp_id not in self.recent_interactions:
                self.recent_interactions[opp_id] = []
            self.recent_interactions[opp_id].append((my_action, opp_action))
            if len(self.recent_interactions[opp_id]) > 10:
                self.recent_interactions[opp_id].pop(0)

            if opp_id not in self.coop_with_opp:
                self.coop_with_opp[opp_id] = 0
                self.def_with_opp[opp_id] = 0
            if my_action == 'cooperate':
                self.coop_with_opp[opp_id] += 1
            else:
                self.def_with_opp[opp_id] += 1

            # Track opponent's actions against me
            if opp_id not in self.opp_total_def_against_me:
                self.opp_total_def_against_me[opp_id] = 0
                self.opp_total_coop_against_me[opp_id] = 0
                self.opp_interaction_count[opp_id] = 0
                self.opp_recent_def_against_me[opp_id] = 0
                self.opp_recent_cooperations[opp_id] = 0
                self.opp_ever_defected[opp_id] = False
                self.opp_ever_cooperated[opp_id] = False
            if opp_action == 'defect':
                self.opp_total_def_against_me[opp_id] += 1
                self.opp_ever_defected[opp_id] = True
                self.opp_recent_def_against_me[opp_id] += 1
            else:
                self.opp_total_coop_against_me[opp_id] += 1
                self.opp_ever_cooperated[opp_id] = True
                self.opp_recent_cooperations[opp_id] += 1
            self.opp_interaction_count[opp_id] += 1

            # Track recent defections (last 5 interactions)
            recent_my = self.recent_interactions.get(opp_id, [])
            if len(recent_my) > 5:
                # Remove old counts
                old_interaction = recent_my[0]
                old_opp_action = old_interaction[1]
                if old_opp_action == 'defect':
                    self.opp_recent_def_against_me[opp_id] -= 1
                else:
                    self.opp_recent_cooperations[opp_id] -= 1

            # Track retaliation: if I defected and opponent defects next time, that's retaliation
            if opp_id not in self.opp_retaliations:
                self.opp_retaliations[opp_id] = 0
            recent = self.recent_interactions.get(opp_id, [])
            if len(recent) >= 2:
                if recent[-2][0] == 'defect' and recent[-1][1] == 'defect':
                    self.opp_retaliations[opp_id] += 1

            # Track response patterns: how opponent responds to my actions
            if opp_id not in self.opp_response_to_my_coop:
                self.opp_response_to_my_coop[opp_id] = {'coop': 0, 'def': 0}
                self.opp_response_to_my_defect[opp_id] = {'coop': 0, 'def': 0}
            if len(self.interactions[opp_id]) >= 1:
                last_my, last_opp = self.interactions[opp_id][-1]
                if len(self.interactions[opp_id]) >= 2:
                    prev_my, prev_opp = self.interactions[opp_id][-2]
                    if prev_my == 'cooperate':
                        self.opp_response_to_my_coop[opp_id][last_opp] += 1
                    else:
                        self.opp_response_to_my_defect[opp_id][last_opp] += 1

        # Update my reputation based on my actions
        total_actions = self.my_total_coop + self.my_total_def
        if total_actions > 0:
            self.my_reputation = self.my_total_coop / total_actions
        # Also consider others' perception: if I cooperate, I'm seen as cooperative
        self.my_perceived_coop = self.my_total_coop
        self.my_perceived_def = self.my_total_def
        if self.my_perceived_coop + self.my_perceived_def > 0:
            self.my_perceived_coop = self.my_perceived_coop / (self.my_perceived_coop + self.my_perceived_def)
        self.my_rep_history.append(self.my_reputation)

        self.round_num += 1

