        self.my_defects = {}
        # Track opponent's cooperation count specifically with us
        self.opp_coop_vs_me = {}
        self.opp_def_vs_me = {}
        # Reputation tracking: how often each agent cooperates in public
        self.public_coop_rate = {}
        self.public_total = {}
        # Track our own public reputation to adjust behavior
        self.my_public_total = 0
        self.my_public_coops = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            # Base trust on public reputation if enough observations
            if opp in self.public_total and self.public_total[opp] > 20:
                coop_rate = self.public_coop_rate.get(opp, 0) / self.public_total[opp]
                if coop_rate > 0.8:
                    self.trust[opp] = 0.7
                elif coop_rate < 0.3:
                    self.trust[opp] = 0.2
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                # Tit-for-tat with forgiveness: cooperate if opponent cooperated last time
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    # If opponent defected, check streak
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.35)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
        # Exploit cooperators: if opponent has high coop rate but low defections against us, cooperate more
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 20:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.1:
                # Generous cooperator - exploit by always cooperating to keep them cooperating
                self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.3)
            elif def_rate > 0.6:
                # Chronic defector - defect always
                self.trust[opp] = 0.0
        # Specific to our interactions: if they cooperate with us a lot but we defect, they may still cooperate
        my_def = self.my_defects.get(opp, 0)
        opp_coop_me = self.opp_coop_vs_me.get(opp, 0)
        if opp_coop_me > 5 and my_def > opp_coop_me * 0.5:
            # They are forgiving - exploit more
            self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.15)
