        self.my_total_defects = 0
        self.coop_rate_with_us = {}
        self.defects_against = {}
        self.forgiveness = {}
        # NEW: Track opponent cooperation streaks and our own image
        self.opp_coop_streak = {}
        self.my_image = 0.5  # smoothed reputation estimate

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6

        # Personal history adjustments with more aggressive punishment/reward
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)

        # Exploit pure cooperators: more aggressive exploitation while maintaining their cooperation
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                # They cooperate almost always - exploit with pattern that maintains their trust
                # Defect every 2nd interaction instead of 3rd for more payoff, but use forgiveness detection
                if opp not in self.defects_against:
                    self.defects_against[opp] = 0
                # If they forgive our defections, defect more often
                forgiveness_level = self.forgiveness.get(opp, 0)
                total_interactions = self.interaction_count.get(opp, 0)
                if total_interactions > 0:
                    forgive_rate = forgiveness_level / max(1, self.defects_against.get(opp, 0))
                    if forgive_rate > 0.5:
                        # They forgive a lot, defect every 2nd time
                        if self.defects_against[opp] % 2 == 1:
                            return False
                        else:
                            return True
                # Default pattern: defect every 3rd interaction
                if self.defects_against[opp] % 3 == 2:
                    return False
                else:
                    return True
            elif def_rate > 0.7:
                # Chronic defector - defect always
                self.trust[opp] = 0.0
                return False

        # Reputation engineering: maintain high reputation to get cooperation from others
        # Use smoothed image instead of raw ratio to be more responsive
        if self.my_total_coops + self.my_total_defects > 0:
            current_rep = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            # Update smoothed image
            self.my_image = 0.9 * self.my_image + 0.1 * current_rep
            if self.my_image < 0.5:
                # Rebuild reputation by cooperating even with untrusted opponents
                if self.trust.get(opp, 0.5) < 0.3:
                    return True

        # Strategic exploitation: if we have high reputation, defect more often against cooperators
        if self.my_total_coops + self.my_total_defects > 10:
