class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.history = {}
        self.own_interactions = {}
        self.defect_count = {}
        self.coop_count = {}
        self.trust = {}
        self.round_num = 0
        self.generation = 0
        self._ctx_opponent_id = None
        # Track recent opponent actions for adaptive strategy
        self.recent_opp_actions = {}  # opp_id -> list of last 3 actions (True=C, False=D)
        # Track how many times we cooperated with each opponent
        self.coops_with = {}
        # Track opponent's recent defection streak
        self.opp_def_streak = {}
        # Track our own defection count against each opponent to exploit
        self.my_defects = {}
        # Track opponent's cooperation count specifically with us
        self.opp_coop_vs_me = {}
        self.opp_def_vs_me = {}
        # Reputation tracking: how often each agent cooperates in public
        self.public_coop_rate = {}
        self.public_total = {}
        # New: track recent public actions to identify patterns
        self.public_actions = {}  # agent_id -> list of recent actions (True=C, False=D)

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            # Base trust on public reputation if enough observations
            if opp in self.public_total and self.public_total[opp] > 20:
                coop_rate = self.public_coop_rate.get(opp, 0) / self.public_total[opp]
                if coop_rate > 0.8:
                    self.trust[opp] = 0.7
                elif coop_rate < 0.3:
                    self.trust[opp] = 0.2
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                # Tit-for-tat with forgiveness: cooperate if opponent cooperated last time
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    # If opponent defected, check streak
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.35)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
        # Exploit cooperators: if opponent has high coop rate but low defections against us, cooperate more
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 20:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.1:
                # Generous cooperator - exploit by always cooperating to keep them cooperating
                self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.3)
            elif def_rate > 0.6:
                # Chronic defector - defect always
                self.trust[opp] = 0.0
        # Specific to our interactions: if they cooperate with us a lot but we defect, they may still cooperate
        my_def = self.my_defects.get(opp, 0)
        opp_coop_me = self.opp_coop_vs_me.get(opp, 0)
        if opp_coop_me > 5 and my_def > opp_coop_me * 0.5:
            # They are forgiving - exploit more
            self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.15)
        # New: Use recent public patterns to adjust trust
        # If opponent has been cooperating recently in public, increase trust
        if opp in self.public_actions and len(self.public_actions[opp]) >= 5:
            recent = self.public_actions[opp][-5:]
            recent_coop_rate = sum(recent) / len(recent)
            if recent_coop_rate > 0.8:
                self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.1)
            elif recent_coop_rate < 0.2:
                self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.2)
        # Decision threshold: slightly lower to be more trusting of cooperators
        return self.trust.get(opp, 0.5) >= 0.35

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        d_act = (donor_action == 'cooperate')
        r_act = (recipient_action == 'cooperate')
        # Update global counts
        if donor_id not in self.defect_count:
            self.defect_count[donor_id] = 0
            self.coop_count[donor_id] = 0
        if d_act:
            self.coop_count[donor_id] += 1
        else:
            self.defect_count[donor_id] += 1
        # Update public reputation
        if donor_id not in self.public_total:
            self.public_total[donor_id] = 0
            self.public_coop_rate[donor_id] = 0
        self.public_total[donor_id] += 1
        if d_act:
            self.public_coop_rate[donor_id] += 1
        # Track recent public actions for each agent
        if donor_id not in self.public_actions:
            self.public_actions[donor_id] = []
        self.public_actions[donor_id].append(d_act)
        # Keep only last 20 to save memory
        if len(self.public_actions[donor_id]) > 20:
            self.public_actions[donor_id] = self.public_actions[donor_id][-20:]
        # Track per-pair history
        key = (donor_id, recipient_id)
        if key not in self.history:
            self.history[key] = []
        self.history[key].append(d_act)
        # Track own interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            own_key = (self.agent_id, other)
            if own_key not in self.own_interactions:
                self.own_interactions[own_key] = []
            if donor_id == self.agent_id:
                my_act = d_act
                opp_act = r_act
            else:
                my_act = r_act
                opp_act = d_act
            self.own_interactions[own_key].append((my_act, opp_act))
            # Update recent opponent actions
            if other not in self.recent_opp_actions:
                self.recent_opp_actions[other] = []
            self.recent_opp_actions[other].append(opp_act)
            if len(self.recent_opp_actions[other]) > 3:
                self.recent_opp_actions[other] = self.recent_opp_actions[other][-3:]
            # Update defection streak
            if opp_act:
                self.opp_def_streak[other] = 0
            else:
                self.opp_def_streak[other] = self.opp_def_streak.get(other, 0) + 1
            # Update opponent's behavior specifically against us
            if opp_act:
                self.opp_coop_vs_me[other] = self.opp_coop_vs_me.get(other, 0) + 1
            else:
                self.opp_def_vs_me[other] = self.opp_def_vs_me.get(other, 0) + 1
            # Update our defection count
            if not my_act:
                self.my_defects[other] = self.my_defects.get(other, 0) + 1
            # Update trust based on this interaction
            if opp_act:
                self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.15)
            else:
                # If opponent defected, lower trust more if they have a streak
                streak = self.opp_def_streak.get(other, 0)
                penalty = 0.2 if streak >= 2 else 0.1
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - penalty)
        # Third-party reputation: but be less harsh to avoid over-penalizing
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            total = self.defect_count.get(donor_id, 0) + self.coop_count.get(donor_id, 0)
            if total > 30:
                def_rate = self.defect_count.get(donor_id, 0) / total
                if def_rate > 0.8:
                    self.trust[donor_id] = min(self.trust.get(donor_id, 0.5), 0.1)
                elif def_rate < 0.1:
                    self.trust[donor_id] = max(self.trust.get(donor_id, 0.5), 0.8)

