        # Track how many times we cooperated with each opponent
        self.coops_with = {}
        # Track opponent's recent defection streak
        self.opp_def_streak = {}
        # Track our own defection count against each opponent to exploit
        self.my_defects = {}
        # Track opponent's cooperation count specifically with us
        self.opp_coop_vs_me = {}
        self.opp_def_vs_me = {}
        # Reputation tracking: how often each agent cooperates in public
        self.public_coop_rate = {}
        self.public_total = {}
        # NEW: Track opponent's actions in last 5 interactions with us for better prediction
        self.opp_recent_5 = {}
        # NEW: Track if opponent tends to retaliate after our defection
        self.opp_retaliates = {}
        # NEW: Track our own reputation to know if we can afford defection
        self.my_public_coop = 0
        self.my_public_total = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            # Base trust on public reputation if enough observations
            if opp in self.public_total and self.public_total[opp] > 20:
                coop_rate = self.public_coop_rate.get(opp, 0) / self.public_total[opp]
                if coop_rate > 0.8:
                    self.trust[opp] = 0.7
                elif coop_rate < 0.3:
                    self.trust[opp] = 0.2
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                # Tit-for-tat with forgiveness: cooperate if opponent cooperated last time
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    # If opponent defected, check streak
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.35)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
