            recent_coop = sum(self.opp_public_recent[opp])
            if recent_coop >= 8:
                # Very cooperative recently - maybe exploit by defecting occasionally? But better to cooperate for mutual benefit
                # Actually, if they are very cooperative, we can defect and still get away with it, but risk reputation.
                # For now, increase trust to cooperate.
                self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
            elif recent_coop <= 2:
                self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
        # NEW: Use last 20 public interactions for more stable sucker detection
        if opp in self.opp_public_last20 and len(self.opp_public_last20[opp]) == 20:
