        # If opponent's global cooperation rate is very high, defect more often
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.1:
                # Defect with high probability
                if random.random() < 0.9:
                    return True
        # Additional exploitation: if opponent has been cooperating recently in general and we have high reputation
        recent_global = self.opp_recent_global_coop.get(opp, [])
        if len(recent_global) >= 3 and all(recent_global[-3:]) and self.my_reputation_score > 0.6:
