        self.opp_recent_def = {}
        self.my_total_coops = 0
        self.my_total_defects = 0
        self.coop_rate_with_us = {}
        self.defects_against = {}
        self.forgiveness = {}
        self.opp_recent_global_coop = {}
        self.my_recent_reputation = []
        self.opp_reaction_to_def = {}
        # Track our reputation in the eyes of others (aggregate)
        self.my_reputation_score = 0.5
        self.my_reputation_count = 0
        # Track opponent's overall cooperation rate from all observations
        self.opp_global_coop = {}
        # Track whether opponent has been cooperating recently in general
        self.opp_recent_general_coop = {}
        # New: track consecutive defections by each opponent
        self.opp_consecutive_defects = {}
        # New: track our total interactions and adaptive threshold
        self.total_interactions = 0
        self.adaptive_threshold = 0.5

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
        # Exploit pure cooperators more aggressively
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                # Defect every 2nd interaction instead of 3rd
                if opp not in self.defects_against:
                    self.defects_against[opp] = 0
                if self.defects_against[opp] % 2 == 1:
                    return False
                else:
                    return True
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False
        # Reputation engineering: more aggressive rebuild when reputation is low
        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if my_reputation < 0.4:
                # Cooperate even with untrusted opponents to rebuild quickly
                if self.trust.get(opp, 0.5) < 0.5:
                    return True
        # Strategic exploitation: defect more often when reputation is high
        if self.my_total_coops + self.my_total_defects > 10:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if my_reputation > 0.7 and self.trust.get(opp, 0.5) > 0.8:
                # Increase defection probability from 0.4 to 0.55
                if random.random() < 0.55:
                    return False
        # Avoid defectors
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False
        # If opponent has defected recently against us, defect
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False
        # If opponent's global cooperation rate is very high, defect more often
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.1:
                # Defect with high probability
                if random.random() < 0.9:
                    return True
        # Additional exploitation: if opponent has been cooperating recently in general and we have high reputation
        recent_global = self.opp_recent_global_coop.get(opp, [])
        if len(recent_global) >= 3 and all(recent_global[-3:]) and self.my_reputation_score > 0.6:
            if random.random() < 0.3:
                return True
        # If our reputation is low, cooperate more to rebuild
        if self.my_reputation_count > 10:
            if self.my_reputation_score < 0.4:
                return True
        # Adaptive threshold: decrease threshold over time to become more aggressive
        # but only if we have a decent reputation
        self.total_interactions += 1
        if self.total_interactions > 50 and self.my_reputation_score > 0.5:
            self.adaptive_threshold = max(0.3, self.adaptive_threshold - 0.001)
        else:
            self.adaptive_threshold = 0.35
        # Decision threshold: slightly more aggressive than parent
        return self.trust.get(opp, 0.5) >= self.adaptive_threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        d_act = (donor_action == 'cooperate')
        r_act = (recipient_action == 'cooperate')
