            # Track reaction to our defection: did they defect next time?
            if not my_act:
                # We defected, record their next action (if any)
                if other not in self.opp_reaction_to_def:
                    self.opp_reaction_to_def[other] = []
                # We'll add their next action in the next interaction
            # Update trust
            if opp_act:
