        self.coop_threshold = 0.65
        self.defect_threshold = 0.4
        self.explore_prob = 0.08
        self.punish_streak = 0
        self.max_punish_streak = 2
        self.defect_rep = {}
        self.my_defect_count = 0
        self.my_total_actions = 0
        self.global_rep = {}
        self.self_rep_estimate = 0
        self.recent_opp_actions = {}
        self.recent_my_actions = []
        self.recent_window = 10
        self.opp_global_defect_freq = {}
        self.obs_count = {}
        self.my_recent_coop_rate = 0.5
        self.opp_exploitable = {}

    def decide(self) -> bool:
        self.round += 1
        opponent = self._ctx_opponent_id
        if self.recent_my_actions:
            self.my_recent_coop_rate = sum(self.recent_my_actions) / len(self.recent_my_actions)
        else:
            self.my_recent_coop_rate = 0.5

        opp_total_obs = self.obs_count.get(opponent, 0)
        opp_defects = self.defect_rep.get(opponent, 0)
        if opp_total_obs > 0:
            opp_defect_freq = opp_defects / opp_total_obs
        else:
            opp_defect_freq = 0.0

        opp_rep = self.reputation.get(opponent, 0)

        # If opponent is known to be very cooperative (low defect freq, high rep), exploit them
        if opp_defect_freq <= 0.2 and opp_rep > 10 and self.interaction_count.get(opponent, 0) >= 2:
            if self.self_rep_estimate < -15:
                return True
            if self.my_recent_coop_rate < 0.3:
                return True
            if random.random() < 0.9:
                return False
            else:
                return True

        # If opponent is very defecting (high defect freq, low rep), avoid and defect
        if opp_defect_freq >= 0.7 and opp_rep < -5:
            return False

        # Standard logic based on my interaction history with this opponent
        if opponent not in self.interaction_count or self.interaction_count[opponent] < 3:
            if opp_defect_freq >= 0.5:
                return False
            return True

        coop_rate = self.opp_coop_rate.get(opponent, 0.5)
        # If opponent is forgiving (high coop rate with me), exploit more aggressively
        if coop_rate >= 0.7 and opp_rep > 5:
            if self.self_rep_estimate < -10:
                return True
            recent_opp = self.recent_opp_actions.get(opponent, [])
            if recent_opp and not recent_opp[-1]:
                return True
            if random.random() < 0.95:
                return False
            else:
                return True
        # If opponent is very defecting with me, defect
        if coop_rate <= 0.3:
            return False
        # Tit-for-tat with forgiveness
        last_opp = self.last_opp_action.get(opponent, True)
        if last_opp:
            return True
        else:
            recent_opp = self.recent_opp_actions.get(opponent, [])
            recent_defections = sum(1 for a in recent_opp[-3:] if not a)
            if recent_defections >= 2:
                return False
            if opp_rep > 0 and self.my_defect_count / max(1, self.my_total_actions) < 0.5:
                return random.random() < 0.3
            else:
                return False

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        donor_coop = (donor_action == 'cooperate')
        recipient_coop = (recipient_action == 'cooperate')
