        self.recent_opp_actions = {}  # opp_id -> list of last 3 actions (True=C, False=D)
        # Track how many times we cooperated with each opponent
        self.coops_with = {}
        # Track opponent's recent defection streak
        self.opp_def_streak = {}
        # Track our own defection count against each opponent to exploit
        self.my_defects = {}
        # Track opponent's cooperation count specifically with us
        self.opp_coop_vs_me = {}
        self.opp_def_vs_me = {}
        # Reputation tracking: how often each agent cooperates in public
        self.public_coop_rate = {}
        self.public_total = {}
        # NEW: Track opponent's actions in last 5 interactions with us for better prediction
        self.opp_recent_5 = {}
        # NEW: Track if opponent tends to retaliate after our defection
        self.opp_retaliates = {}
        # NEW: Track our own reputation to know if we can afford defection
        self.my_public_coop = 0
        self.my_public_total = 0
        # NEW: Track opponent's average cooperation rate in last 10 public interactions for better baseline
        self.opp_public_recent = {}  # opp_id -> list of last 10 actions
        # NEW: Track opponent's cooperation rate in last 20 interactions for more stable estimate
        self.opp_public_last20 = {}
        # NEW: Track if we have a strong reputation to exploit others
        self.reputation_strong = False
        # NEW: Track if opponent is a "sucker" who rarely defects even when exploited
        self.sucker_score = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            # Base trust on public reputation if enough observations
            if opp in self.public_total and self.public_total[opp] > 20:
                coop_rate = self.public_coop_rate.get(opp, 0) / self.public_total[opp]
                if coop_rate > 0.8:
                    self.trust[opp] = 0.7
                elif coop_rate < 0.3:
                    self.trust[opp] = 0.2
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                # Tit-for-tat with forgiveness: cooperate if opponent cooperated last time
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    # If opponent defected, check streak
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.35)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
        # Exploit cooperators: if opponent has high coop rate but low defections against us, cooperate more
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 20:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.1:
                # Generous cooperator - exploit by always cooperating to keep them cooperating
                self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.3)
            elif def_rate > 0.6:
                # Chronic defector - defect always
                self.trust[opp] = 0.0
        # Specific to our interactions: if they cooperate with us a lot but we defect, they may still cooperate
        my_def = self.my_defects.get(opp, 0)
        opp_coop_me = self.opp_coop_vs_me.get(opp, 0)
        if opp_coop_me > 5 and my_def > opp_coop_me * 0.5:
            # They are forgiving - exploit more
            self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.15)
        # NEW: Consider opponent's recent 5 actions pattern
        if opp in self.opp_recent_5 and len(self.opp_recent_5[opp]) == 5:
            coop_count = sum(self.opp_recent_5[opp])
            if coop_count <= 1:
                # Strongly defecting recently
                self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.2)
            elif coop_count >= 4:
                # Strongly cooperating recently
                self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.1)
        # NEW: Retaliation detection - if we defected and next turn opponent defected, they retaliate
        if opp in self.opp_retaliates and self.opp_retaliates[opp] > 2:
            # If they retaliate a lot, be cautious about defecting
            self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.05)
        # NEW: Reputation management - if our reputation is low, cooperate more often to rebuild
        if self.my_public_total > 20:
            my_coop_rate = self.my_public_coop / self.my_public_total
            if my_coop_rate < 0.3:
                # Need to rebuild reputation, be more cooperative
                self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.1)
        # NEW: Use recent public behavior (last 10) to detect trend
        if opp in self.opp_public_recent and len(self.opp_public_recent[opp]) == 10:
            recent_coop = sum(self.opp_public_recent[opp])
