                    self.defectors.add(donor_id)
        # New: Track last opponent action for quick reactions
        if donor_id == self.agent_id:
            self.last_opp_action[recipient_id] = r_act
        elif recipient_id == self.agent_id:
            self.last_opp_action[donor_id] = d_act

