        self.agent_id = agent_id
        self.history = {}
        self.own_interactions = {}
        self.defect_count = {}
        self.coop_count = {}
        self.trust = {}
        self.round_num = 0
        self.generation = 0
        self._ctx_opponent_id = None
        self.recent_opp_actions = {}
        self.coops_with = {}
        self.opp_def_streak = {}
        self.my_recent_actions = []
        self.coop_rate_others = {}
        self.def_rate_against_us = {}
        self.interaction_count = {}
        self.opp_recent_def = {}
        self.my_total_coops = 0
        self.my_total_defects = 0
        self.coop_rate_with_us = {}
        self.defects_against = {}
        self.forgiveness = {}
        self.opp_recent_global_coop = {}
        self.my_recent_reputation = []
        self.opp_reaction_to_def = {}
        self.my_reputation_score = 0.5
        self.my_reputation_count = 0
        self.opp_global_coop = {}
        self.opp_recent_general_coop = {}
        # New: track cooperation/defection counts per opponent for exploitation
        self.opp_total = {}
        self.opp_def_rate = {}
        # New: track how often we have defected against each opponent to avoid over-exploitation
        self.defections_against_opp = {}
        # New: track recent defections by opponent (global) to detect patterns
        self.opp_recent_def_global = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
        # Exploit pure cooperators more aggressively: defect every interaction if we have high reputation
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                # Defect every interaction if our reputation is above 0.7
                if self.my_total_coops + self.my_total_defects > 0:
                    my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
                    if my_reputation > 0.7:
                        return True
                # Otherwise defect every 2nd interaction to avoid too much reputation loss
                if opp not in self.defects_against:
                    self.defects_against[opp] = 0
                if self.defects_against[opp] % 2 == 1:
                    return False
                else:
                    return True
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False
        # Reputation engineering: more aggressive rebuild when reputation is low
        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if my_reputation < 0.4:
                # Cooperate even with untrusted opponents to rebuild quickly
                if self.trust.get(opp, 0.5) < 0.5:
                    return True
        # Strategic exploitation: defect more often when reputation is high
        if self.my_total_coops + self.my_total_defects > 10:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if my_reputation > 0.7 and self.trust.get(opp, 0.5) > 0.8:
                # Increase defection probability to 0.6 if opponent is cooperative
                if random.random() < 0.6:
                    return False
        # Avoid defectors
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False
        # If opponent has defected recently against us, defect
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False
        # If opponent's global cooperation rate is very high, defect more often
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.1:
                # Defect with high probability, but not always to avoid reputation damage
                if random.random() < 0.9:
                    return True
        # If our reputation is low, cooperate more to rebuild
        if self.my_reputation_count > 10:
            if self.my_reputation_score < 0.4:
                return True
        # Decision threshold: slightly more aggressive (lower threshold)
        return self.trust.get(opp, 0.5) >= 0.3

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        d_act = (donor_action == 'cooperate')
        r_act = (recipient_action == 'cooperate')
        # Update global counts
        if donor_id not in self.defect_count:
            self.defect_count[donor_id] = 0
            self.coop_count[donor_id] = 0
        if d_act:
            self.coop_count[donor_id] += 1
        else:
            self.defect_count[donor_id] += 1
        total = self.defect_count.get(donor_id, 0) + self.coop_count.get(donor_id, 0)
        if total > 0:
            self.coop_rate_others[donor_id] = self.coop_count.get(donor_id, 0) / total
            self.opp_total[donor_id] = total
            self.opp_def_rate[donor_id] = self.defect_count.get(donor_id, 0) / total
        # Track recent global cooperation for donor
        if donor_id not in self.opp_recent_global_coop:
            self.opp_recent_global_coop[donor_id] = []
        self.opp_recent_global_coop[donor_id].append(d_act)
        if len(self.opp_recent_global_coop[donor_id]) > 5:
            self.opp_recent_global_coop[donor_id] = self.opp_recent_global_coop[donor_id][-5:]
        # Track recent global defections specifically
        if donor_id not in self.opp_recent_def_global:
            self.opp_recent_def_global[donor_id] = []
        self.opp_recent_def_global[donor_id].append(not d_act)
        if len(self.opp_recent_def_global[donor_id]) > 5:
            self.opp_recent_def_global[donor_id] = self.opp_recent_def_global[donor_id][-5:]
        # Track overall global coop rate
        if donor_id not in self.opp_global_coop:
            self.opp_global_coop[donor_id] = [0, 0]
        if d_act:
            self.opp_global_coop[donor_id][0] += 1
        self.opp_global_coop[donor_id][1] += 1
        # Track per-pair history
        key = (donor_id, recipient_id)
        if key not in self.history:
            self.history[key] = []
        self.history[key].append(d_act)
        # Track own interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            own_key = (self.agent_id, other)
            if own_key not in self.own_interactions:
                self.own_interactions[own_key] = []
            if donor_id == self.agent_id:
                my_act = d_act
                opp_act = r_act
            else:
                my_act = r_act
                opp_act = d_act
            self.own_interactions[own_key].append((my_act, opp_act))
            if other not in self.recent_opp_actions:
                self.recent_opp_actions[other] = []
            self.recent_opp_actions[other].append(opp_act)
            if len(self.recent_opp_actions[other]) > 3:
                self.recent_opp_actions[other] = self.recent_opp_actions[other][-3:]
            if opp_act:
                self.opp_def_streak[other] = 0
            else:
                self.opp_def_streak[other] = self.opp_def_streak.get(other, 0) + 1
            self.interaction_count[other] = self.interaction_count.get(other, 0) + 1
            if not opp_act:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0) + 1
            else:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0)
            if self.interaction_count[other] > 0:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0) / self.interaction_count[other]
            if other not in self.coop_rate_with_us:
                self.coop_rate_with_us[other] = [0, 0]
            if opp_act:
                self.coop_rate_with_us[other][0] += 1
            self.coop_rate_with_us[other][1] += 1
            # Update trust
            if opp_act:
                self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.15)
            else:
                streak = self.opp_def_streak.get(other, 0)
                penalty = 0.2 if streak >= 2 else 0.1
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - penalty)
            if donor_id == self.agent_id:
                self.my_recent_actions.append(my_act)
                if len(self.my_recent_actions) > 3:
                    self.my_recent_actions = self.my_recent_actions[-3:]
                if my_act:
                    self.my_total_coops += 1
                else:
                    self.my_total_defects += 1
                    if other not in self.defects_against:
                        self.defects_against[other] = 0
                    self.defects_against[other] += 1
                # Update recent reputation
                self.my_recent_reputation.append(my_act)
                if len(self.my_recent_reputation) > 10:
                    self.my_recent_reputation = self.my_recent_reputation[-10:]
                # Update our reputation score (simple: coop increases, defect decreases)
                self.my_reputation_count += 1
                if my_act:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 1) / self.my_reputation_count
                else:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 0) / self.my_reputation_count
        # Third-party reputation
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            total = self.defect_count.get(donor_id, 0) + self.coop_count.get(donor_id, 0)
            if total > 20:
                def_rate = self.defect_count.get(donor_id, 0) / total
                if def_rate > 0.75:
                    self.trust[donor_id] = min(self.trust.get(donor_id, 0.5), 0.15)
                elif def_rate < 0.15:
                    self.trust[donor_id] = max(self.trust.get(donor_id, 0.5), 0.85)
                elif def_rate < 0.4:
                    self.trust[donor_id] = max(self.trust.get(donor_id, 0.5), 0.6)

