        self.round += 1
        opponent = self._ctx_opponent_id
        if opponent not in self.interaction_count or self.interaction_count[opponent] < 3:
            opp_rep = self.reputation.get(opponent, 0)
            if opp_rep > 2:
                return True
            elif opp_rep < -3:
                return False
            else:
                return random.random() < 0.7

        coop_rate = self.opp_coop_rate.get(opponent, 0.5)
        opp_rep = self.reputation.get(opponent, 0)
        recent_opp = self.recent_opp_actions.get(opponent, [])
        opp_coop_streak = self.opp_coop_streak.get(opponent, 0)
        opp_defect_streak = self.opp_defect_streak.get(opponent, 0)

        coop_list = self.opp_coop_list.get(opponent, [])
        if len(coop_list) >= 5:
            mean_coop = sum(coop_list) / len(coop_list)
            variance = sum((x - mean_coop) ** 2 for x in coop_list) / len(coop_list)
            self.opp_coop_variance[opponent] = variance
        else:
            variance = 1.0

        # Enhanced exploitation with reputation management
        if coop_rate >= 0.7 and opp_rep > 2 and opp_coop_streak >= 1:
            if self.self_rep_estimate < -6:
                return True
            if self.my_defect_streak >= 4:
                return True
            if recent_opp and not recent_opp[-1]:
                return True
            recent_def = self.recent_defect_vs.get(opponent, 0)
            recent_coop = self.recent_coop_vs.get(opponent, 0)
            if recent_def > recent_coop + 1:
