        self.my_recent_defections = []
        self.my_recent_window = 15

    def decide(self) -> bool:
        self.round += 1
        opponent = self._ctx_opponent_id
        self.last_interaction_round[opponent] = self.round

        # Reputation boosting: if my rep is low, cooperate often to recover
        if self.self_rep_estimate < -10:
            if self.opp_coop_rate.get(opponent, 0.5) < 0.3:
                return False
            return True

        # Initial interactions: adapt based on reputation
        if opponent not in self.interaction_count or self.interaction_count[opponent] < 3:
            opp_rep = self.reputation.get(opponent, 0)
            if opp_rep > 2:
                return True
            elif opp_rep < -3:
                return False
            else:
                return random.random() < 0.75

        coop_rate = self.opp_coop_rate.get(opponent, 0.5)
        opp_rep = self.reputation.get(opponent, 0)
        recent_opp = self.recent_opp_actions.get(opponent, [])
        opp_coop_streak = self.opp_coop_streak.get(opponent, 0)
        opp_defect_streak = self.opp_defect_streak.get(opponent, 0)

        # Compute variance in opponent's cooperation
        coop_list = self.opp_coop_list.get(opponent, [])
        if len(coop_list) >= 5:
            mean_coop = sum(coop_list) / len(coop_list)
            variance = sum((x - mean_coop) ** 2 for x in coop_list) / len(coop_list)
            self.opp_coop_variance[opponent] = variance
        else:
            variance = 1.0

        # Track opponent's reputation trajectory
        if opponent not in self.opponent_rep_traj:
            self.opponent_rep_traj[opponent] = []
        self.opponent_rep_traj[opponent].append(opp_rep)
        if len(self.opponent_rep_traj[opponent]) > 10:
            self.opponent_rep_traj[opponent] = self.opponent_rep_traj[opponent][-10:]
        if len(self.opponent_rep_traj[opponent]) >= 5:
            rep_trend = self.opponent_rep_traj[opponent][-1] - self.opponent_rep_traj[opponent][-5]
        else:
            rep_trend = 0

        # More aggressive exploitation: if opponent is very cooperative and has decent reputation, defect often
        if coop_rate >= 0.7 and opp_rep > 2 and opp_coop_streak >= 1:
            # But avoid over-exploitation if my reputation is too low or I've been defecting a lot
            if self.self_rep_estimate < -6:
                return True
            if self.my_defect_streak >= 4:
                return True
            if recent_opp and not recent_opp[-1]:
                return True
            recent_def = self.recent_defect_vs.get(opponent, 0)
            recent_coop = self.recent_coop_vs.get(opponent, 0)
            if recent_def > recent_coop:
                return True
            # Defect with high probability, but sometimes cooperate to maintain relationship
            exploit_prob = 0.95 if variance < 0.15 else 0.85
            if self.last_interaction_round.get(opponent, 0) > 5:
                exploit_prob = 0.97
            # If opponent's reputation is declining, defect more (they might be losing reputation anyway)
            if rep_trend < -2:
                exploit_prob = min(0.99, exploit_prob + 0.05)
            if random.random() < exploit_prob:
                return False
            else:
                return True

        if coop_rate <= 0.3:
            return False

        last_opp = self.last_opp_action.get(opponent, True)
        if last_opp:
            # New: if opponent is very cooperative but not yet exploited, exploit a bit more
            if coop_rate >= 0.8 and opp_rep > 0:
                # But ensure I don't defect too often overall
                recent_my_def_rate = sum(self.my_recent_defections) / max(1, len(self.my_recent_defections))
                if recent_my_def_rate < 0.4:
                    return random.random() < 0.15
            return True
        else:
            if opp_defect_streak >= 2:
                return False
            if opp_rep > 0 and self.my_defect_count / max(1, self.my_total_actions) < 0.5:
                if self.my_forgiveness_count < 3 and random.random() < 0.4:
                    self.my_forgiveness_count += 1
