        self.opp_reputation_avg = {}
        self.exploit_threshold = 0.8
        self.exploit_count = 0
        self.max_exploit_count = 5
        self.last_opp_action_global = {}
        self.recent_defect_vs = {}
        self.recent_coop_vs = {}
        self.opponent_rep_history = {}
        self.total_reputation_updates = {}
        self.opp_coop_variance = {}
        self.opp_coop_list = {}
        self.exploit_opportunity = 0
        self.reputation_boosting = False
        self.boost_rounds = 0
        self.max_boost_rounds = 5
        self.boost_target = None
        self.forgiven_opponents = set()
        self.coop_after_defect_count = {}
        self.recent_rep_change = {}
        self.trust_scores = {}  # new: dynamic trust per opponent
        self.coop_ratio_global = 0.5  # new: estimate global cooperation

    def decide(self) -> bool:
        self.round += 1
        opponent = self._ctx_opponent_id
        # Update global cooperation estimate periodically
        if self.round % 10 == 0:
            if self.opponent_history:
                all_actions = [a for hist in self.opponent_history.values() for a in hist]
                if all_actions:
                    self.coop_ratio_global = sum(all_actions) / len(all_actions)

        # Early interaction - trust reputation and global trends
        if opponent not in self.interaction_count or self.interaction_count[opponent] < 3:
            opp_rep = self.reputation.get(opponent, 0)
            if opp_rep > 2:
                return True
            elif opp_rep < -3:
                return False
            else:
                # Use global cooperation rate to decide
                return random.random() < max(0.5, self.coop_ratio_global)

        coop_rate = self.opp_coop_rate.get(opponent, 0.5)
        opp_rep = self.reputation.get(opponent, 0)
        recent_opp = self.recent_opp_actions.get(opponent, [])
        opp_coop_streak = self.opp_coop_streak.get(opponent, 0)
        opp_defect_streak = self.opp_defect_streak.get(opponent, 0)

        coop_list = self.opp_coop_list.get(opponent, [])
        if len(coop_list) >= 5:
            mean_coop = sum(coop_list) / len(coop_list)
            variance = sum((x - mean_coop) ** 2 for x in coop_list) / len(coop_list)
            self.opp_coop_variance[opponent] = variance
        else:
            variance = 1.0

        # Dynamic trust score: combine coop rate, reputation, variance, streaks
        trust = coop_rate * 0.4 + (opp_rep > 0) * 0.2 + (1 - variance) * 0.2
        if opp_coop_streak > 0:
            trust += 0.1
        if opp_defect_streak > 0:
            trust -= 0.2
        self.trust_scores[opponent] = trust

        # Enhanced exploitation with reputation management
        if coop_rate >= 0.7 and opp_rep > 2 and opp_coop_streak >= 1:
            # Check if we can afford to defect (reputation buffer)
            if self.self_rep_estimate > 3:
                # High reputation, safe to exploit more
                if self.my_defect_streak >= 3:
                    return True
                if recent_opp and not recent_opp[-1]:
                    return True
                recent_def = self.recent_defect_vs.get(opponent, 0)
                recent_coop = self.recent_coop_vs.get(opponent, 0)
                if recent_def > recent_coop + 1:
                    return True
                # Adaptive exploitation probability based on trust and variance
                if variance < 0.15 and trust > 0.7:
                    exploit_prob = 0.95
                else:
                    exploit_prob = 0.88
                # Occasional cooperation to maintain relationship and reputation
                if random.random() < exploit_prob:
                    return False
                else:
                    return True
            elif self.self_rep_estimate > -2:
                # Medium reputation - exploit moderately
                if self.my_defect_streak >= 5:
                    return True
                if recent_opp and not recent_opp[-1]:
                    return True
                if variance < 0.2:
                    exploit_prob = 0.85
                else:
                    exploit_prob = 0.75
                if random.random() < exploit_prob:
                    return False
                else:
                    return True
            else:
                # Low reputation - need to rebuild, cooperate mostly
                if self.my_defect_streak >= 6:
                    return True
                if random.random() < 0.2:
                    return False
                else:
                    return True

        # Defect against very uncooperative opponents
        if coop_rate <= 0.25:
            return False

        # Tit-for-tat with forgiveness for high-reputation opponents
        last_opp = self.last_opp_action.get(opponent, True)
        if last_opp:
            return True
        else:
            # If opponent just defected, check if it's a blip or pattern
            if opp_defect_streak >= 2:
                return False
            # For high reputation opponents, forgive more often
            if opp_rep > 2 and self.self_rep_estimate > 0:
                if opponent not in self.forgiven_opponents and random.random() < 0.6:
                    self.forgiven_opponents.add(opponent)
                    return True
                else:
                    return False
            elif opp_rep > 0:
                if opponent not in self.forgiven_opponents and random.random() < 0.4:
                    self.forgiven_opponents.add(opponent)
                    return True
                else:
                    return False
            else:
                return False

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        donor_coop = (donor_action == 'cooperate')
        recipient_coop = (recipient_action == 'cooperate')

        # Asymmetric reputation update with adaptive weights
        # If we have low reputation, we want to cooperate more to rebuild
        if self.self_rep_estimate < 0:
            coop_weight = 1.8
            defect_weight = -2.0
        else:
            coop_weight = 1.0
            defect_weight = -2.5

        self.reputation[donor_id] = self.reputation.get(donor_id, 0) + (coop_weight if donor_coop else defect_weight)
        self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + (coop_weight if recipient_coop else defect_weight)
        self.global_rep[donor_id] = self.reputation.get(donor_id, 0)
        self.global_rep[recipient_id] = self.reputation.get(recipient_id, 0)

        if not donor_coop:
            self.defect_rep[donor_id] = self.defect_rep.get(donor_id, 0) + 1
        if not recipient_coop:
            self.defect_rep[recipient_id] = self.defect_rep.get(recipient_id, 0) + 1

        for agent_id, agent_coop in [(donor_id, donor_coop), (recipient_id, recipient_coop)]:
            if agent_id not in self.recent_opp_actions:
                self.recent_opp_actions[agent_id] = []
            self.recent_opp_actions[agent_id].append(agent_coop)
