                self.my_reputation_count += 1
                if my_act:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 1) / self.my_reputation_count
                else:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 0) / self.my_reputation_count
        # Third-party reputation
