    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        donor_coop = (donor_action == 'cooperate')
        recipient_coop = (recipient_action == 'cooperate')

        # Asymmetric reputation update with adaptive weights
        if self.self_rep_estimate < 0:
            coop_weight = 1.8
            defect_weight = -2.0
        else:
            coop_weight = 1.0
            defect_weight = -2.5

        self.reputation[donor_id] = self.reputation.get(donor_id, 0) + (coop_weight if donor_coop else defect_weight)
        self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + (coop_weight if recipient_coop else defect_weight)
        self.global_rep[donor_id] = self.reputation.get(donor_id, 0)
        self.global_rep[recipient_id] = self.reputation.get(recipient_id, 0)

        # Track rep history for slope calculation
        for agent_id in [donor_id, recipient_id]:
            if agent_id not in self.rep_history:
                self.rep_history[agent_id] = []
            self.rep_history[agent_id].append(self.reputation.get(agent_id, 0))
            if len(self.rep_history[agent_id]) > 10:
                self.rep_history[agent_id] = self.rep_history[agent_id][-10:]
            if len(self.rep_history[agent_id]) >= 3:
                x = list(range(len(self.rep_history[agent_id])))
                y = self.rep_history[agent_id]
                n = len(x)
                if n > 1:
                    x_mean = sum(x) / n
                    y_mean = sum(y) / n
                    num = sum((x[i] - x_mean) * (y[i] - y_mean) for i in range(n))
                    den = sum((x[i] - x_mean) ** 2 for i in range(n))
                    if den > 0:
                        self.opponent_rep_slope[agent_id] = num / den
                    else:
                        self.opponent_rep_slope[agent_id] = 0

        # Additional penalty for repeated defection by an agent
        if not donor_coop:
            self.defect_rep[donor_id] = self.defect_rep.get(donor_id, 0) + 1
            if self.defect_rep[donor_id] > 3:
                self.reputation[donor_id] -= self.defect_rep_penalty
        if not recipient_coop:
            self.defect_rep[recipient_id] = self.defect_rep.get(recipient_id, 0) + 1
            if self.defect_rep[recipient_id] > 3:
                self.reputation[recipient_id] -= self.defect_rep_penalty

        for agent_id, agent_coop in [(donor_id, donor_coop), (recipient_id, recipient_coop)]:
            if agent_id not in self.recent_opp_actions:
                self.recent_opp_actions[agent_id] = []
            self.recent_opp_actions[agent_id].append(agent_coop)
            if len(self.recent_opp_actions[agent_id]) > self.recent_window:
                self.recent_opp_actions[agent_id] = self.recent_opp_actions[agent_id][-self.recent_window:]
            if agent_coop:
                self.opp_coop_streak[agent_id] = self.opp_coop_streak.get(agent_id, 0) + 1
                self.opp_defect_streak[agent_id] = 0
            else:
                self.opp_defect_streak[agent_id] = self.opp_defect_streak.get(agent_id, 0) + 1
                self.opp_coop_streak[agent_id] = 0
            if agent_id not in self.opp_coop_list:
                self.opp_coop_list[agent_id] = []
            self.opp_coop_list[agent_id].append(1 if agent_coop else 0)
            if len(self.opp_coop_list[agent_id]) > 20:
                self.opp_coop_list[agent_id] = self.opp_coop_list[agent_id][-20:]

        if donor_id == self.agent_id:
            self.last_my_action[recipient_id] = donor_coop
            self.last_opp_action[recipient_id] = recipient_coop
            if recipient_id not in self.interaction_count:
                self.interaction_count[recipient_id] = 0
                self.opp_coop_rate[recipient_id] = 0.0
                self.opponent_history[recipient_id] = []
            self.interaction_count[recipient_id] += 1
            self.opponent_history[recipient_id].append(recipient_coop)
            hist = self.opponent_history[recipient_id]
            self.opp_coop_rate[recipient_id] = sum(hist) / len(hist)
            self.my_history.append((recipient_id, donor_coop, recipient_coop))
            self.my_total_actions += 1
            if not donor_coop:
                self.my_defect_count += 1
                self.my_defect_streak += 1
                self.recent_defect_vs[recipient_id] = self.recent_defect_vs.get(recipient_id, 0) + 1
                self.recent_coop_vs[recipient_id] = self.recent_coop_vs.get(recipient_id, 0)
            else:
                self.my_defect_streak = 0
                self.recent_coop_vs[recipient_id] = self.recent_coop_vs.get(recipient_id, 0) + 1
                self.recent_defect_vs[recipient_id] = self.recent_defect_vs.get(recipient_id, 0)
            self.self_rep_estimate += (coop_weight if donor_coop else defect_weight)
            self.self_rep_history.append(self.self_rep_estimate)
            if len(self.self_rep_history) > 10:
