    def decide(self) -> bool:
        self.round += 1
        opponent = self._ctx_opponent_id
        # Update global cooperation estimate periodically
        if self.round % 10 == 0:
            if self.opponent_history:
                all_actions = [a for hist in self.opponent_history.values() for a in hist]
                if all_actions:
                    self.coop_ratio_global = sum(all_actions) / len(all_actions)

        # Early interaction - trust reputation and global trends, but be more cautious
        if opponent not in self.interaction_count or self.interaction_count[opponent] < 3:
            opp_rep = self.reputation.get(opponent, 0)
            if opp_rep > 3:
                return True
            elif opp_rep < -2:
                return False
            else:
                # Use global cooperation rate with slight defection bias for low info
                return random.random() < max(0.45, self.coop_ratio_global - 0.05)

        coop_rate = self.opp_coop_rate.get(opponent, 0.5)
        opp_rep = self.reputation.get(opponent, 0)
        recent_opp = self.recent_opp_actions.get(opponent, [])
        opp_coop_streak = self.opp_coop_streak.get(opponent, 0)
        opp_defect_streak = self.opp_defect_streak.get(opponent, 0)

        coop_list = self.opp_coop_list.get(opponent, [])
        if len(coop_list) >= 5:
            mean_coop = sum(coop_list) / len(coop_list)
            variance = sum((x - mean_coop) ** 2 for x in coop_list) / len(coop_list)
            self.opp_coop_variance[opponent] = variance
        else:
            variance = 1.0

        # Dynamic trust score with reputation slope
        trust = coop_rate * 0.35 + (opp_rep > 0) * 0.15 + (1 - variance) * 0.2
        if opp_coop_streak > 0:
            trust += 0.1
        if opp_defect_streak > 0:
            trust -= 0.2
        # Add slope info: if opponent's rep is improving, they may be building trust
        slope = self.opponent_rep_slope.get(opponent, 0)
        if slope > 0.2:
            trust += 0.1
        elif slope < -0.2:
            trust -= 0.1
        self.trust_scores[opponent] = trust

        # Enhanced exploitation with reputation management and slope awareness
        if coop_rate >= 0.7 and opp_rep > 2 and opp_coop_streak >= 1:
            # Check if we can afford to defect (reputation buffer)
            if self.self_rep_estimate > 3:
                # High reputation, safe to exploit more, but watch own rep trend
                if self.my_defect_streak >= 3:
                    return True
                if recent_opp and not recent_opp[-1]:
                    return True
                recent_def = self.recent_defect_vs.get(opponent, 0)
                recent_coop = self.recent_coop_vs.get(opponent, 0)
                if recent_def > recent_coop + 1:
                    return True
                # Adaptive exploitation probability based on trust and variance
                if variance < 0.15 and trust > 0.7:
                    exploit_prob = 0.97
                else:
                    exploit_prob = 0.9
                # Occasional cooperation to maintain relationship and reputation
                if random.random() < exploit_prob:
                    return False
                else:
