        else:
            # If opponent just defected, check if it's a blip or pattern
            if opp_defect_streak >= 2:
                return False
            # For high reputation opponents, forgive more often, but consider slope
            if opp_rep > 2 and self.self_rep_estimate > 0:
                if opponent not in self.forgiven_opponents and random.random() < 0.65:
                    self.forgiven_opponents.add(opponent)
                    return True
                else:
                    return False
            elif opp_rep > 0:
                if opponent not in self.forgiven_opponents and random.random() < 0.45:
                    self.forgiven_opponents.add(opponent)
                    return True
                else:
                    return False
            else:
                return False

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        donor_coop = (donor_action == 'cooperate')
        recipient_coop = (recipient_action == 'cooperate')

        # Asymmetric reputation update with adaptive weights
        if self.self_rep_estimate < 0:
            coop_weight = 1.8
            defect_weight = -2.0
        else:
            coop_weight = 1.0
            defect_weight = -2.5

        self.reputation[donor_id] = self.reputation.get(donor_id, 0) + (coop_weight if donor_coop else defect_weight)
        self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + (coop_weight if recipient_coop else defect_weight)
        self.global_rep[donor_id] = self.reputation.get(donor_id, 0)
        self.global_rep[recipient_id] = self.reputation.get(recipient_id, 0)

        # Track rep history for slope calculation
        for agent_id in [donor_id, recipient_id]:
            if agent_id not in self.rep_history:
                self.rep_history[agent_id] = []
            self.rep_history[agent_id].append(self.reputation.get(agent_id, 0))
            if len(self.rep_history[agent_id]) > 10:
                self.rep_history[agent_id] = self.rep_history[agent_id][-10:]
