            if other not in self.recent_opp_actions:
                self.recent_opp_actions[other] = []
            self.recent_opp_actions[other].append(opp_act)
            if len(self.recent_opp_actions[other]) > 3:
                self.recent_opp_actions[other] = self.recent_opp_actions[other][-3:]
            if opp_act:
                self.opp_def_streak[other] = 0
            else:
                self.opp_def_streak[other] = self.opp_def_streak.get(other, 0) + 1
            self.interaction_count[other] = self.interaction_count.get(other, 0) + 1
            if not opp_act:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0) + 1
            else:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0)
            if self.interaction_count[other] > 0:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0) / self.interaction_count[other]
            if other not in self.coop_rate_with_us:
                self.coop_rate_with_us[other] = [0, 0]
            if opp_act:
                self.coop_rate_with_us[other][0] += 1
            self.coop_rate_with_us[other][1] += 1
            # Update trust
            if opp_act:
                self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.15)
            else:
                streak = self.opp_def_streak.get(other, 0)
                penalty = 0.2 if streak >= 2 else 0.1
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - penalty)
            if donor_id == self.agent_id:
                self.my_recent_actions.append(my_act)
                if len(self.my_recent_actions) > 3:
                    self.my_recent_actions = self.my_recent_actions[-3:]
                if my_act:
                    self.my_total_coops += 1
                else:
                    self.my_total_defects += 1
                    if other not in self.defects_against:
                        self.defects_against[other] = 0
                    self.defects_against[other] += 1
                # Update recent reputation
                self.my_recent_reputation.append(my_act)
                if len(self.my_recent_reputation) > 10:
                    self.my_recent_reputation = self.my_recent_reputation[-10:]
                # Update our reputation score (simple: coop increases, defect decreases)
                self.my_reputation_count += 1
                if my_act:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 1) / self.my_reputation_count
                else:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 0) / self.my_reputation_count
                # Track recent action window for reputation management
                self.recent_action_window.append(my_act)
                if len(self.recent_action_window) > 5:
