import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.history = {}
        self.own_interactions = {}
        self.defect_count = {}
        self.coop_count = {}
        self.trust = {}
        self.round_num = 0
        self.generation = 0
        self._ctx_opponent_id = None
        self.recent_opp_actions = {}
        self.coops_with = {}
        self.opp_def_streak = {}
        self.my_recent_actions = []
        self.coop_rate_others = {}
        self.def_rate_against_us = {}
        self.interaction_count = {}
        self.opp_recent_def = {}
        self.my_total_coops = 0
        self.my_total_defects = 0
        self.coop_rate_with_us = {}
        self.defects_against = {}
        self.forgiveness = {}
        self.opp_recent_global_coop = {}
        self.my_recent_reputation = []
        self.opp_reaction_to_def = {}
        self.my_reputation_score = 0.5
        self.my_reputation_count = 0
        self.opp_global_coop = {}
        self.opp_recent_general_coop = {}
        self.recent_global_def = {}
        self.my_recent_actions_global = []
        self.global_coop_rate = {}
        self.cooperators = set()
        self.defectors = set()
        self.last_opp_action = {}
        self.opp_coop_streak = {}
        self.my_def_streak = 0
        # New: track opponent's recent global cooperation rate window
        self.opp_recent_coop_window = {}
        # New: track how many times we've exploited each opponent
        self.exploit_count = {}
        # New: track opponent's response to our defection
        self.opp_retaliation = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.2
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.4
            else:
                self.trust[opp] = 0.5

        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.25)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.35)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.2)

        # Exploit pure cooperators more aggressively and adaptively
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 8:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                # Defect every interaction (fully exploit)
                return True
            elif def_rate < 0.15:
                # Defect with high probability
                if random.random() < 0.9:
                    return True
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False

        # Reputation engineering: more aggressive rebuild when reputation is low
        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if my_reputation < 0.45:
                # Cooperate even with untrusted opponents to rebuild quickly
                if self.trust.get(opp, 0.5) < 0.5:
                    return True
                else:
                    return True

        # Strategic exploitation: defect more often when reputation is high
        if self.my_total_coops + self.my_total_defects > 5:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if my_reputation > 0.65 and self.trust.get(opp, 0.5) > 0.75:
                # Increase defection probability to 0.5
                if random.random() < 0.5:
                    return False

        # Avoid defectors based on both personal and global info
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.4:
            return False
        # Global defection rate
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 10:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate > 0.6:
                return False

        # If opponent has defected recently against us, defect
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 1 and not recent[-1]:
            return False

        # If opponent's global cooperation rate is very high, defect more often
        if total_global > 15:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.1:
                # Defect with high probability
                if random.random() < 0.95:
                    return True

        # If our reputation is low, cooperate more to rebuild
        if self.my_reputation_count > 10:
            if self.my_reputation_score < 0.45:
                return True

        # New: If opponent is a known pure cooperator, always defect
        if opp in self.cooperators:
            return True

        # New: Exploit opponents with long cooperation streaks (predictable cooperators)
        if opp in self.opp_coop_streak and self.opp_coop_streak[opp] >= 4:
            # They've cooperated 4+ times in a row, they'll likely keep cooperating
            return True

        # New: If we've defected many times in a row, rebuild reputation
        if self.my_def_streak >= 3 and self.my_reputation_count > 10:
            if self.my_reputation_score < 0.6:
                return True

        # New: Exploit opponents who don't retaliate after our defection
        if opp in self.opp_retaliation:
            if not self.opp_retaliation[opp] and self.exploit_count.get(opp, 0) > 1:
                # They don't punish us, keep exploiting
                return True

        # Decision threshold: slightly more aggressive
        return self.trust.get(opp, 0.5) >= 0.3

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        d_act = (donor_action == 'cooperate')
        r_act = (recipient_action == 'cooperate')
        # Update global counts
        if donor_id not in self.defect_count:
            self.defect_count[donor_id] = 0
            self.coop_count[donor_id] = 0
        if d_act:
            self.coop_count[donor_id] += 1
        else:
            self.defect_count[donor_id] += 1
