            else:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0)
            if self.interaction_count[other] > 0:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0) / self.interaction_count[other]
            if other not in self.coop_rate_with_us:
                self.coop_rate_with_us[other] = [0, 0]
            if opp_act:
                self.coop_rate_with_us[other][0] += 1
            self.coop_rate_with_us[other][1] += 1
            # Track reaction to our defection: did they defect next time?
            if not my_act:
                if other not in self.opp_reaction_to_def:
                    self.opp_reaction_to_def[other] = []
                # Record whether they defected after our defection
                if not opp_act:
                    self.opp_reaction_to_def[other].append(True)
