        self.exploit_mode = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        if opp not in self.interactions_with_opp:
            self.interactions_with_opp[opp] = 0
            self.my_coops_with_opp[opp] = 0

        # Initialize trust if unknown
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6

        # Compute our current reputation
        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if len(self.my_recent_reputation) > 0:
                recent_coops = sum(1 for a in self.my_recent_reputation if a)
                recent_total = len(self.my_recent_reputation)
                my_reputation = recent_coops / recent_total
            self.reputation_good = my_reputation > 0.6
        else:
            my_reputation = 0.5
            self.reputation_good = False

        # Identify pure cooperators and exploit them ruthlessly when reputation is high
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                # Pure cooperator: defect always if reputation above 0.5, otherwise defect most of the time
                if my_reputation > 0.5:
                    return True
                else:
                    # Even with lower reputation, defect 80% of the time
                    if random.random() < 0.8:
                        return True
                    else:
                        return False
            elif def_rate > 0.7:
                # Defector: always cooperate to avoid reputation damage and try to build trust
                self.trust[opp] = 0.0
                return False

        # Reputation engineering: if reputation is low, cooperate even with defectors to rebuild
        if my_reputation < 0.4:
            # If we have a good reputation trend, defect more; otherwise cooperate
            if len(self.reputation_trend) >= 3 and sum(self.reputation_trend[-3:]) >= 2:
                # Reputation is recovering, resume exploitation
                pass
            else:
                # Cooperate to rebuild reputation
                return True

        # Strategic exploitation: defect more often when reputation is high and opponent is cooperative
        if my_reputation > 0.7:
            # Check opponent's recent cooperation with us
            recent_with_us = self.recent_coop_with_us.get(opp, [])
            if len(recent_with_us) >= 3:
                coop_rate = sum(recent_with_us) / len(recent_with_us)
                if coop_rate > 0.8:
                    # Opponent cooperates often with us: defect with high probability
                    if random.random() < 0.9:
                        return True
                    else:
                        return False
            # Check opponent's global cooperation rate
            total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total_global > 20:
                global_def_rate = self.defect_count.get(opp, 0) / total_global
                if global_def_rate < 0.1:
                    # Very cooperative globally: defect with high probability
                    if random.random() < 0.9:
                        return True
                    else:
                        return False

        # Avoid defectors: if opponent has defected often against us, cooperate
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            # If we have a high reputation, we can afford to defect once in a while
            if my_reputation > 0.7 and random.random() < 0.3:
                return True
            return False

        # Recent opponent actions: if opponent defected twice in a row against us, cooperate
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            # But if we have high reputation, defect to exploit their defection
            if my_reputation > 0.6 and random.random() < 0.5:
                return True
            return False

        # If opponent has a long cooperation streak, exploit them
        if opp in self.opp_coop_streak:
            if self.opp_coop_streak[opp] >= 3:
                # Cooperate streak of 3+: defect if reputation is decent
                if my_reputation > 0.4:
                    return True
                else:
                    return False

        # Default: use trust threshold, but slightly more aggressive
        return self.trust.get(opp, 0.5) >= 0.3

