            if len(self.recent_coop_with_us[other]) > 5:
                self.recent_coop_with_us[other] = self.recent_coop_with_us[other][-5:]
            # Update trust
            if opp_act:
                self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.15)
            else:
                streak = self.opp_def_streak.get(other, 0)
                penalty = 0.2 if streak >= 2 else 0.1
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - penalty)
            if donor_id == self.agent_id:
                self.my_recent_actions.append(my_act)
                if len(self.my_recent_actions) > 3:
                    self.my_recent_actions = self.my_recent_actions[-3:]
                if my_act:
                    self.my_total_coops += 1
                else:
                    self.my_total_defects += 1
                    if other not in self.defects_against:
                        self.defects_against[other] = 0
                    self.defects_against[other] += 1
                # Update recent reputation
                self.my_recent_reputation.append(my_act)
                if len(self.my_recent_reputation) > 10:
                    self.my_recent_reputation = self.my_recent_reputation[-10:]
                # Update our reputation score (simple: coop increases, defect decreases)
                self.my_reputation_count += 1
                if my_act:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 1) / self.my_reputation_count
                else:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 0) / self.my_reputation_count
                # Track reputation trend for adaptive exploitation
                if len(self.my_recent_reputation) >= 3:
                    recent_coops = sum(1 for a in self.my_recent_reputation[-3:] if a)
                    if recent_coops >= 2:
                        self.reputation_trend.append(1)
