            self.opp_consistency[donor_id].append(d_act)
            if len(self.opp_consistency[donor_id]) > 10:
                self.opp_consistency[donor_id] = self.opp_consistency[donor_id][-10:]
            # New: track recent global behavior for exploitation
            if donor_id not in self.opp_recent_behavior:
