                    elif recent_coops <= 1:
                        self.reputation_trend.append(-1)
                    else:
                        self.reputation_trend.append(0)
                    if len(self.reputation_trend) > 5:
                        self.reputation_trend = self.reputation_trend[-5:]
        # Third-party reputation
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            total = self.defect_count.get(donor_id, 0) + self.coop_count.get(donor_id, 0)
            if total > 20:
                def_rate = self.defect_count.get(donor_id, 0) / total
                if def_rate > 0.75:
                    self.trust[donor_id] = min(self.trust.get(donor_id, 0.5), 0.15)
                elif def_rate < 0.15:
                    self.trust[donor_id] = max(self.trust.get(donor_id, 0.5), 0.85)
                elif def_rate < 0.4:
                    self.trust[donor_id] = max(self.trust.get(donor_id, 0.5), 0.6)
            # Track opponent consistency
            if donor_id not in self.opp_consistency:
                self.opp_consistency[donor_id] = []
            self.opp_consistency[donor_id].append(d_act)
            if len(self.opp_consistency[donor_id]) > 10:
                self.opp_consistency[donor_id] = self.opp_consistency[donor_id][-10:]

