    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                if opp not in self.defects_against:
                    self.defects_against[opp] = 0
                if self.defects_against[opp] % 2 == 1:
                    return False
                else:
                    return True
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False
        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if my_reputation < 0.4:
                if self.trust.get(opp, 0.5) < 0.5:
                    return True
        if self.my_total_coops + self.my_total_defects > 10:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if my_reputation > 0.7 and self.trust.get(opp, 0.5) > 0.8:
                if random.random() < 0.5:
                    return False
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.1:
                if random.random() < 0.8:
                    return True
        if self.my_reputation_count > 10:
            if self.my_reputation_score < 0.4:
                return True
        if opp in self.opp_recent_coop_rate:
            recent_coop_rate = self.opp_recent_coop_rate[opp]
            if recent_coop_rate >= 0.8 and self.interaction_count.get(opp, 0) > 5:
                if random.random() < 0.6:
                    return True
        # NEW: Exploit opponents who are very cooperative globally but not tracked as pure
        if total_global > 30:
            global_coop_rate = self.coop_count.get(opp, 0) / total_global
            if global_coop_rate > 0.85 and self.trust.get(opp, 0.5) > 0.7:
                # Use a pattern: defect every 3rd interaction to maintain trust
                if opp not in self.defect_propensity:
                    self.defect_propensity[opp] = 0
                self.defect_propensity[opp] += 1
                if self.defect_propensity[opp] % 3 == 0:
                    return True
        # NEW: Avoid opponents who defect a lot but are not caught by def_rate_against_us
        if total_global > 15 and self.opp_def_rate.get(opp, 0.5) > 0.6:
            if self.interaction_count.get(opp, 0) > 8:
                return False
        # NEW: If opponent has a long cooperate streak with us, defect occasionally
        if opp in self.coop_streak:
            if self.coop_streak[opp] >= 4:
                if random.random() < 0.4:
                    return True
        # NEW: If we have cooperated many times in a row, defect to exploit
        if self.coop_streak.get(opp, 0) >= 3:
            if random.random() < 0.3:
                return True
        # NEW: If opponent is unknown but has high global coop, cooperate initially
        if self.interaction_count.get(opp, 0) == 0:
            if total_global > 5 and self.coop_count.get(opp, 0) / total_global > 0.6:
                return True
        # NEW: Adaptive exploitation with reputation maintenance
        if total_global > 40:
            global_coop_rate = self.coop_count.get(opp, 0) / total_global
            if global_coop_rate > 0.9 and self.trust.get(opp, 0.5) > 0.8:
                # Defect more frequently but never twice in a row
                if opp not in self.defect_schedule:
                    self.defect_schedule[opp] = False
                if not self.defect_schedule[opp]:
                    self.defect_schedule[opp] = True
                    return True
                else:
                    self.defect_schedule[opp] = False
        # NEW: Punish defectors immediately but forgive after one cooperation
        if opp in self.defects_against:
            if self.defects_against[opp] > 0 and self.trust.get(opp, 0.5) < 0.3:
                if self.coop_streak.get(opp, 0) == 0:
                    return False
        # NEW: Reputation engineering - cooperate more when our rep is low
        if self.my_reputation_count > 5:
            if self.my_reputation_score < 0.3:
                if random.random() < 0.7:
                    return True
        return self.trust.get(opp, 0.5) >= 0.3

