    def decide(self) -> bool:
        self.round += 1
        opponent = self._ctx_opponent_id
        # Early game: build reputation by cooperating mostly, but defect if opponent is clearly bad
        if opponent not in self.interaction_count or self.interaction_count[opponent] < 3:
            opp_rep = self.reputation.get(opponent, 0)
            if opp_rep > 2:
                return True
            elif opp_rep < -3:
                return False
            else:
                return random.random() < 0.7

        coop_rate = self.opp_coop_rate.get(opponent, 0.5)
        opp_rep = self.reputation.get(opponent, 0)
        recent_opp = self.recent_opp_actions.get(opponent, [])
        opp_coop_streak = self.opp_coop_streak.get(opponent, 0)
        opp_defect_streak = self.opp_defect_streak.get(opponent, 0)

        # Compute variance in opponent's cooperation to detect predictability
        coop_list = self.opp_coop_list.get(opponent, [])
        if len(coop_list) >= 5:
            mean_coop = sum(coop_list) / len(coop_list)
            variance = sum((x - mean_coop) ** 2 for x in coop_list) / len(coop_list)
            self.opp_coop_variance[opponent] = variance
        else:
            variance = 1.0

        # Compute opponent reputation trend and momentum
        prev_rep = self.opp_rep_prev.get(opponent, opp_rep)
        if opp_rep > prev_rep:
            self.opp_rep_trend[opponent] = 1
        elif opp_rep < prev_rep:
            self.opp_rep_trend[opponent] = -1
        else:
            self.opp_rep_trend[opponent] = 0
        self.opp_rep_prev[opponent] = opp_rep
        # Momentum: if reputation consistently rising, they may be a good target; if falling, avoid
        if opponent in self.opp_rep_trend:
            momentum = self.opp_rep_trend[opponent]
            if opponent in self.opp_rep_momentum:
                self.opp_rep_momentum[opponent] = 0.7 * self.opp_rep_momentum[opponent] + 0.3 * momentum
            else:
                self.opp_rep_momentum[opponent] = momentum
        else:
            self.opp_rep_momentum[opponent] = 0

        # Reputation engineering: periodically cooperate with a low-reputation opponent to boost my public image
        if self.reputation_engineer_active and opponent == self.reputation_engineer_opponent:
            if self.reputation_engineer_round < 5:
                self.reputation_engineer_round += 1
                return True  # Cooperate to show I'm forgiving and build my rep
            else:
                self.reputation_engineer_active = False
                self.reputation_engineer_opponent = None
                self.reputation_engineer_round = 0

        # If I've wronged this opponent recently, they might retaliate. Check their recent behavior.
        wronged_them = self.wronged_against.get(opponent, 0) > self.wronged_by.get(opponent, 0)
        if wronged_them and opp_defect_streak >= 1:
            return True

        # If opponent has wronged me, I might defect to punish but also consider reputation
        they_wronged_me = self.wronged_by.get(opponent, 0) > self.wronged_against.get(opponent, 0)
        if they_wronged_me and opp_coop_streak == 0:
            if random.random() < 0.8:
                return False

        # Exploit predictable cooperators, but be careful about reputation
        if coop_rate >= 0.7 and opp_rep > 2 and opp_coop_streak >= 1:
            if self.self_rep_estimate < -5:
                return True
            recent_def = self.recent_defect_vs.get(opponent, 0)
            recent_coop = self.recent_coop_vs.get(opponent, 0)
            if recent_def > recent_coop * 2:
                return True
            # Enhanced exploitation: consider reputation momentum and my own current reputation
            my_rep = self.self_rep_estimate
            # If my reputation is high, I can afford to defect more; if low, be more careful
            if my_rep > 10:
                exploit_prob = 0.95 if variance < 0.15 else 0.85
