                self.recent_defect_vs[donor_id] = self.recent_defect_vs.get(donor_id, 0) + 1
                self.recent_coop_vs[donor_id] = self.recent_coop_vs.get(donor_id, 0)
                self.wronged_by[donor_id] = self.wronged_by.get(donor_id, 0) + 1
            else:
                self.my_defect_streak = 0
                self.recent_coop_vs[donor_id] = self.recent_coop_vs.get(donor_id, 0) + 1
                self.recent_defect_vs[donor_id] = self.recent_defect_vs.get(donor_id, 0)
            self.self_rep_estimate += (1 if recipient_coop else -2)
            self.recent_my_actions.append(recipient_coop)
            if len(self.recent_my_actions) > self.recent_window:
                self.recent_my_actions = self.recent_my_actions[-self.recent_window:]

        # Update my reputation history based on public observations of my actions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # My action was just observed; update my rep history
            my_action_coop = donor_coop if donor_id == self.agent_id else recipient_coop
            # This is public knowledge; track my own reputation trend
            # We'll approximate by using the last known self_rep_estimate
            self.my_rep_history.append(self.self_rep_estimate)
            if len(self.my_rep_history) > 20:
                self.my_rep_history = self.my_rep_history[-20:]

        # Reputation engineering: if my reputation is low and I haven't recently engaged in it, start a campaign
        if self.self_rep_estimate < -2 and not self.reputation_engineer_active:
            # Find an opponent with low reputation to cooperate with
            candidates = [aid for aid, rep in self.reputation.items() if rep < 0 and aid != self.agent_id]
            if candidates:
                self.reputation_engineer_opponent = random.choice(candidates)
                self.reputation_engineer_active = True
                self.reputation_engineer_round = 0

