        self.round += 1
        opponent = self._ctx_opponent_id

        # Update EMA of self reputation
        self.self_rep_ema = self.self_rep_alpha * self.self_rep_estimate + (1 - self.self_rep_alpha) * self.self_rep_ema

        # Reputation engineering: boost reputation when low and cooldown expired
        if self.rep_engineer_active and opponent == self.rep_engineer_target:
            self.rep_engineer_round += 1
            if self.rep_engineer_round < 4:
                return True  # Cooperate to build reputation
            else:
                self.rep_engineer_active = False
                self.rep_engineer_target = None
                self.rep_engineer_round = 0
                self.rep_boost_cooldown = 5
                # After boosting, switch to exploitation if possible
                if self.self_rep_ema > 0:
                    return False  # Now exploit the naive opponent
                else:
                    return True

        # Early game: establish reputation but also probe opponents
        if opponent not in self.interaction_count or self.interaction_count[opponent] < 3:
            opp_rep = self.reputation.get(opponent, 0)
            if opp_rep > 3:
                return False  # Exploit high-rep cooperators early
            elif opp_rep < -2:
                return False  # Defectors get defected
            else:
                # Mixed strategy: cooperate more if opponent is unknown, but defect occasionally
                return random.random() < 0.6

        coop_rate = self.opp_coop_rate.get(opponent, 0.5)
        opp_rep = self.reputation.get(opponent, 0)
        recent_opp = self.recent_opp_actions.get(opponent, [])
        opp_coop_streak = self.opp_coop_streak.get(opponent, 0)
        opp_defect_streak = self.opp_defect_streak.get(opponent, 0)

        # Compute variance in opponent's cooperation
        coop_list = self.opp_coop_list.get(opponent, [])
        if len(coop_list) >= 5:
            mean_coop = sum(coop_list) / len(coop_list)
            variance = sum((x - mean_coop) ** 2 for x in coop_list) / len(coop_list)
            self.opp_coop_variance[opponent] = variance
        else:
            variance = 1.0

        # Track opponent reputation changes
        prev_rep = self.opp_rep_prev.get(opponent, opp_rep)
        rep_change = opp_rep - prev_rep
        self.opp_rep_change[opponent] = rep_change
        self.opp_rep_prev[opponent] = opp_rep

        # Adaptive exploitation: exploit consistent cooperators, but adapt to retaliation
        if coop_rate >= 0.65 and opp_rep > 1 and opp_coop_streak >= 2:
            # Check if opponent has punished me recently
            last_punish = self.opp_punishment.get(opponent, 0)
            if self.round - last_punish < 5:
                # Opponent is punishing me, back off
                return True
            # Exploit more aggressively if my reputation is high
            if self.self_rep_ema > 8:
                exploit_prob = 0.9 if variance < 0.2 else 0.8
            elif self.self_rep_ema > 0:
                exploit_prob = 0.8 if variance < 0.2 else 0.7
            else:
                exploit_prob = 0.6 if variance < 0.2 else 0.5

            # Increase exploitation if opponent's rep is rising (they're cooperating to build rep)
            if rep_change > 0.5:
                exploit_prob += 0.1

            # Reduce exploitation if I've defected too much recently to avoid reputation damage
            recent_def = self.recent_defect_vs.get(opponent, 0)
            if recent_def > 3:
                exploit_prob -= 0.2

            if random.random() < exploit_prob:
                self.consecutive_defects += 1
                self.last_action_was_coop = False
                return False
            else:
                self.consecutive_defects = 0
                self.last_action_was_coop = True
                return True

        # If opponent tends to defect, be tough but don't overdo it
        if coop_rate <= 0.3:
            # If I've defected too many times consecutively, cooperate to reset reputation
            if self.consecutive_defects >= self.max_consecutive_defects:
                self.consecutive_defects = 0
                self.last_action_was_coop = True
                return True
            self.consecutive_defects += 1
            self.last_action_was_coop = False
            return False

        # Tit-for-tat with forgiveness, but consider reputation dynamics
        last_opp = self.last_opp_action.get(opponent, True)
        if last_opp:
            self.last_action_was_coop = True
            return True
        else:
            # Opponent defected last time
            if opp_defect_streak >= 2:
                # Punish defectors but not indefinitely
                if self.consecutive_defects >= self.max_consecutive_defects:
                    self.consecutive_defects = 0
                    self.last_action_was_coop = True
                    return True
                self.consecutive_defects += 1
                self.last_action_was_coop = False
                return False
            else:
                # Forgive occasionally if opponent has good reputation and I need rep
                if opp_rep > 0 and self.self_rep_ema < 0:
                    self.last_action_was_coop = True
                    return True
                else:
                    if random.random() < 0.3:
                        self.last_action_was_coop = True
                        return True
                    else:
                        self.consecutive_defects += 1
                        self.last_action_was_coop = False
                        return False

