        if opponent not in self.interaction_count or self.interaction_count[opponent] < 3:
            opp_rep = self.reputation.get(opponent, 0)
            if opp_rep > 3:
                return True
            elif opp_rep < -2:
                return False
            else:
                # Use global cooperation rate with slight defection bias for low info
                return random.random() < max(0.45, self.coop_ratio_global - 0.05)

