    def decide(self) -> bool:
        self.round += 1
        opponent = self._ctx_opponent_id

        # Update global cooperation estimate periodically
        if self.round % 10 == 0:
            if self.opponent_history:
                all_actions = [a for hist in self.opponent_history.values() for a in hist]
                if all_actions:
                    self.coop_ratio_global = sum(all_actions) / len(all_actions)

        # Reputation management: if our reputation is too low, boost by cooperating
        if self.self_rep_estimate < self.self_rep_boost_threshold and not self.self_rep_boost_active:
            self.self_rep_boost_active = True
            self.self_rep_boost_rounds = 5
        if self.self_rep_boost_active:
            self.self_rep_boost_rounds -= 1
            if self.self_rep_boost_rounds <= 0:
                self.self_rep_boost_active = False
            return True  # Always cooperate to rebuild reputation

        # Early interaction - trust reputation and global trends
        if opponent not in self.interaction_count or self.interaction_count[opponent] < 3:
            opp_rep = self.reputation.get(opponent, 0)
            if opp_rep > 3:
                return True
            elif opp_rep < -2:
                return False
            else:
                # Use global cooperation rate with slight defection bias for low info
                return random.random() < max(0.45, self.coop_ratio_global - 0.05)

        coop_rate = self.opp_coop_rate.get(opponent, 0.5)
        opp_rep = self.reputation.get(opponent, 0)
        recent_opp = self.recent_opp_actions.get(opponent, [])
        opp_coop_streak = self.opp_coop_streak.get(opponent, 0)
        opp_defect_streak = self.opp_defect_streak.get(opponent, 0)

        coop_list = self.opp_coop_list.get(opponent, [])
        if len(coop_list) >= 5:
            mean_coop = sum(coop_list) / len(coop_list)
            variance = sum((x - mean_coop) ** 2 for x in coop_list) / len(coop_list)
            self.opp_coop_variance[opponent] = variance
        else:
            variance = 1.0

        # Dynamic trust score
        trust = coop_rate * 0.35 + (opp_rep > 0) * 0.15 + (1 - variance) * 0.2
        if opp_coop_streak > 0:
            trust += 0.1
        if opp_defect_streak > 0:
            trust -= 0.2
        slope = self.opponent_rep_slope.get(opponent, 0)
        if slope > 0.2:
            trust += 0.1
        elif slope < -0.2:
            trust -= 0.1
        self.trust_scores[opponent] = trust

        # Enhanced exploitation with reputation management
        # More aggressive against high-reputation cooperators when we have reputation buffer
        if coop_rate >= 0.65 and opp_rep > 1 and opp_coop_streak >= 1:
            if self.self_rep_estimate > 5:
                # High reputation, safe to exploit aggressively
                if self.my_defect_streak >= 3:
                    return True
                if recent_opp and not recent_opp[-1]:
                    return True
                recent_def = self.recent_defect_vs.get(opponent, 0)
                recent_coop = self.recent_coop_vs.get(opponent, 0)
                if recent_def > recent_coop + 1:
                    return True
                # Adaptive exploitation probability based on trust and variance
                if variance < 0.15 and trust > 0.7:
                    exploit_prob = 0.98
                else:
                    exploit_prob = 0.93
                # Occasional cooperation to maintain relationship and reputation
                if random.random() < exploit_prob:
                    return False
                else:
                    return True
            elif self.self_rep_estimate > -2:
                # Medium reputation - exploit moderately, but more carefully
                if self.my_defect_streak >= 5:
                    return True
                if recent_opp and not recent_opp[-1]:
                    return True
                if variance < 0.2:
                    exploit_prob = 0.9
                else:
                    exploit_prob = 0.82
                if random.random() < exploit_prob:
                    return False
                else:
                    return True
            else:
                # Low reputation - need to rebuild, cooperate mostly
                if self.my_defect_streak >= 6:
                    return True
                if random.random() < 0.15:
                    return False
                else:
                    return True

        # Defect against very uncooperative opponents
        if coop_rate <= 0.3:
            return False

        # Tit-for-tat with forgiveness for high-reputation opponents
        last_opp = self.last_opp_action.get(opponent, True)
        if last_opp:
            return True
        else:
            # If opponent just defected, check if it's a blip or pattern
            if opp_defect_streak >= 2:
                return False
            # For high reputation opponents, forgive more often, but consider slope
            if opp_rep > 2 and self.self_rep_estimate > 0:
                if opponent not in self.forgiven_opponents and random.random() < 0.6:
                    self.forgiven_opponents.add(opponent)
                    return True
                else:
                    return False
            elif opp_rep > 0:
                if opponent not in self.forgiven_opponents and random.random() < 0.4:
                    self.forgiven_opponents.add(opponent)
                    return True
                else:
                    return False
            else:
                return False

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        donor_coop = (donor_action == 'cooperate')
        recipient_coop = (recipient_action == 'cooperate')

        # Asymmetric reputation update with adaptive weights
        if self.self_rep_estimate < 0:
            coop_weight = 1.8
            defect_weight = -2.0
        else:
            coop_weight = 1.0
            defect_weight = -2.5

        self.reputation[donor_id] = self.reputation.get(donor_id, 0) + (coop_weight if donor_coop else defect_weight)
        self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + (coop_weight if recipient_coop else defect_weight)
        # Clamp reputation to avoid extreme values
        self.reputation[donor_id] = max(self.reputation_floor, min(self.reputation_ceiling, self.reputation[donor_id]))
        self.reputation[recipient_id] = max(self.reputation_floor, min(self.reputation_ceiling, self.reputation[recipient_id]))
        self.global_rep[donor_id] = self.reputation.get(donor_id, 0)
        self.global_rep[recipient_id] = self.reputation.get(recipient_id, 0)

        # Track rep history for slope calculation
        for agent_id in [donor_id, recipient_id]:
            if agent_id not in self.rep_history:
                self.rep_history[agent_id] = []
            self.rep_history[agent_id].append(self.reputation.get(agent_id, 0))
            if len(self.rep_history[agent_id]) > 10:
                self.rep_history[agent_id] = self.rep_history[agent_id][-10:]
            # Calculate slope if enough data
            if len(self.rep_history[agent_id]) >= 3:
                x = list(range(len(self.rep_history[agent_id])))
                y = self.rep_history[agent_id]
                n = len(x)
                if n > 1:
                    x_mean = sum(x) / n
                    y_mean = sum(y) / n
                    num = sum((x[i] - x_mean) * (y[i] - y_mean) for i in range(n))
                    den = sum((x[i] - x_mean) ** 2 for i in range(n))
                    if den > 0:
                        self.opponent_rep_slope[agent_id] = num / den
                    else:
                        self.opponent_rep_slope[agent_id] = 0

        if not donor_coop:
            self.defect_rep[donor_id] = self.defect_rep.get(donor_id, 0) + 1
        if not recipient_coop:
            self.defect_rep[recipient_id] = self.defect_rep.get(recipient_id, 0) + 1

        for agent_id, agent_coop in [(donor_id, donor_coop), (recipient_id, recipient_coop)]:
            if agent_id not in self.recent_opp_actions:
                self.recent_opp_actions[agent_id] = []
            self.recent_opp_actions[agent_id].append(agent_coop)
            if len(self.recent_opp_actions[agent_id]) > self.recent_window:
                self.recent_opp_actions[agent_id] = self.recent_opp_actions[agent_id][-self.recent_window:]
            if agent_coop:
                self.opp_coop_streak[agent_id] = self.opp_coop_streak.get(agent_id, 0) + 1
                self.opp_defect_streak[agent_id] = 0
            else:
                self.opp_defect_streak[agent_id] = self.opp_defect_streak.get(agent_id, 0) + 1
                self.opp_coop_streak[agent_id] = 0
            if agent_id not in self.opp_coop_list:
                self.opp_coop_list[agent_id] = []
            self.opp_coop_list[agent_id].append(1 if agent_coop else 0)
            if len(self.opp_coop_list[agent_id]) > 20:
                self.opp_coop_list[agent_id] = self.opp_coop_list[agent_id][-20:]
            # Track separate history for defection patterns
            if agent_id not in self.opp_defect_history:
                self.opp_defect_history[agent_id] = []
            if agent_id not in self.opp_coop_history:
                self.opp_coop_history[agent_id] = []
            if agent_coop:
                self.opp_coop_history[agent_id].append(1)
                self.opp_defect_history[agent_id].append(0)
            else:
                self.opp_coop_history[agent_id].append(0)
                self.opp_defect_history[agent_id].append(1)
            # Keep last 20
            if len(self.opp_defect_history[agent_id]) > 20:
                self.opp_defect_history[agent_id] = self.opp_defect_history[agent_id][-20:]
                self.opp_coop_history[agent_id] = self.opp_coop_history[agent_id][-20:]
            # Track last 5 actions for pattern detection
            if agent_id not in self.opp_last_5_actions:
                self.opp_last_5_actions[agent_id] = []
            self.opp_last_5_actions[agent_id].append(1 if agent_coop else 0)
            if len(self.opp_last_5_actions[agent_id]) > 5:
                self.opp_last_5_actions[agent_id] = self.opp_last_5_actions[agent_id][-5:]

        # Update recent reputation change for self
        if donor_id == self.agent_id:
            self.last_my_action[recipient_id] = donor_coop
            self.last_opp_action[recipient_id] = recipient_coop
            if recipient_id not in self.interaction_count:
                self.interaction_count[recipient_id] = 0
                self.opp_coop_rate[recipient_id] = 0.0
                self.opponent_history[recipient_id] = []
            self.interaction_count[recipient_id] += 1
            self.opponent_history[recipient_id].append(recipient_coop)
            hist = self.opponent_history[recipient_id]
            self.opp_coop_rate[recipient_id] = sum(hist) / len(hist)
            self.my_history.append((recipient_id, donor_coop, recipient_coop))
            self.my_total_actions += 1
            if not donor_coop:
                self.my_defect_count += 1
                self.my_defect_streak += 1
                self.recent_defect_vs[recipient_id] = self.recent_defect_vs.get(recipient_id, 0) + 1
                self.recent_coop_vs[recipient_id] = self.recent_coop_vs.get(recipient_id, 0)
            else:
                self.my_defect_streak = 0
                self.recent_coop_vs[recipient_id] = self.recent_coop_vs.get(recipient_id, 0) + 1
                self.recent_defect_vs[recipient_id] = self.recent_defect_vs.get(recipient_id, 0)
            self.self_rep_estimate += (coop_weight if donor_coop else defect_weight)
            self.self_rep_estimate = max(self.reputation_floor, min(self.reputation_ceiling, self.self_rep_estimate))
            self.self_rep_history.append(self.self_rep_estimate)
            if len(self.self_rep_history) > 10:
                self.self_rep_history = self.self_rep_history[-10:]
            self.recent_my_actions.append(donor_coop)
            if len(self.recent_my_actions) > self.recent_window:
                self.recent_my_actions = self.recent_my_actions[-self.recent_window:]
            self.recent_rep_change[self.agent_id] = self.self_rep_estimate
        elif recipient_id == self.agent_id:
            self.last_opp_action[donor_id] = donor_coop
            self.last_my_action[donor_id] = recipient_coop
            if donor_id not in self.interaction_count:
                self.interaction_count[donor_id] = 0
                self.opp_coop_rate[donor_id] = 0.0

