        # Reputation engineering: rebuild when reputation is low
        if self.my_total_coops + self.my_total_defects > 0:
            if not self.reputation_good and my_reputation < 0.45:
                # Cooperate even with untrusted opponents to rebuild quickly
                if self.trust.get(opp, 0.5) < 0.5:
                    return True

        # Strategic exploitation: defect more often when reputation is high
        if self.reputation_good and self.trust.get(opp, 0.5) > 0.75:
            # Check opponent's recent behavior against us: if they've been cooperative, defect
            recent_seq = self.opp_recent_against_us.get(opp, [])
            if len(recent_seq) >= 3 and all(recent_seq[-3:]):
                return True
            # If opponent is generally cooperative, defect with high probability
            if random.random() < 0.75:
