        # Avoid defectors
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False

        # If opponent has defected recently against us (last 2), defect
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False

        # If opponent's global cooperation rate is very high, defect more often
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 15:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.1:
                # Defect with high probability, but not always to avoid reputation damage
                if random.random() < 0.85:
                    return True

        # If our reputation is low, cooperate more to rebuild
        if self.my_reputation_count > 8:
            if not self.reputation_good and my_reputation < 0.4:
                return True

        # Exploit opponents with long cooperation streaks (global)
        streak = self.opp_coop_streak_global.get(opp, 0)
        if streak >= 3 and self.reputation_good:
            return True

        # If opponent has cooperated last 3 times against us, defect
        seq = self.opp_seq_against_us.get(opp, [])
        if len(seq) >= 3 and all(seq[-3:]):
            return True

        # If opponent has high global cooperation rate and we have high reputation, defect
        if opp in self.opp_recent_behavior and len(self.opp_recent_behavior[opp]) >= 5:
            recent_coop = sum(1 for a in self.opp_recent_behavior[opp] if a)
            if recent_coop >= 4 and self.reputation_good:
                return True

        # If opponent is recently very cooperative against us, defect
        if opp in self.opp_recent_against_us and len(self.opp_recent_against_us[opp]) >= 3:
            recent = self.opp_recent_against_us[opp][-3:]
            if all(recent):
                return True

        # New: punish defectors that defected after we cooperated
        if opp in self.opp_def_after_coop_count:
            if self.opp_def_after_coop_count[opp] >= 2:
                self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.2)
