        if opp in self.opp_consistency_score:
            if self.opp_consistency_score[opp] < 0.3:
                return self.trust.get(opp, 0.5) >= 0.4

        # Fallback to trust threshold
        return self.trust.get(opp, 0.5) >= 0.3

