        # New: if opponent is very cooperative globally and we have good reputation, defect with higher probability
        if opp in self.opp_global_coop and self.opp_global_coop[opp][1] > 10:
            coop_rate = self.opp_global_coop[opp][0] / self.opp_global_coop[opp][1]
            if coop_rate > 0.9 and self.reputation_good:
                if random.random() < 0.95:
                    return True

        # New: opportunistic exploitation - if we have a good reputation and opponent is cooperative, defect more
        if self.reputation_good and self.trust.get(opp, 0.5) > 0.7:
            if opp in self.opp_recent_behavior and len(self.opp_recent_behavior[opp]) >= 5:
                recent_coop = sum(1 for a in self.opp_recent_behavior[opp] if a)
                if recent_coop >= 4:
                    # Exploit cooperative opponents more aggressively
                    if random.random() < 0.8:
                        return True

        # New: if opponent has defected recently and we have low reputation, cooperate to rebuild
        if not self.reputation_good and opp in self.opp_recent_def_global:
            if self.opp_recent_def_global[opp][-1] and random.random() < 0.6:
                return False  # Cooperate to show goodwill

        return self.trust.get(opp, 0.5) >= 0.3

