            else:
                self.opp_def_streak[other] = self.opp_def_streak.get(other, 0) + 1
            self.interaction_count[other] = self.interaction_count.get(other, 0) + 1
            if not opp_act:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0) + 1
            else:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0)
            if self.interaction_count[other] > 0:
                self.def_rate_against_us[other] = self.def_rate_against_us.get(other, 0) / self.interaction_count[other]
            if other not in self.coop_rate_with_us:
                self.coop_rate_with_us[other] = [0, 0]
            if opp_act:
                self.coop_rate_with_us[other][0] += 1
            self.coop_rate_with_us[other][1] += 1
            if other not in self.recent_coop_with_us:
                self.recent_coop_with_us[other] = []
            self.recent_coop_with_us[other].append(opp_act)
            if len(self.recent_coop_with_us[other]) > 5:
                self.recent_coop_with_us[other] = self.recent_coop_with_us[other][-5:]
            if opp_act:
                self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.15)
            else:
                streak = self.opp_def_streak.get(other, 0)
                penalty = 0.2 if streak >= 2 else 0.1
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - penalty)
            if donor_id == self.agent_id:
                self.my_recent_actions.append(my_act)
                if len(self.my_recent_actions) > 3:
                    self.my_recent_actions = self.my_recent_actions[-3:]
                if my_act:
                    self.my_total_coops += 1
                else:
                    self.my_total_defects += 1
                    if other not in self.defects_against:
                        self.defects_against[other] = 0
                    self.defects_against[other] += 1
                    if other not in self.defections_vs_opp:
                        self.defections_vs_opp[other] = 0
                    self.defections_vs_opp[other] += 1
                self.my_recent_reputation.append(my_act)
                if len(self.my_recent_reputation) > 10:
                    self.my_recent_reputation = self.my_recent_reputation[-10:]
                self.my_reputation_count += 1
                if my_act:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 1) / self.my_reputation_count
                else:
                    self.my_reputation_score = (self.my_reputation_score * (self.my_reputation_count - 1) + 0) / self.my_reputation_count
                if len(self.my_recent_reputation) >= 3:
                    recent_coops = sum(1 for a in self.my_recent_reputation[-3:] if a)
                    if recent_coops >= 2:
                        self.reputation_trend.append(1)
                    elif recent_coops <= 1:
                        self.reputation_trend.append(-1)
                    else:
                        self.reputation_trend.append(0)
                    if len(self.reputation_trend) > 5:
                        self.reputation_trend = self.reputation_trend[-5:]
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            total = self.defect_count.get(donor_id, 0) + self.coop_count.get(donor_id, 0)
            if total > 20:
                def_rate = self.defect_count.get(donor_id, 0) / total
                if def_rate > 0.75:
                    self.trust[donor_id] = min(self.trust.get(donor_id, 0.5), 0.15)
                elif def_rate < 0.15:
                    self.trust[donor_id] = max(self.trust.get(donor_id, 0.5), 0.85)
                elif def_rate < 0.4:
                    self.trust[donor_id] = max(self.trust.get(donor_id, 0.5), 0.6)
            if donor_id not in self.opp_consistency:
                self.opp_consistency[donor_id] = []
            self.opp_consistency[donor_id].append(d_act)
            if len(self.opp_consistency[donor_id]) > 10:
                self.opp_consistency[donor_id] = self.opp_consistency[donor_id][-10:]
            if donor_id not in self.opp_recent_behavior:
                self.opp_recent_behavior[donor_id] = []
            self.opp_recent_behavior[donor_id].append(d_act)
            if len(self.opp_recent_behavior[donor_id]) > 10:
                self.opp_recent_behavior[donor_id] = self.opp_recent_behavior[donor_id][-10:]

import math
