        # If our reputation is low, cooperate more to rebuild
        if self.my_reputation_count > 10:
            if not self.reputation_good and my_reputation < 0.35:
                return True

        # New: if opponent's last global action was defection, be cautious
        last_global = self.opp_last_global_action.get(opp)
        if last_global is not None and not last_global:
