        # New: if opponent is very cooperative in their last 5 interactions with us, defect
        seq = self.opp_seq_against_us.get(opp, [])
        if len(seq) >= 3 and all(seq[-3:]):
            # They've cooperated last 3 times against us, defect to exploit
