            if long_term_coop_rate > 0.9 and self.reputation_good:
                # Defect with probability 0.8 (lower than parent's 0.85)
                if random.random() < 0.8:
                    return True
        # New: if opponent has defected against us recently in the last 3 games, defect with high probability
        recent_defs = self.recent_def_against_us.get(opp, [])
        if len(recent_defs) >= 3 and sum(1 for d in recent_defs[-3:] if not d) >= 2:
            return False
        # Decision threshold: slightly more cooperative (higher threshold) to maintain reputation
        return self.trust.get(opp, 0.5) >= 0.3

