            if global_def_rate < 0.1:
                if random.random() < 0.9:
                    return False

        # If we've defected against this opponent a lot, cooperate to maintain reputation
        if opp in self.defections_vs_opp and self.defections_vs_opp[opp] >= 3:
            return False

