        if opp in self.opp_global_coop and self.opp_global_coop[opp][1] > 10:
            coop_rate = self.opp_global_coop[opp][0] / self.opp_global_coop[opp][1]
            if coop_rate > 0.9 and self.reputation_good:
                if random.random() < 0.95:
                    return True

        # New enhancement: if we've built reputation, exploit more aggressively
        if self.reputation_good and my_reputation > 0.8:
            if self.trust.get(opp, 0.5) > 0.6:
                if random.random() < 0.85:
                    return False

        # New enhancement: if opponent is a known sucker (always cooperates), exploit
        if opp in self.opp_recent_behavior and len(self.opp_recent_behavior[opp]) >= 8:
            recent_coop = sum(1 for a in self.opp_recent_behavior[opp] if a)
            if recent_coop >= 7:
                if random.random() < 0.9:
                    return False

        # New enhancement: if we have a good reputation and opponent is neutral, sometimes defect
        if self.reputation_good and self.trust.get(opp, 0.5) >= 0.5:
            if random.random() < 0.3:
                return False

        return self.trust.get(opp, 0.5) >= 0.3

