                recent_coops = sum(1 for a in self.my_recent_reputation if a)
                recent_total = len(self.my_recent_reputation)
                my_reputation = recent_coops / recent_total
            self.reputation_good = my_reputation > 0.6
        else:
            my_reputation = 0.5
            self.reputation_good = False

        # Enhanced exploitation of very cooperative opponents
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                # Very cooperative opponent: exploit aggressively but maintain reputation
                if self.reputation_good:
                    # Defect most of the time, but occasionally cooperate to keep trust
                    if random.random() < 0.9:
                        return False
                    return True
                # If reputation is poor, cooperate to rebuild it
                return True
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False

        # Reputation rebuilding: if we have a bad reputation, cooperate more
        if self.my_total_coops + self.my_total_defects > 0:
            if not self.reputation_good and my_reputation < 0.5:
