            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.1:
                if random.random() < 0.95:
                    return False

        # If we've defected against this opponent a lot, cooperate to maintain reputation
        if opp in self.defections_vs_opp and self.defections_vs_opp[opp] >= 3:
            return False

        # If opponent has been very cooperative recently, exploit more
        if opp in self.opp_recent_behavior and len(self.opp_recent_behavior[opp]) >= 5:
            recent_coop = sum(1 for a in self.opp_recent_behavior[opp] if a)
            if recent_coop >= 4:
                if random.random() < 0.85:
                    return False

        # New: if opponent is very cooperative and we have good reputation, defect more aggressively
        if opp in self.opp_global_coop and self.opp_global_coop[opp][1] > 10:
            coop_rate = self.opp_global_coop[opp][0] / self.opp_global_coop[opp][1]
            if coop_rate > 0.9 and self.reputation_good:
                if random.random() < 0.97:
                    return False

        # Additional exploitation: if opponent has a long history of cooperation and we have a good reputation, defect with high probability
        if opp in self.opp_global_coop and self.opp_global_coop[opp][1] > 30:
            coop_rate = self.opp_global_coop[opp][0] / self.opp_global_coop[opp][1]
            if coop_rate > 0.85 and self.reputation_good:
                if random.random() < 0.99:
                    return False

        # If we have a very good reputation and opponent is moderately cooperative, exploit more
        if self.reputation_good and my_reputation > 0.8:
            if opp in self.coop_rate_others and self.coop_rate_others[opp] > 0.7:
                if random.random() < 0.8:
                    return False

        # Default: cooperate if trust is high enough
        return self.trust.get(opp, 0.5) >= 0.3

