            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
