        if opp in self.opp_recent_behavior and len(self.opp_recent_behavior[opp]) >= 5:
            recent_coop = sum(1 for a in self.opp_recent_behavior[opp] if a)
            if recent_coop >= 4:
                if self.reputation_good:
                    if random.random() < 0.85:
                        return False
                else:
                    if random.random() < 0.4:
                        return False
                    else:
                        return True

        # New: adaptive exploitation based on our recent cooperation rate
        # If we've been cooperating a lot, we can afford to defect against exploitable opps
        if self.recent_total_count > 5:
            recent_coop_rate = self.recent_coop_count / self.recent_total_count
            if recent_coop_rate > 0.7 and self.trust.get(opp, 0.5) > 0.6:
                # Defect more if we have a good reputation and high trust
                if self.reputation_good:
                    if random.random() < 0.7:
                        return False
                else:
                    if random.random() < 0.4:
                        return False

        # New: avoid over-exploiting opponents we've defected against many times
        # to maintain long-term cooperation
        if opp in self.defections_vs_opp and self.defections_vs_opp[opp] >= 4:
            coop_count_opp = self.coops_vs_opp.get(opp, 0)
            if coop_count_opp == 0:
                # Never cooperated – cooperate now to maintain relationship
