        self.own_action_window = []
        # New: track opponent's recent defection rate against us specifically
        self.opp_def_recent = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False

        # Initialize trust for unknown opponents
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6

        # Update trust based on last direct interaction
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)

        # Compute my current reputation from recent actions
        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if len(self.my_recent_reputation) > 0:
                recent_coops = sum(1 for a in self.my_recent_reputation if a)
                recent_total = len(self.my_recent_reputation)
                my_reputation = recent_coops / recent_total
            self.reputation_good = my_reputation > 0.6
        else:
            my_reputation = 0.5
            self.reputation_good = False

        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                # Very cooperative opponent – exploit if reputation is safe
                if self.reputation_good:
                    # If we have a good reputation, defect more often but not always
                    # to avoid retaliation and reputation damage
                    risk = 0.2 if my_reputation > 0.8 else 0.6
                    if random.random() < risk:
                        return False  # defect
                    else:
                        return True
                else:
                    # Not good reputation – need to cooperate more
                    if opp not in self.defects_against:
                        self.defects_against[opp] = 0
                    if self.defects_against[opp] % 2 == 1:
                        return False
                    else:
                        return True
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False

        # If reputation is poor, cooperate more to rebuild it
        if self.my_total_coops + self.my_total_defects > 0:
            if not self.reputation_good and my_reputation < 0.4:
                if self.trust.get(opp, 0.5) < 0.5:
                    return True

        # If we have good reputation and high trust, occasionally defect for gain
        if self.reputation_good and self.trust.get(opp, 0.5) > 0.8:
            # Defect with probability 0.8 if we've not been exploiting too much
            exploit_count = self.defections_vs_opp.get(opp, 0)
            coop_count_opp = self.coops_vs_opp.get(opp, 0)
            if exploit_count >= 3 and coop_count_opp >= 1:
                # Too much exploitation – reduce to maintain cooperation
                if random.random() < 0.3:
                    return False
            else:
                if random.random() < 0.8:
                    return False
            # Otherwise cooperate

        # Defect against opponents who defect against us often
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False

        # Defect if opponent defected in last two direct interactions
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False

        # Global defection rate: if opponent is very cooperative globally, exploit
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.1:
                # Exploit with probability 0.85 if reputation good
                if self.reputation_good:
                    if random.random() < 0.85:
                        return False
                else:
                    # Need to maintain reputation – cooperate more
                    if random.random() < 0.3:
                        return False
                    else:
                        return True

        # If reputation is bad, cooperate to fix it
        if self.my_reputation_count > 10:
            if not self.reputation_good and my_reputation < 0.4:
                return True

        # If opponent has been very cooperative recently, exploit sometimes
        if opp in self.opp_recent_behavior and len(self.opp_recent_behavior[opp]) >= 5:
            recent_coop = sum(1 for a in self.opp_recent_behavior[opp] if a)
            if recent_coop >= 4:
                if self.reputation_good:
                    if random.random() < 0.85:
                        return False
                else:
                    if random.random() < 0.4:
                        return False
                    else:
                        return True

        # New: adaptive exploitation based on our recent cooperation rate
        # If we've been cooperating a lot, we can afford to defect against exploitable opps
        if self.recent_total_count > 5:
            recent_coop_rate = self.recent_coop_count / self.recent_total_count
            if recent_coop_rate > 0.7 and self.trust.get(opp, 0.5) > 0.6:
                # Defect more if we have a good reputation and high trust
                if self.reputation_good:
                    if random.random() < 0.7:
                        return False
                else:
                    if random.random() < 0.4:
                        return False

        # New: avoid over-exploiting opponents we've defected against many times
        # to maintain long-term cooperation
        if opp in self.defections_vs_opp and self.defections_vs_opp[opp] >= 4:
            coop_count_opp = self.coops_vs_opp.get(opp, 0)
            if coop_count_opp == 0:
                # Never cooperated – cooperate now to maintain relationship
                return True
            elif self.defections_vs_opp[opp] > coop_count_opp * 2:
                # Too many defections – cooperate more
                if random.random() < 0.6:
                    return True

        # New: if our recent reputation is dropping, cooperate more
        if len(self.reputation_trend) >= 3:
            trend_sum = sum(self.reputation_trend[-3:])
            if trend_sum < 0:  # recent defections hurting reputation
                if self.trust.get(opp, 0.5) > 0.5:
                    return True

        # Default: cooperate if trust is decent
        return self.trust.get(opp, 0.5) >= 0.3

