                return False
        # New improvement: if opponent is a moderate cooperator (50-80% global coop) and we have good reputation,
        # defect with moderate probability to exploit while keeping some cooperation for reputation
        if self.reputation_good and 0.5 <= self.coop_rate_others.get(opp, 0.5) < 0.8:
            if random.random() < 0.6:
                return True
            else:
                return False
        # New improvement: if opponent is a defector (global def rate > 0.6) but we have good reputation,
        # occasionally defect to punish, but mostly cooperate to maintain reputation
        if self.reputation_good and self.opp_def_rate.get(opp, 0) > 0.6:
            if random.random() < 0.2:
                return True
            else:
                return False
        # New change: if opponent is a strong defector (global def rate > 0.8) and we have poor reputation,
        # defect aggressively to avoid being exploited
        if not self.reputation_good and self.opp_def_rate.get(opp, 0) > 0.8:
            return True
        # New change: if opponent has been cooperating with us consistently in last 3 interactions and we have good reputation,
        # cooperate to build trust and maintain reputation
        if self.reputation_good and opp in self.recent_coop_with_us and len(self.recent_coop_with_us[opp]) >= 3:
            if sum(self.recent_coop_with_us[opp][-3:]) == 3:
