        if self.reputation_good and self.coop_rate_others.get(opp, 0.5) > 0.8:
            if random.random() < 0.98:
                return True
            else:
                return False
        # Novel change: if opponent has been defecting a lot against us recently, defect to retaliate
        if opp in self.recent_coop_with_us and len(self.recent_coop_with_us[opp]) >= 3:
            if sum(self.recent_coop_with_us[opp][-3:]) == 0:
                return False
