        # If we have good reputation and opponent is cooperative, defect more often
        if self.reputation_good and self.coop_rate_others.get(opp, 0.5) > 0.7:
            # Track exploitation rounds to avoid over-exploiting and destroying reputation
            if opp not in self.exploit_counter:
                self.exploit_counter[opp] = 0
            if self.exploit_counter[opp] < 2:
                if random.random() < 0.99:
                    self.exploit_counter[opp] += 1
                    return True
                else:
                    self.exploit_counter[opp] = 0
                    return False
            else:
                # Occasionally cooperate to maintain reputation
                if random.random() < 0.2:
                    self.exploit_counter[opp] = 0
                    return False
                else:
                    return True
        # If opponent is very cooperative and we have low reputation, cooperate to rebuild
        if not self.reputation_good and self.coop_rate_others.get(opp, 0.5) > 0.8:
            if random.random() < 0.7:
                return False
        return self.trust.get(opp, 0.5) >= 0.25

