        if donor_id not in self.opp_recent_def_global:
            self.opp_recent_def_global[donor_id] = []
        self.opp_recent_def_global[donor_id].append(not d_act)
        if len(self.opp_recent_def_global[donor_id]) > 5:
            self.opp_recent_def_global[donor_id] = self.opp_recent_def_global[donor_id][-5:]
        # Track overall global coop rate
        if donor_id not in self.opp_global_coop:
            self.opp_global_coop[donor_id] = [0, 0]
        if d_act:
            self.opp_global_coop[donor_id][0] += 1
        self.opp_global_coop[donor_id][1] += 1
        # Track long-term coop/def for donor
        if donor_id not in self.opp_long_term_coop:
            self.opp_long_term_coop[donor_id] = 0
            self.opp_long_term_def[donor_id] = 0
        if d_act:
            self.opp_long_term_coop[donor_id] += 1
        else:
            self.opp_long_term_def[donor_id] += 1
        # Track per-pair history
        key = (donor_id, recipient_id)
        if key not in self.history:
            self.history[key] = []
        self.history[key].append(d_act)
        # Track own interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            own_key = (self.agent_id, other)
            if own_key not in self.own_interactions:
                self.own_interactions[own_key] = []
            if donor_id == self.agent_id:
                my_act = d_act
                opp_act = r_act
            else:
