            self.recent_opp_actions[other].append(opp_act)
            if len(self.recent_opp_actions[other]) > 3:
                self.recent_opp_actions[other] = self.recent_opp_actions[other][-3:]
            # Track opponent's streaks
            if other not in self.def_streak:
                self.def_streak[other] = 0
            if other not in self.coop_streak:
                self.coop_streak[other] = 0
            if opp_act:
                self.coop_streak[other] += 1
                self.def_streak[other] = 0
            else:
                self.def_streak[other] += 1
                self.coop_streak[other] = 0
            self.last_opp_action[other] = opp_act
