            # New: Track if opponent cooperated after we defected (for reciprocity)
            if donor_id == self.agent_id:
                self.last_my_action = my_act
                if my_act == False and opp_act == True:
                    self.coop_after_def[other] = True
                else:
                    self.coop_after_def[other] = False
            if donor_id == self.agent_id:
                self.my_recent_actions.append(my_act)
