    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
