        self.reputation_good = my_reputation > 0.6
        # Store reputation history
        self.reputation_history.append(my_reputation)
        if len(self.reputation_history) > 50:
            self.reputation_history = self.reputation_history[-50:]

        # Dynamic phase switching based on reputation
        if len(self.reputation_history) > 5:
            recent_avg = sum(self.reputation_history[-5:]) / 5
            if recent_avg > 0.75:
                self.phase = 'exploit'
            elif recent_avg < 0.45:
                self.phase = 'build'
            else:
                if random.random() < 0.05:
                    self.phase = 'build' if self.phase == 'exploit' else 'exploit'

        # Exploit pure cooperators
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                if opp not in self.exploit_schedule:
                    self.exploit_schedule[opp] = 0
                prob_defect = 0.95 if self.reputation_good else 0.7
                if self.exploit_schedule.get(opp, 0) >= 3:
                    prob_defect = 0.3
                if self.phase == 'build':
                    prob_defect = min(prob_defect, 0.4)
                if self.opp_def_streak.get(opp, 0) >= 2:
                    prob_defect = max(prob_defect, 0.8)
                my_streak = self.my_def_streak_against.get(opp, 0)
                if my_streak >= 2:
                    prob_defect = min(prob_defect, 0.2)
                if random.random() < prob_defect:
                    self.exploit_schedule[opp] = self.exploit_schedule.get(opp, 0) + 1
                    return True
                else:
                    self.exploit_schedule[opp] = 0
                    return False
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False
        # Rebuild reputation if low
        if total_actions > 0:
            if not self.reputation_good and my_reputation < 0.45:
                if self.trust.get(opp, 0.5) < 0.5:
                    return True
        # Exploit when reputation high and opponent cooperative
        if self.reputation_good and self.trust.get(opp, 0.5) > 0.85:
            if random.random() < 0.9:
                return False
        # Avoid defectors
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False
        # Punish recent defections against us
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False
        # Exploit very cooperative opponents globally
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.08:
                if random.random() < 0.98:
                    return True
        # Rebuild reputation
        if len(self.reputation_history) > 10:
            if not self.reputation_good and my_reputation < 0.4:
                return True
        # Punish if opponent defected recently against us despite being generally cooperative
        if total_global > 20 and global_def_rate < 0.2:
            recent_def_against = sum(1 for a in self.recent_opp_actions.get(opp, []) if not a)
            if recent_def_against >= 1:
                return False
        # Adaptive threshold based on opponent's cooperation rate
        if total_opp > 0:
            coop_rate = self.coop_count.get(opp, 0) / total_opp
            self.adaptive_threshold = 0.3 - 0.1 * (coop_rate - 0.5) * 2
            self.adaptive_threshold = max(0.1, min(0.5, self.adaptive_threshold))
        else:
            self.adaptive_threshold = 0.3
        threshold = self.adaptive_threshold
        if self.phase == 'build':
            threshold = 0.45
        # New mutation: if we have defected many times against this opponent, cooperate more to maintain reputation
        my_streak_against = self.my_def_streak_against.get(opp, 0)
        if my_streak_against >= 3:
            threshold = 0.6
        # New mutation: if opponent has a long global cooperation streak, be more trusting
        global_streak = self.opp_global_coop_streak.get(opp, 0)
        if global_streak >= 5:
            threshold = min(threshold, 0.2)
        # New mutation: if our reputation is trending upward, be a bit more aggressive
        if len(self.reputation_history) >= 3:
            if self.reputation_history[-1] > self.reputation_history[-2] and self.reputation_history[-2] > self.reputation_history[-3]:
                threshold = max(0.1, threshold - 0.05)
        return self.trust.get(opp, 0.5) >= threshold

