                recent_total = len(self.my_recent_reputation)
                my_rep = recent_coops / recent_total
            self.reputation_good = my_rep > 0.6
        else:
            my_rep = 0.5
            self.reputation_good = False

        # Exploit known cooperators with reputation management
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
