            # Never defect against habitual defectors
            if def_rate > 0.7:
                self.trust[opp] = 0.0
                return False
            # Exploit very cooperative opponents moderately
            if def_rate < 0.05 and self.reputation_good:
                # Use exploitation with cooldown to avoid retaliation
                cooldown = self.exploit_cooldown.get(opp, 0)
                if cooldown > 0:
                    self.exploit_cooldown[opp] = cooldown - 1
