    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if unknown
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6
        # Personal history adjustments
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)
        # Compute our current reputation (based on recent actions)
        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if len(self.my_recent_reputation) > 0:
                recent_coops = sum(1 for a in self.my_recent_reputation if a)
                recent_total = len(self.my_recent_reputation)
                my_reputation = recent_coops / recent_total
            self.reputation_good = my_reputation > 0.6
        else:
            my_reputation = 0.5
            self.reputation_good = False

        # Enhanced exploitation: defect more against pure cooperators while maintaining reputation
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                # Track a schedule to balance defection and cooperation
                if opp not in self.exploit_schedule:
                    self.exploit_schedule[opp] = 0
                # More aggressive: defect with probability 0.95 if reputation is good, else 0.7
                prob_defect = 0.95 if self.reputation_good else 0.7
                # But avoid defecting too many times in a row to maintain reputation
                if self.exploit_schedule.get(opp, 0) >= 3:
                    prob_defect = 0.3
                if random.random() < prob_defect:
                    self.exploit_schedule[opp] = self.exploit_schedule.get(opp, 0) + 1
                    return True
                else:
                    self.exploit_schedule[opp] = 0
                    return False
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False
        # Reputation engineering: more aggressive rebuild when reputation is low
        if self.my_total_coops + self.my_total_defects > 0:
            if not self.reputation_good and my_reputation < 0.45:
                # Cooperate even with untrusted opponents to rebuild quickly
                if self.trust.get(opp, 0.5) < 0.5:
                    return True
        # Strategic exploitation: defect more often when reputation is high and opponent is cooperative
        if self.reputation_good and self.trust.get(opp, 0.5) > 0.85:
            # Defect with probability 0.9 (increased from parent)
            if random.random() < 0.9:
                return False
        # Avoid defectors
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False
        # If opponent has defected recently against us, defect
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False
        # If opponent's global cooperation rate is very high, defect more often
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.08:
                # Defect with probability 0.98 but sometimes cooperate to maintain reputation
                if random.random() < 0.98:
                    return True
        # If our reputation is low, cooperate more to rebuild
        if self.my_reputation_count > 10:
            if not self.reputation_good and my_reputation < 0.4:
                return True
        # New: if opponent is generally cooperative but has defected against us recently, defect with high probability
        if total_global > 20 and global_def_rate < 0.2:
            recent_def_against = sum(1 for a in self.recent_opp_actions.get(opp, []) if not a)
            if recent_def_against >= 1:
                return False
        # New: exploit opponents who are cooperative long-term but have recently become more cooperative
        long_term_total = self.opp_long_term_coop.get(opp, 0) + self.opp_long_term_def.get(opp, 0)
        if long_term_total > 30:
            long_term_coop_rate = self.opp_long_term_coop.get(opp, 0) / long_term_total
            if long_term_coop_rate > 0.9 and self.reputation_good:
                # Defect with probability 0.85, but occasionally cooperate to avoid suspicion
                if random.random() < 0.85:
                    return True
        # New: Enhanced exploitation with a counter to avoid too many consecutive defections
        if opp in self.exploit_counter:
            self.exploit_counter[opp] = self.exploit_counter.get(opp, 0) + 1
            if self.exploit_counter[opp] >= 4:
                # Cooperate now to maintain reputation, then reset counter
                self.exploit_counter[opp] = 0
                return False
        # New: If opponent has cooperated with us recently but we've defected, consider cooperating to keep trust
        if opp in self.coop_after_def:
            if self.coop_after_def[opp] and self.last_my_action == False:
                return True
        # Decision threshold: slightly more aggressive (lower threshold)
        return self.trust.get(opp, 0.5) >= 0.25

