        opp = self._ctx_opponent_id
        if opp is None:
            return False
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
