        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if len(self.my_recent_reputation) > 0:
                recent_coops = sum(1 for a in self.my_recent_reputation if a)
                recent_total = len(self.my_recent_reputation)
                my_reputation = recent_coops / recent_total
            self.reputation_good = my_reputation > 0.6
        else:
            my_reputation = 0.5
            self.reputation_good = False

        # Enhanced exploitation with burst control
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                # Target pure cooperators: defect in bursts to maintain reputation
                if opp not in self.coop_burst_remaining:
                    self.coop_burst_remaining[opp] = 0
                if opp not in self.def_burst_remaining:
                    self.def_burst_remaining[opp] = 0
                if self.def_burst_remaining[opp] > 0:
                    self.def_burst_remaining[opp] -= 1
                    return True
                else:
                    # Start a new defection burst with probability based on reputation
                    if self.reputation_good:
                        burst_len = random.randint(2, 4)
                        self.def_burst_remaining[opp] = burst_len - 1
                        return True
                    else:
                        # When reputation is low, cooperate to rebuild
                        if random.random() < 0.3:
                            return True
                        else:
                            return False
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False
        # Reputation engineering: aggressive rebuild when low
        if self.my_total_coops + self.my_total_defects > 0:
            if not self.reputation_good and my_reputation < 0.45:
                if self.trust.get(opp, 0.5) < 0.5:
                    return True
        # Strategic exploitation: defect when reputation high and opponent cooperative
        if self.reputation_good and self.trust.get(opp, 0.5) > 0.85:
            if random.random() < 0.9:
                return False  # Defect
        # Avoid defectors
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False
        # If opponent has defected recently against us
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False
