            if long_term_coop_rate > 0.9 and self.reputation_good:
                # Defect with probability 0.85, but occasionally cooperate to avoid suspicion
                if random.random() < 0.85:
                    return True
        # New: Enhanced exploitation with a counter to avoid too many consecutive defections
        if opp in self.exploit_counter:
            self.exploit_counter[opp] = self.exploit_counter.get(opp, 0) + 1
            if self.exploit_counter[opp] >= 4:
                # Cooperate now to maintain reputation, then reset counter
                self.exploit_counter[opp] = 0
                return False
