                # Exploit more often but not too much
                if random.random() < 0.95:
                    return True
        # Punishment mechanism: if we've been punishing, continue until coop
        if opp in self.punishment_until:
            if self.punishment_until[opp] > 0:
                self.punishment_until[opp] -= 1
                return False
            else:
                del self.punishment_until[opp]
