        # If opponent is generally cooperative but recently defected, punish with defection
        if total_global > 20 and global_def_rate < 0.2:
            recent_def_against = sum(1 for a in self.recent_opp_actions.get(opp, []) if not a)
            if recent_def_against >= 1:
                return False
        # Long-term cooperation exploitation
        long_term_total = self.opp_long_term_coop.get(opp, 0) + self.opp_long_term_def.get(opp, 0)
        if long_term_total > 30:
