            if long_term_coop_rate > 0.9 and self.reputation_good:
                # Defect with probability 0.9, but occasionally cooperate to avoid suspicion
                if random.random() < 0.9:
                    return True
        # New: Enhanced exploitation with a counter to avoid too many consecutive defections
        if opp in self.exploit_counter:
            self.exploit_counter[opp] = self.exploit_counter.get(opp, 0) + 1
            if self.exploit_counter[opp] >= 3:
                # Cooperate now to maintain reputation, then reset counter
                self.exploit_counter[opp] = 0
                return False
        # New: If opponent has cooperated with us recently but we've defected, consider cooperating to keep trust
        if opp in self.coop_after_def:
            if self.coop_after_def[opp] and self.last_my_action == False:
                return True

        # === NEW STRATEGY: Adaptive exploitation with reputation buffer ===
        # If we have a good reputation, we can afford to defect more against cooperative opponents
        # but must maintain a buffer of cooperation to avoid being labeled as a defector.
        if self.reputation_good:
            # If opponent is very cooperative overall, defect with high probability
            if total_global > 10:
                global_coop_rate = self.coop_count.get(opp, 0) / total_global
                if global_coop_rate > 0.85:
                    # Defect with probability 0.97, but occasionally cooperate to keep reputation
                    if random.random() < 0.97:
                        return True
                    else:
                        return False
            # If opponent is moderately cooperative, defect with moderate probability
            if total_global > 10:
                global_coop_rate = self.coop_count.get(opp, 0) / total_global
                if global_coop_rate > 0.6:
                    if random.random() < 0.8:
                        return True
                    else:
                        return False
        # If reputation is not good, cooperate more to rebuild, but still defect if opponent is clearly exploitable
        else:
            # If opponent is a pure cooperator, defect occasionally but not too much
            if total_global > 10:
                global_coop_rate = self.coop_count.get(opp, 0) / total_global
                if global_coop_rate > 0.95:
                    if random.random() < 0.3:
                        return True
                    else:
                        return False
        # If we have a recent defection streak, cooperate to restore reputation
        if self.my_def_streak >= 2:
            return False
        # If opponent has a long defection streak against us, defect
        if self.def_streak.get(opp, 0) >= 3:
            return False
        # If opponent tends to retaliate against defection, be more cooperative
        opp_def_resp = self.opp_def_responses.get(opp, 0)
        opp_coop_resp = self.opp_coop_responses.get(opp, 0)
        if opp_def_resp + opp_coop_resp > 0:
            retaliation_ratio = opp_def_resp / (opp_def_resp + opp_coop_resp)
            if retaliation_ratio > 0.8:
                return False
        # Decision threshold: slightly more aggressive (lower threshold)
        return self.trust.get(opp, 0.5) >= 0.25

