            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.08:
                # Defect with probability 0.99 but sometimes cooperate to maintain reputation
                if random.random() < 0.99:
                    return True
        # If our reputation is low, cooperate more to rebuild
        if self.my_reputation_count > 10:
            if not self.reputation_good and my_reputation < 0.4:
                return True
        # New: if opponent is generally cooperative but has defected against us recently, defect with high probability
        if total_global > 20 and global_def_rate < 0.2:
            recent_def_against = sum(1 for a in self.recent_opp_actions.get(opp, []) if not a)
            if recent_def_against >= 1:
                return False
        # New: exploit opponents who are cooperative long-term but have recently become more cooperative
        long_term_total = self.opp_long_term_coop.get(opp, 0) + self.opp_long_term_def.get(opp, 0)
