        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if len(self.my_recent_reputation) > 0:
                recent_coops = sum(1 for a in self.my_recent_reputation if a)
                recent_total = len(self.my_recent_reputation)
                my_reputation = recent_coops / recent_total
            self.reputation_good = my_reputation > 0.55  # slightly lower threshold
        else:
            my_reputation = 0.5
            self.reputation_good = False

        # Track recent cooperation rate to avoid being labeled as defector
        if len(self.recent_my_coop) > 0:
            recent_coop_rate = sum(self.recent_my_coop) / len(self.recent_my_coop)
        else:
            recent_coop_rate = 0.5

