        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)

        # Track opponent's susceptibility: how often they cooperate after we defect
        if opp not in self.opp_susceptibility:
            self.opp_susceptibility[opp] = 0.5
        # Update susceptibility from recent interactions
        if len(self.own_interactions.get(key, [])) > 0:
            recent_interactions = self.own_interactions[key][-5:]
            if recent_interactions:
                def_events = [(m, o) for m, o in recent_interactions if not m]
                if def_events:
                    coop_after_def = sum(1 for m, o in def_events if o)
                    self.opp_susceptibility[opp] = coop_after_def / len(def_events)

        # Compute global cooperation rates for opponent
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 0:
            global_coop_rate = self.coop_count.get(opp, 0) / total_global
        else:
            global_coop_rate = 0.5

        # Main decision logic with adaptive reputation buffer
        # If reputation is low, we need to cooperate more to rebuild
        if not self.reputation_good:
            # If reputation is very low, cooperate with high probability
            if my_reputation < 0.4:
                # But still exploit if opponent is pure cooperator and we can risk it
                if total_global > 10 and global_coop_rate > 0.95:
                    if random.random() < 0.2:  # occasional exploitation
                        return True
                return False
            # If reputation is moderate, cooperate with decent probability
            else:
                # If opponent is very cooperative, defect occasionally
                if total_global > 10 and global_coop_rate > 0.9:
                    if random.random() < 0.4:
                        return True
                return False

        # If reputation is good, we can exploit more aggressively
        else:
            # Pure cooperators: exploit heavily but maintain cycle to keep reputation
            if total_global > 10 and global_coop_rate > 0.85:
                # Use a cycle: cooperate every 4th time to maintain reputation
                if opp not in self.exploit_cycle:
                    self.exploit_cycle[opp] = 0
                cycle_pos = self.exploit_cycle[opp]
                self.exploit_cycle[opp] = (cycle_pos + 1) % 4
                if cycle_pos == 3:
                    return False  # cooperate to maintain reputation
                else:
                    return True  # defect

            # Cooperative opponents (not pure): defect with high probability
            if total_global > 10 and global_coop_rate > 0.7:
                if random.random() < 0.9:
                    return True
                else:
                    return False

            # Moderate cooperators: defect with moderate probability
            if total_global > 10 and global_coop_rate > 0.5:
                if random.random() < 0.7:
                    return True
                else:
                    return False

        # Avoid defectors: if opponent has high defection rate, cooperate
        opp_def_rate_val = self.def_rate_against_us.get(opp, 0)
        if opp_def_rate_val > 0.5:
            return False

        # If opponent has defected recently against us, defect (tit-for-tat)
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return True

        # If opponent is exploitable (high susceptibility), defect more
        if self.opp_susceptibility.get(opp, 0.5) > 0.7 and self.reputation_good:
            if random.random() < 0.9:
                return True

        # If we have a recent defection streak, cooperate to restore reputation
        if self.my_def_streak >= 3:
            return False

        # If opponent has a long defection streak against us, defect
        if self.def_streak.get(opp, 0) >= 3:
            return True

        # If opponent tends to retaliate against defection, be more cooperative
        opp_def_resp = self.opp_def_responses.get(opp, 0)
