            retaliation_ratio = opp_def_resp / (opp_def_resp + opp_coop_resp)
            if retaliation_ratio > 0.8:
                return False

        # Default: cooperate if trust is high enough, but slightly more aggressive
        return self.trust.get(opp, 0.5) >= 0.2

