                if opp not in self.exploit_schedule:
                    self.exploit_schedule[opp] = 0
                prob_defect = 0.95 if self.reputation_good else 0.7
                if self.exploit_schedule.get(opp, 0) >= 3:
                    prob_defect = 0.3
                if random.random() < prob_defect:
                    self.exploit_schedule[opp] = self.exploit_schedule.get(opp, 0) + 1
                    return True
                else:
                    self.exploit_schedule[opp] = 0
                    return False
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False
        if self.my_total_coops + self.my_total_defects > 0:
            if not self.reputation_good and my_reputation < 0.45:
                if self.trust.get(opp, 0.5) < 0.5:
                    return True
        if self.reputation_good and self.trust.get(opp, 0.5) > 0.85:
            # Enhanced exploitation: defect with probability 1.0 (always)
            return False
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.08:
                # Always defect against extremely cooperative opponents
                return True
        if self.my_reputation_count > 10:
            if not self.reputation_good and my_reputation < 0.4:
                return True
        if total_global > 20 and global_def_rate < 0.2:
            recent_def_against = sum(1 for a in self.recent_opp_actions.get(opp, []) if not a)
            if recent_def_against >= 1:
                return False
        long_term_total = self.opp_long_term_coop.get(opp, 0) + self.opp_long_term_def.get(opp, 0)
        if long_term_total > 30:
            long_term_coop_rate = self.opp_long_term_coop.get(opp, 0) / long_term_total
            if long_term_coop_rate > 0.9 and self.reputation_good:
                # Always defect against long-term cooperators when reputation is good
                return True
        if opp in self.exploit_counter:
            self.exploit_counter[opp] = self.exploit_counter.get(opp, 0) + 1
            if self.exploit_counter[opp] >= 4:
                self.exploit_counter[opp] = 0
                return False
        if opp in self.coop_after_def:
            if self.coop_after_def[opp] and self.last_my_action == False:
