    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize trust if needed
        if opp not in self.trust:
            total = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
            if total > 0:
                def_rate = self.defect_count.get(opp, 0) / total
                if def_rate > 0.5:
                    self.trust[opp] = 0.3
                elif def_rate < 0.2:
                    self.trust[opp] = 0.7
                else:
                    self.trust[opp] = 0.5
            else:
                self.trust[opp] = 0.6

        # Update trust based on recent own interactions
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.2)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.3)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)

        # Compute reputation
        if self.my_total_coops + self.my_total_defects > 0:
            my_reputation = self.my_total_coops / (self.my_total_coops + self.my_total_defects)
            if len(self.my_recent_reputation) > 0:
                recent_coops = sum(1 for a in self.my_recent_reputation if a)
                recent_total = len(self.my_recent_reputation)
                my_reputation = recent_coops / recent_total
            self.reputation_good = my_reputation > 0.6
        else:
            my_reputation = 0.5
            self.reputation_good = False

        # Enhanced exploitation of pure cooperators with reputation management
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                if opp not in self.exploit_schedule:
                    self.exploit_schedule[opp] = 0
                # More aggressive when reputation good, but maintain cooperation rate
                prob_defect = 0.98 if self.reputation_good else 0.8
                # Reduce defection if we've defected too many times in a row
                if self.exploit_schedule.get(opp, 0) >= 3:
                    prob_defect = 0.2
                # If opponent retaliates, punish
                if self.opp_retaliation.get(opp, 0) > 0:
                    prob_defect = 0.1
                # Randomize to avoid predictability
                if random.random() < prob_defect:
                    return True
                else:
                    return False
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False

        # Reputation engineering: rebuild reputation quickly when low
        if self.my_total_coops + self.my_total_defects > 0:
            if not self.reputation_good and my_reputation < 0.45:
                if self.trust.get(opp, 0.5) < 0.5:
                    return True

        # Strategic exploitation: defect when reputation high and opponent cooperative
        if self.reputation_good and self.trust.get(opp, 0.5) > 0.85:
            # Check if opponent retaliates after our defection
            if opp in self.opp_retaliated_after_def and self.opp_retaliated_after_def[opp] > 0.5:
                prob_defect = 0.3
            else:
                prob_defect = 0.95
            if random.random() < prob_defect:
                return False

        # Avoid defectors
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False

        # If opponent has defected recently against us, defect
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False

        # If opponent's global cooperation rate is very high, defect more often
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.08:
                # Defect with high probability but sometimes cooperate
                if random.random() < 0.98:
                    return True

        # If our reputation is low, cooperate more to rebuild
        if self.my_reputation_count > 10:
            if not self.reputation_good and my_reputation < 0.4:
                return True

        # New: If opponent is a retaliator, be more cooperative to avoid punishment
        if opp in self.opp_punishment_count and self.opp_punishment_count[opp] > 2:
            if self.trust.get(opp, 0.5) < 0.5:
                return True

        # New: If we've been cooperating a lot with this opponent, occasional defection
        if opp in self.coop_rate_with_us and self.coop_rate_with_us[opp][1] > 5:
            coop_rate = self.coop_rate_with_us[opp][0] / self.coop_rate_with_us[opp][1]
            if coop_rate > 0.9 and self.reputation_good:
                # Defect occasionally to exploit, but maintain trust
                if random.random() < 0.1:
                    return True

        # Decision threshold: slightly more aggressive
        return self.trust.get(opp, 0.5) >= 0.25

