        # Enhanced exploitation of pure cooperators with better reputation management
        total_opp = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_opp > 10:
            def_rate = self.defect_count.get(opp, 0) / total_opp
            if def_rate < 0.05:
                if opp not in self.exploit_schedule:
                    self.exploit_schedule[opp] = 0
                # More aggressive when reputation good, but maintain a minimum cooperation rate
                prob_defect = 0.95 if self.reputation_good else 0.75
                # Reduce defection if we've defected too many times in a row
                if self.exploit_schedule.get(opp, 0) >= 2:
                    prob_defect = 0.4
                # Also consider opponent's recent retaliation to avoid getting punished
                if self.opp_retaliation.get(opp, 0) > 0:
                    prob_defect = 0.2
                if random.random() < prob_defect:
                    return True
                else:
                    return False
            elif def_rate > 0.7:
                self.trust[opp] = 0.0
                return False

        # Reputation engineering: rebuild reputation quickly when low
        if self.my_total_coops + self.my_total_defects > 0:
            if not self.reputation_good and my_reputation < 0.45:
                if self.trust.get(opp, 0.5) < 0.5:
                    return True

        # Strategic exploitation: defect when reputation high and opponent cooperative, but be wary of retaliation
        if self.reputation_good and self.trust.get(opp, 0.5) > 0.85:
            # Check if opponent retaliates after our defection
            if opp in self.opp_retaliated_after_def and self.opp_retaliated_after_def[opp] > 0.5:
                # Opponent retaliates, so defect less often
                prob_defect = 0.4
            else:
                prob_defect = 0.9
            if random.random() < prob_defect:
                return False

        # Avoid defectors
        if opp in self.def_rate_against_us and self.def_rate_against_us[opp] > 0.5:
            return False

        # If opponent has defected recently against us, defect
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False

        # If opponent's global cooperation rate is very high, defect more often
        total_global = self.defect_count.get(opp, 0) + self.coop_count.get(opp, 0)
        if total_global > 20:
            global_def_rate = self.defect_count.get(opp, 0) / total_global
            if global_def_rate < 0.08:
                # Defect with high probability but sometimes cooperate to maintain reputation
                if random.random() < 0.95:
                    return True

        # If our reputation is low, cooperate more to rebuild
        if self.my_reputation_count > 10:
            if not self.reputation_good and my_reputation < 0.4:
                return True

        # NEW: Enhanced reciprocity with forgiveness mechanism
        if opp in self.coop_since_def and self.coop_since_def[opp] >= 2:
            # Opponent has cooperated twice since our last defection, forgive and cooperate
            return True

        # NEW: Avoid being exploited by alternating defectors
        if opp in self.opp_last_5_actions:
            actions = self.opp_last_5_actions[opp]
            if len(actions) >= 5:
                # Check for alternating pattern
                if all(actions[i] != actions[i+1] for i in range(4)):
                    # Alternating defector - defect to punish
                    return False

        # NEW: Adaptive trust based on opponent's recent global behavior
        if opp in self.opp_recent_global_coop:
            recent_global = self.opp_recent_global_coop[opp]
            if len(recent_global) >= 3:
                recent_coop_rate = sum(recent_global) / len(recent_global)
                if recent_coop_rate > 0.9:
                    # Very cooperative recently - exploit
                    if random.random() < 0.8:
                        return True
                elif recent_coop_rate < 0.2:
                    # Very defective recently - avoid
                    return False

        # Decision threshold: slightly more aggressive
        return self.trust.get(opp, 0.5) >= 0.25

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        d_act = (donor_action == 'cooperate')
        r_act = (recipient_action == 'cooperate')
        if donor_id not in self.defect_count:
            self.defect_count[donor_id] = 0
            self.coop_count[donor_id] = 0
        if d_act:
            self.coop_count[donor_id] += 1
        else:
            self.defect_count[donor_id] += 1
        total = self.defect_count.get(donor_id, 0) + self.coop_count.get(donor_id, 0)
        if total > 0:
            self.coop_rate_others[donor_id] = self.coop_count.get(donor_id, 0) / total
            self.opp_total[donor_id] = total
            self.opp_def_rate[donor_id] = self.defect_count.get(donor_id, 0) / total
        if donor_id not in self.opp_recent_global_coop:
            self.opp_recent_global_coop[donor_id] = []
        self.opp_recent_global_coop[donor_id].append(d_act)
        if len(self.opp_recent_global_coop[donor_id]) > 5:
            self.opp_recent_global_coop[donor_id] = self.opp_recent_global_coop[donor_id][-5:]
        if donor_id not in self.opp_recent_def_global:
            self.opp_recent_def_global[donor_id] = []
        self.opp_recent_def_global[donor_id].append(not d_act)
        if len(self.opp_recent_def_global[donor_id]) > 5:
            self.opp_recent_def_global[donor_id] = self.opp_recent_def_global[donor_id][-5:]
        if donor_id not in self.opp_global_coop:
            self.opp_global_coop[donor_id] = [0, 0]
        if d_act:
            self.opp_global_coop[donor_id][0] += 1
        self.opp_global_coop[donor_id][1] += 1

        # Track last 5 actions for stability analysis
        if donor_id not in self.opp_last_5_actions:
            self.opp_last_5_actions[donor_id] = []
        self.opp_last_5_actions[donor_id].append(d_act)
        if len(self.opp_last_5_actions[donor_id]) > 5:
            self.opp_last_5_actions[donor_id] = self.opp_last_5_actions[donor_id][-5:]

        # Track last 10 actions for more robust modeling
        if donor_id not in self.opp_last_10_actions:
