                penalty = 0.2 if streak >= 2 else 0.1
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - penalty)

            # Analyze opponent's forgiveness and betrayal patterns
            if other not in self.opp_betrayal_prob:
                self.opp_betrayal_prob[other] = [0, 0]  # [defections, total]
                self.opp_forgiveness[other] = 0
                self.opp_punishment_count[other] = 0
                self.opp_streak_after_def[other] = 0

            if not my_act:
                # We defected; check opponent's response
                if opp_act:
                    self.opp_forgiveness[other] += 1
                    self.opp_streak_after_def[other] = 0
                else:
                    self.opp_punishment_count[other] += 1

