            def_rate = self.defect_count.get(opp, 0) / total_opp
            coop_rate = 1 - def_rate
            if coop_rate > 0.9:
                # Very cooperative opponent: defect with high probability, but not always
                # to avoid damaging reputation too much
                if self.reputation_good:
