                self.opp_rep_quality[opp] = 1.0 - global_def_rate
                # Recent reputation (last 10 actions)
                recent = self.opp_last_10_actions.get(opp, [])
                if len(recent) >= 5:
                    recent_def = sum(1 for a in recent if not a) / len(recent)
                    self.opp_rep_quality_recent[opp] = 1.0 - recent_def
        else:
            self.opp_rep_quality[opp] = 0.5
            self.opp_rep_quality_recent[opp] = 0.5

        # My reputation assessment
        my_total = self.my_total_coops + self.my_total_defects
        if my_total > 0:
            my_rep = self.my_total_coops / my_total
            if len(self.my_recent_reputation) > 0:
                recent_coops = sum(1 for a in self.my_recent_reputation if a)
                my_rep = recent_coops / len(self.my_recent_reputation)
            self.reputation_good = my_rep > 0.65
        else:
            my_rep = 0.5
            self.reputation_good = False

        # Detect pure cooperators (global defection rate very low)
        pure_coop = False
        if total_global > 15 and global_def_rate < 0.05:
            pure_coop = True

        # If pure cooperator, exploit aggressively but manage reputation
        if pure_coop:
            # Check if opponent retaliates after our defection
            retaliation = self.opp_retaliation_rate.get(opp, 0.0)
            # Check recent defections against this opponent
            key = (self.agent_id, opp)
            my_defs_against = 0
            my_coops_against = 0
            if key in self.own_interactions:
                for my_act, opp_act in self.own_interactions[key]:
                    if not my_act:
                        my_defs_against += 1
                    else:
                        my_coops_against += 1
            total_against = my_defs_against + my_coops_against
            if total_against > 0:
                my_def_rate_against = my_defs_against / total_against
            else:
                my_def_rate_against = 0.0

            # If we have a good reputation, defect with high probability
            if self.reputation_good and my_rep > 0.7:
                # If opponent doesn't retaliate much, defect almost always
                if retaliation < 0.3:
                    prob_defect = 0.95
                else:
                    prob_defect = 0.7
                # But if we've been defecting a lot recently, cooperate to rebuild rep
                if my_def_rate_against > 0.8:
                    prob_defect = 0.4
                # If opponent has defected at all recently, reduce defection
                recent_opp = self.recent_opp_actions.get(opp, [])
                if recent_opp and not recent_opp[-1]:
                    prob_defect = 0.2
                if random.random() < prob_defect:
                    return True
                else:
                    return False
            else:
                # Reputation not good, cooperate to build it
                # But still exploit occasionally if opponent is very cooperative
                if my_rep < 0.5:
                    # Rebuild reputation by cooperating
                    return True
                else:
                    # Moderate exploitation
                    if random.random() < 0.6:
                        return True
                    else:
                        return False

        # Avoid known defectors (global defection rate high)
        if total_global > 10 and global_def_rate > 0.7:
            return False

        # If opponent has defected recently against us, defect
        recent = self.recent_opp_actions.get(opp, [])
        if len(recent) >= 2 and not recent[-1] and not recent[-2]:
            return False

        # If opponent's recent reputation is poor, defect to avoid being exploited
        if opp in self.opp_rep_quality_recent:
            if self.opp_rep_quality_recent[opp] < 0.3:
                return False

        # Reputation engineering: if my reputation is low, cooperate to rebuild
        if my_total > 10 and my_rep < 0.4:
            # If opponent is cooperative, cooperate to build rep
            if self.trust.get(opp, 0.5) > 0.5:
                return True
            # If opponent is defector, defect but we're already in trouble
            return False

        # Strategic decision based on trust and opponent's behavior
        if opp not in self.trust:
            # Initialize trust based on opponent's global rep
            if total_global > 0:
                if global_def_rate < 0.2:
                    self.trust[opp] = 0.7
                elif global_def_rate < 0.5:
                    self.trust[opp] = 0.5
                else:
                    self.trust[opp] = 0.3
            else:
                self.trust[opp] = 0.6

        # Update trust based on last interaction
        key = (self.agent_id, opp)
        if key in self.own_interactions:
            my_actions = [a[0] for a in self.own_interactions[key]]
            opp_actions = [a[1] for a in self.own_interactions[key]]
            if opp_actions:
                if opp_actions[-1]:
                    self.trust[opp] = min(1.0, self.trust.get(opp, 0.5) + 0.15)
                else:
                    streak = self.opp_def_streak.get(opp, 0)
                    if streak >= 2:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.25)
                    else:
                        self.trust[opp] = max(0.0, self.trust.get(opp, 0.5) - 0.15)

        # If trust is high, cooperate normally
        if self.trust.get(opp, 0.5) > 0.7:
            return True

        # If trust is moderate, use tit-for-tat with forgiveness
        if self.trust.get(opp, 0.5) > 0.4:
            if len(recent) > 0 and not recent[-1]:
                return False
            else:
                return True

        # Otherwise defect
        return False

